export default {
  // 数据查看
  type: 'dialog',
  id: 'dialog_meta_set_codeeditor',
  width: '80%',
  title: Tech.$t('seniorTable.dataViewing'),
  display: false,
  hasFooter: true,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  items: [
    {
      type: 'form',
      created: (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        let tableVm = vm.$select(idPre + 'table_main_table')
        vm.$ds.form.codeeditor = JSON.stringify(tableVm.$ds.tableData.data)
      },
      dataSource: {
        codeeditor: ''
      },

      items: [
        {
          type: 'codeeditor',
          id: 'dialog_meta_set_codeeditor_form_item',
          name: 'codeeditor',
          height: '500px'
        }
      ]
    }
  ]
}
