import { approvalRejectdialogView } from './approvalReject'

export default {
  type: 'tabs',
  id: 'approval_tabs_node',
  className: 'approval_tabs_process_nodes', //放在tabs上才生效
  close: false,
  activeWork: true, // 切换到的tab才生效
  style: {
    width: '100%'
  },
  items: [
    {
      type: 'container',
      id: 'approval_tabs_process_cards',
      name: `${Tech.$t('workflow.process')}`,
      style: {
        padding: '0.1rem',
        height: '100%',
        overflow: 'auto'
      },
      created: (vm) => {
        const processDatas = vm.$ds.processDatas
        const approvalHistories = processDatas?.approvalHistories || []
        const approvalNodes = processDatas?.approvalNodes || []
        const formData = processDatas?.formData || {}
        // 前置处理
        let renderArr = [],
          groupMap = new Map() // {groupId: []}
        approvalHistories.forEach((item) => {
          if (item.groupId) {
            if (!groupMap.has(item.groupId)) {
              groupMap.set(item.groupId, [item])
            } else {
              let tArr = groupMap.get(item.groupId)
              tArr.push(item) && groupMap.set(item.groupId, tArr)
            }
          } else {
            groupMap.set('NoGroup_' + item.id, [item])
          }
        })

        groupMap.forEach((value, key) => {
          renderArr.push(value)
        })

        const array = renderArr?.map((item) => {
          const resItem = {
            type: 'container',
            items: [
              {
                type: 'container',
                style: {
                  background: '#FFFFFF',
                  'border-radius': '0.1rem',
                  marginBottom: '0.08rem',
                  padding: '0.1rem',
                  border: '1px solid #d9d9d9',
                  borderLeft: '5px solid #67c23a'
                },
                formatItem: (row, node) => {
                  // 审核详情左边框样式border颜色处理
                  item.map((gItem, index) => {
                    if (gItem?.actionType === 'Back') {
                      node.style.borderLeft = '5px solid #f56c6c'
                    } else if (!gItem.isExecuted && gItem.isCurrentNode) {
                      node.style.borderLeft = '5px solid #F7AC03'
                    } else if (!gItem.isExecuted && !gItem.isCurrentNode) {
                      node.style.borderLeft = '5px solid #E1E7EC'
                    }
                  })
                  if (item[0].metaType === 'END' || item[0].metaType === 'START') {
                    // node.style.background = 'transparent'
                    delete node.style.borderLeft
                    delete node.style.padding
                    delete node.style.border
                  }

                  return node
                },
                items: []
              }
            ]
          }
          const getDefaultData = (model, fromDataId) => {
            const formDataList = formData.formDataList || []
            if (fromDataId) {
              const fromProcessData = formDataList.find((item) => item?.processId == fromDataId)
              return fromProcessData?.[model] || {}
            } else {
              const formDataInfo = formDataList.find(
                (item) => model in item && item.processModel === model
              )

              if (formDataInfo?.processId && !fromDataId) {
                return {}
              }

              return formDataInfo?.[model] || {}
            }
          }

          const setDefaultData = (singleData, model, disabled = true, fromDataId) => {
            const data = getDefaultData(model, fromDataId)
            singleData.items.map((srcItem) => {
              vm.$cmd.meta.nestObj(vm, srcItem, 'items', (vm, objItem) => {
                if (objItem?.name) {
                  if (objItem?.name.indexOf('.') > -1) {
                    objItem.name = objItem.name.replace(/\./g, '___') // 将点替换成三个下划线 否则会引起表单组件报错
                  }
                  objItem.defaultValue = data[objItem.name]
                  if (objItem?.disabled) {
                    objItem.disabled = true
                  } else {
                    objItem.disabled = disabled
                  }
                }
                return objItem
              })
            })
          }

          item.map((gItem, gIndex) => {
            const cardItem = {
              type: 'container',
              className: 'approval_card_item_cls',
              items: [
                {
                  type: 'container',
                  class: 'card-top',
                  items: [
                    {
                      type: 'container',
                      style: {
                        width: '10px',
                        height: '10px',
                        border: '3px solid',
                        borderColor: '#67C23A',
                        borderRadius: '50%',
                        display: 'none',
                        background: '#ffffff'
                      },
                      formatItem: (row, node) => {
                        //
                        if (gItem.metaType === 'END' || gItem.metaType === 'START') {
                          node.style.display = 'inline-block'
                        }
                        if (!gItem.isExecuted && !gItem.isCurrentNode) {
                          node.style.borderColor = '#E1E7EC'
                        }

                        return node
                      }
                    },
                    //流程节点名
                    {
                      type: 'text',
                      value: '',
                      style: {
                        marginLeft: '5px',
                        color: '#999999',
                        'font-size': '12px'
                      },
                      formatItem: (row, node) => {
                        node.value = gItem.name
                        if (node.value) {
                          node.style.marginLeft = '5px'
                        }
                        if (gItem.metaType === 'END' || gItem.metaType === 'START') {
                          node.style.color = '#333333'
                          node.style.fontSize = '14px'
                        }
                        return node
                      }
                    },
                    //流程状态
                    {
                      type: 'text',
                      value: '',
                      style: {
                        color: '#67c23a',
                        background: '#ddf5d2',
                        fontSize: '12px',
                        borderRadius: '4px',
                        marginLeft: '5px'
                      },
                      formatItem: (row, node) => {
                        // tag
                        node.value = gItem.approvalAction
                        if (gItem.actionType === 'Back') {
                          node.style.background = '#fef0f0'
                          node.style.color = '#f56c6c'
                        } else if (!gItem.isExecuted && gItem.isCurrentNode) {
                          node.style.background = '#FFF0CD'
                          node.style.color = '#F7AC03'
                        } else if (!gItem.isExecuted && !gItem.isCurrentNode) {
                          node.style.background = '#E8E8E8'
                          node.style.color = '#949494'
                        }
                        if (node.value) {
                          node.style.padding = '3px 8px'
                        }
                        return node
                      }
                    },
                    {
                      type: 'container',
                      style: {
                        marginTop: '8px',
                        overflowY: 'auto',
                        maxHeight: '2.5rem'
                      },
                      items: [
                        //审批人
                        {
                          type: 'text',
                          value: '',
                          style: {},
                          formatItem: (row, node) => {
                            node.value = gItem.assignee?.label
                            if (node.value && gItem.metaType !== 'END') {
                              node.style = {
                                padding: '1px 5px',
                                color: '#333333',
                                borderRadius: '4px',
                                wordWrap: 'break-word',
                                whiteSpace: 'normal',
                                lineHeight: '30px'
                              }
                            }
                            return node
                          }
                        },
                        {
                          type: 'text',
                          value: '',
                          style: {
                            float: 'right',
                            color: '#999999',
                            opacity: '1',
                            fontSize: '12px',
                            'font-weight': 400,
                            'font-family': 'PingFang SC'
                          },
                          formatItem: (row, node) => {
                            node.value = gItem.endTime
                            return node
                          }
                        }
                      ]
                    }
                  ]
                },
                //审批意见
                {
                  type: 'container',
                  style: {
                    paddingLeft: '5px',
                    marginTop: '5px',
                    color: '#333333',
                    'word-wrap': 'break-word',
                    marginBottom: '10px'
                    // 'white-space': 'pre-wrap'
                  },
                  formatItem: (row, node) => {
                    node.items[0].value = gItem.message || gItem.approvalAction
                    if (gItem.metaType !== 'END' && gItem.metaType !== 'START') {
                      node.style.paddingTop = '15px'
                    }
                    if (!gItem.message) {
                      node.style.color = '#999999'
                    }
                    return node
                  },
                  items: [
                    {
                      type: 'text',
                      value: ''
                    }
                  ]
                }
              ]
            }
            const views = gItem.views
            const nodeInfo = approvalNodes.find((nodeInfo) => nodeInfo.id === gItem.id)
            const formMain = vm.$cmd.meta.getView(vm, 'formMain', vm.$ds.idPre + '_' + gItem.id)
            if (nodeInfo?.processForm) {
              formMain.style.marginLeft = '10px'
              let sigleData = vm.$cmd.meta.formFormat.initForm(
                vm,
                nodeInfo?.processForm?.views?.form,
                nodeInfo?.processForm?.fields
              )

              // const formDataList = formData.formDataList || []
              // const formDataInfo = formDataList.find((item) => nodeInfo.processForm.model in item)
              // const data = formDataInfo[nodeInfo.processForm.model]

              // 表单数据回显
              // let sigleListItem = []
              // sigleData.items.map((srcItem) => {
              //   vm.$cmd.meta.nestObj(vm, srcItem, 'items', (vm, objItem) => {
              //     if (objItem?.name) {
              //       if (objItem?.name.indexOf('.') > -1) {
              //         objItem.name = objItem.name.replace(/\./g, '___') // 将点替换成三个下划线 否则会引起表单组件报错
              //       }
              //       objItem.defaultValue = data[objItem.name]
              //       objItem.disabled = true
              //     }
              //     return objItem
              //   })
              // })

              setDefaultData(sigleData, nodeInfo.processForm.model, true, nodeInfo?.fromDataId)

              formMain.items = sigleData.items

              cardItem.items.push(formMain)
            }
            if (views?.form?.body?.columns?.length) {
              // const formMain = vm.$cmd.meta.getView(vm, 'formMain', vm.$ds.idPre)
              formMain.style.background = '#FFFFFF'
              const data = vm.$cmd.meta.formFormat.initForm(vm, views?.form, gItem.fields)
              let listItems = []
              if (data.items) {
                data.items.map((srcItem) => {
                  vm.$cmd.meta.nestObj(vm, srcItem, 'items', (vm, objItem) => {
                    if (objItem?.name) {
                      listItems.push(objItem)
                    }
                  })
                })
              }
              if (nodeInfo?.processForm) {
                formMain.style.marginLeft = '10px'
                let sigleData = vm.$cmd.meta.formFormat.initForm(
                  vm,
                  nodeInfo?.processForm?.views?.form,
                  nodeInfo?.processForm?.fields
                )

                setDefaultData(sigleData, nodeInfo.processForm.model, false, nodeInfo?.fromDataId)
                formMain.items = sigleData.items
              } else {
                formMain.items = data.items
              }

              formMain.id = vm.$ds.idPre + 'approval_process_nodeItem_form_' + gItem.id
              const copyFormMainID = window.Tech._cloneDeep(formMain.id)
              // 不显示表单的label
              // if (formMain?.items?.[0]?.items?.[0]) {
              //   formMain.items[0].items[0].text = ''
              // }
              let hasId = cardItem.items.some((el) => el?.id == formMain?.id)
              if (!hasId) {
                // 防止重复追加节点
                cardItem.items.push(formMain)
              }
              // 有表单项才显示按钮
              if (views?.form?.body?.buttons?.length) {
                let flowBtns = vm.$cmd.meta.formFormat.formatFlowViewBtns(vm, {
                  view: views?.form,
                  permissions: ['all']
                })
                flowBtns.forEach((btn) => {
                  btn._formMainID = copyFormMainID
                  const table_detail = vm.$select(vm.$ds.idPre + 'table_detail')
                  const approval_empty_container = vm.$select(
                    vm.$ds.idPre + 'approval_empty_container'
                  )
                  const detail_header = vm.$select(vm.$ds.idPre + 'form_main_detail_top_header')
                  if (
                    btn.btnConfig.actionType?.toLowerCase() === 'assign' ||
                    btn.btnConfig.actionType?.toLowerCase() === 'delegate'
                  ) {
                    btn.bind_on_click = async (params) => {
                      let { self: vm } = params
                      // 校验必填
                      const formMainID = vm.$select(btn.id)?.data?._formMainID
                      const approvalHistoriesForm = vm.$select(formMainID)
                      if (approvalHistoriesForm?.instance) {
                        await approvalHistoriesForm.instance.submit()
                      }
                      // 追加转办和加签弹窗
                      let footer_content = vm.$select('container_meta_footer_content')
                      let dialogView = {
                        type: 'container',
                        id: vm.$ds.idPre + 'assign_delegate_container',
                        display: true,
                        items: [],
                        view: {
                          created: {
                            _parentId: vm.$ds.idPre + 'assign_delegate_container',
                            openView: {
                              title:
                                btn.btnConfig.actionType?.toLowerCase() === 'assign'
                                  ? Tech.$t('workflow.transfer')
                                  : Tech.$t('workflow.countersign'),
                              showType: 'dialog',
                              preId: 'work_flow_choose_rbac_user_',
                              app: 'sie-iidp-tenant',
                              model: 'rbac_user',
                              type: 'wf_process_user_grid,wf_process_user_search',
                              checkbox: 'single'
                            },
                            bind_on_opreates: async (params) => {
                              const { self: vm, value } = params
                              if (value?.type == 'cancel') {
                                vm.data.display = false
                              }
                              if (value?.type == 'confirm') {
                                let userTable = vm.$select(
                                  'work_flow_choose_rbac_user_table_main_table'
                                )
                                let checkedDataList = userTable.$ds.checkedDataList
                                if (!checkedDataList.length) {
                                  window.ELEMENT.Message.error(Tech.$t('workflow.selectUser'))
                                } else {
                                  const formMainID = vm.$select(btn.id)?.data?._formMainID
                                  const approvalHistoriesForm = vm.$select(formMainID)
                                  const approvalFormRes =
                                    await approvalHistoriesForm.instance.submit()
                                  let loadingInstance = window.ELEMENT.Loading.service()
                                  let processData = null
                                  if (nodeInfo?.processForm && nodeInfo?.isCurrentNode) {
                                    processData = { ...approvalFormRes }
                                  }
                                  const reqParams = {
                                    model: btn.btnConfig?.model,
                                    app: processDatas?.app,
                                    service: btn?.service,
                                    args: {
                                      action: btn?.action,
                                      serviceVersion: processDatas?.serviceVersion,
                                      id: btn.btnConfig.userTaskId || '',
                                      userId: checkedDataList[0]?.id,
                                      approved: {
                                        message: approvalFormRes?.message || ''
                                      }
                                    }
                                  }
                                  if (processData) {
                                    reqParams.args.processApproved = processData
                                  }
                                  table_detail
                                    .request('otherService', reqParams)
                                    .then((res) => {
                                      if (!res.error) {
                                        vm.data.display = false
                                        if (res?.data?.rootInstanceId) {
                                          detail_header.$cmd.preBack({
                                            self: approval_empty_container.parent
                                          }) // 返回主页
                                          window.ELEMENT.Message.success(
                                            Tech.$t('common.submitSuccess')
                                          )
                                        }
                                      }
                                      loadingInstance.close()
                                    })
                                    .catch((err) => {
                                      vm.data.display = false
                                      loadingInstance.close()
                                    })
                                }
                              }
                            }
                          }
                        }
                      }
                      footer_content.app.updatePageNode(dialogView, footer_content, () => {
                        footer_content.data.items.push(dialogView)
                      })
                    }
                  } else {
                    btn.bind_on_click = async (params) => {
                      // 点击批准、拒绝等按钮
                      const approvalLeftForm = vm.$select(
                        vm.$ds.idPre + 'form_main_detail_top_common'
                      )
                      // 展开折叠面板
                      if (approvalLeftForm?.data?.items?.length) {
                        approvalLeftForm.data.items.forEach(item => {
                          if (item?.type === 'collapse') {
                            const collapse = vm.$select(item.id);
                            const firstItemId = collapse?.data?.items?.[0]?.id;
                            if (firstItemId) {
                              collapse.data.activeNames = [firstItemId];
                            }
                          }
                        });
                      }
                      const table_main = vm.$select(vm.$ds.idPre + 'table_main')
                      const { fields, views } = table_main.$ds.loadFlowView
                      const approvalTemplate = vm.$select(vm.$ds.idPre + 'approval_process_detail')
                      const formMainID = vm.$select(btn.id)?.data?._formMainID
                      const approvalHistoriesForm = vm.$select(formMainID)
                      // 仅 同意/提交 需要校验
                      let actionCode = btn.btnConfig.code?.toLowerCase()
                      const methodName = ['agree', 'submit'].includes(actionCode)
                        ? 'submit'
                        : 'noValidateSubmit'

                      // 校验表单并定位到 不通过的字段
                      methodName === 'submit' &&
                        approvalLeftForm?.instance?.verifyFormAndScrollView?.()
                      let leftFormRes = await approvalLeftForm.instance[methodName]()
                      let submitRes = {}
                      //禁用的表单项 无需提交
                      approvalTemplate.$ds.leftSubmitItem.map((sItem) => {
                        const DataStr = leftFormRes[sItem]
                        if (sItem.indexOf('___') > -1) {
                          sItem = sItem.split('___')[1] //提交的时候去掉模型前缀
                        }
                        submitRes[sItem] = DataStr === '' ? null : DataStr
                        // submitRes[sItem] = leftFormRes[sItem] === '' ? null : leftFormRes[sItem]
                      })
                      approvalTemplate.$ds.leftFormId &&
                        (submitRes.id = approvalTemplate.$ds.leftFormId)
                      let row = submitRes
                      row = await vm.$cmd.mergeErFiledValue(vm, row)
                      for (const key in row) {
                        if (Object.hasOwnProperty.call(row, key)) {
                          if (key.indexOf('filter_') > -1 || key === 'rowIndex') {
                            delete row[key]
                          }
                          // 保存时删除保留的辅助字段
                          const reserveProps = window.techUi?.VxeTable?.$TABLE_ROW_RESERVE_PROPS
                          if (reserveProps && Object.values(reserveProps).includes(key)) {
                            delete row[key]
                          }
                        }
                      }
                      let distRow = vm.$cmd.meta.formFormat.transformParams(vm, row)
                      const obj = window.Tech.formatFormSublimtField(fields, distRow)
                      for (const key in obj) {
                        if (Object.hasOwnProperty.call(obj, key)) {
                          if (key.indexOf('__values') > -1) {
                            delete obj[key]
                          }
                        }
                      }
                      const approvalFormRes = await approvalHistoriesForm.instance.submit()
                      let processData = null

                      // 终止按钮需要必填审批意见
                      if (approvalFormRes.hasOwnProperty('message') && !approvalFormRes.message && actionCode == 'stop') {
                        window.ELEMENT.Message.error(Tech.$t('workflow.opinion'))
                        return
                      }
                      if (nodeInfo?.processForm && nodeInfo?.isCurrentNode) {
                        processData = { ...approvalFormRes }
                      } else if (!approvalFormRes.message && btn.btnConfig.requiredMessage) {
                        window.ELEMENT.Message.error(Tech.$t('workflow.opinion'))
                        return
                      }

                      const reqParams = {
                        model: btn.btnConfig?.model, //外层模型取按钮的model
                        app: processDatas?.app,
                        service: btn?.service,
                        args: {
                          action: btn?.action,
                          actionCode: btn?.btnConfig?.code,
                          serviceVersion: processDatas?.serviceVersion,
                          id: table_detail?.$ds?.mainTableRowData?.id || '',
                          //form-tab表单数据
                          values: obj,
                          // 左侧表单数据
                          // data: {
                          //   [processDatas?.form?.model]: submitRes
                          // },

                          approved: {
                            message: approvalFormRes?.message || ''
                          }
                        }
                      }

                      if (processData) {
                        reqParams.args.processApproved = processData
                      }

                      // 驳回到任意节点 - 弹窗 - 选择节点
                      if (
                        btn?.btnConfig?.rejectParentStatus === '3' ||
                        btn?.btnConfig?.retrialStatus === '2'
                      ) {
                        const result = await new Promise((resolve) => {
                          let tableDetail = vm.$select(vm.$ds.idPre + 'table_detail')
                          let view = approvalRejectdialogView(
                            vm,
                            btn?.btnConfig?.userTaskId,
                            resolve
                          )
                          // 追加节点
                          view.btnConfig = btn.btnConfig // 赋值给弹窗
                          tableDetail.app.updatePageNode(view, tableDetail, () => {
                            const index = tableDetail.data.items.findIndex(
                              (item) => item.id === vm.$ds.idPre + 'approval_reject_dialog'
                            )
                            // 如果存在则删除再重新添加，否则会导致关闭后无法重新打开
                            if (index !== -1) {
                              // 存在则删除再重新添加
                              tableDetail.data.items.splice(index, 1)
                              setTimeout(() => {
                                tableDetail.data.items.push(view)
                              }, 0)
                            } else {
                              tableDetail.data.items.push(view)
                            }
                          })
                        })
                        if (result === false) {
                          return
                          vm.instance.$message.error('取消了驳回')
                        } else {
                          // 增加参数
                          const rejectForm = vm.$select('dialog_approval_reject_form')
                          reqParams.args.rejectCode = rejectForm?.$ds?.form?.rejectNode
                          reqParams.args.retrialStatus = rejectForm?.$ds?.form?.retrialStatus
                        }
                      }

                      // 增加驳回参数
                      if (table_detail.$ds?.processinstanceId) {
                        reqParams.args.id = table_detail.$ds?.processinstanceId
                        delete table_detail.$ds?.processinstanceId
                      }

                      // 终止不需要传入values、传参会触发模型的必填校验
                      if (btn?.btnConfig?.code === 'stop') {
                        delete reqParams?.args?.values
                      }
                      let loadingInstance = window.ELEMENT.Loading.service()
                      vm.request('otherService', reqParams)
                        .then((res) => {
                          loadingInstance.close()
                          if (res?.data?.rootInstanceId) {
                            const _vm = vm.$select(vm.$ds.idPre + 'approval_empty_container')
                            detail_header.$cmd.preBack({ self: _vm.parent }) // 返回主页
                            window.ELEMENT.Message.success(Tech.$t('common.submitSuccess'))
                          }
                        })
                        .catch((err) => loadingInstance.close())
                    }
                  }
                })

                if (flowBtns.length > 4) {
                  const moreBtn = {
                    type: 'meta-dropdown',
                    id: 'work_flow_more_dropdown',
                    css: `.moreBtnsGroup .el-button + .el-button {margin-left: 0;}`,
                    style: {
                      width: '0.45rem',
                      marginLeft: '10px'
                    },
                    dropdownStyle: {
                      //弹窗的style样式
                      width: '1rem',
                      padding: '0.1rem 0',
                      textAlign: 'center',
                      marginTop: '0.1rem',
                      position: 'relative'
                    },
                    placement: 'bottom',
                    items: [
                      {
                        name: 'defaultBtn', // 'customBtn',自定义的按钮，可以是任意的组件
                        buttonClose: {
                          text: Tech.$t('workflow.more'),
                          icon: 'el-icon-arrow-down'
                        },
                        buttonOpen: {
                          text: Tech.$t('workflow.more'),
                          icon: 'el-icon-arrow-up'
                        }
                      },
                      {
                        type: 'container',
                        className: 'moreBtnsGroup',
                        items: []
                      }
                    ]
                  }
                  for (var i = 0; i < flowBtns.length; i++) {
                    if (i > 3) {
                      flowBtns[i].options.type = 'text'
                      flowBtns[i].style = {
                        background: '#ffffff',
                        display: 'block'
                        // fontSize: '0.15rem'
                      }
                      moreBtn.items[1].items.push(flowBtns[i])
                    }
                  }
                  flowBtns = flowBtns.splice(0, 4)
                  flowBtns.push(moreBtn)
                }

                const btnView = {
                  type: 'container',
                  style: { display: 'flex', 'justify-content': 'flex-end', marginRight: '15px' },
                  id: vm.$ds.idPre + 'tabs_node_btns_container',
                  mounted: (vm) => {
                    try {
                      // 获取流程父节点
                      let cards = document.getElementById(
                        vm.$ds.idPre + 'approval_tabs_process_cards'
                      )
                      if (cards) {
                        // 获取按钮容器
                        const btns = document.getElementById(vm.data.id)
                        const cardsHeight = cards?.offsetHeight
                        const btnsBottom = btns?.getBoundingClientRect()?.bottom
                        // 设置流程父节点的滚动条
                        if (btnsBottom > cardsHeight) {
                          cards.scrollTop = btnsBottom - cardsHeight
                        }
                      }
                    } catch (e) {}
                  },
                  items: flowBtns
                }

                vm.app.updatePageNode(btnView, resItem.items, () => {
                  flowBtns.length && cardItem.items.push(btnView)
                })
              }
            }

            // 虚线
            if (gIndex < item.length - 1) {
              cardItem.items.push({
                type: 'container',
                style: {
                  margin: '15px 0',
                  'border-top': '1px dashed #D9D9D9'
                }
              })
            }
            // 内部节点放到后面追加
            vm.app.updatePageNode(cardItem, resItem, () => {
              setTimeout(() => {
                resItem.items[0].items.push(cardItem)
              })
            })
          })
          return resItem
        })

        vm.data.items = []
        array.map((item) => {
          vm.app.updatePageNode(item, vm, () => {
            vm.data.items.push(item)
          })
        })
      },
      items: []
    },
    {
      type: 'container',
      id: 'approval_tabs_process_nodes',
      // className: 'approval_tabs_process_nodes',放到这里的className不生效
      name: `${Tech.$t('workflow.node')}`,
      style: {
        padding: '0.15rem',
        height: '100%',
        overflow: 'auto'
      },
      css: `
            .approval_tabs_process_nodes .el-tabs__item.is-top {border-top-left-radius: 0.06rem;border-top-right-radius: 0.06rem;padding: 0 0.16rem !important;margin-right: 0.02rem;}
            .approval_tabs_process_nodes .el-tabs__item {height: 0.32rem !important;line-height: 0.32rem !important;font-size: 14px;font-weight: 600;color: #677177;background: #f5f7fa !important;}
            .approval_tabs_process_nodes .el-tabs__content {background-color: #ffffff !important;}
            .approval_tabs_process_nodes .el-tabs__header {margin-bottom: 1px;height: 0.32rem !important;background: rgb(225, 231, 236) !important;}
            .approval_tabs_process_nodes .el-tabs__item.is-active {background: var(--tabs-active-bg, #ffffff) !important;color: var(--tabs-active-color, #ad053d) !important;}
            .approval_tabs_process_nodes .el-tabs__active-bar {background: #ffffff !important;}
            .approval_tabs_process_nodes .el-step__title {color: #999999; font-size: 13px; font-weight: 400}
            .approval_tabs_process_nodes .iconfont {font-size: 18px}
            .approval_tabs_process_nodes .iconfont.icon-chenggong {color: #67C23A}
            .approval_tabs_process_nodes .iconfont.icon-chaoshi {color: #F7AC03}
            .approval_tabs_process_nodes .iconfont.icon-weishenpi {color: #999999}
            .approval_tabs_process_nodes .el-step__line .el-step__line-inner {border-color: #999999}
            .approval_tabs_process_nodes .el-step__line {background-color: #999999}
            .approval_tabs_process_nodes .el-step__description{font-size: 14px;color: #333333}
            .approval_tabs_process_nodes .el-step.is-vertical{display:flex;align-items:center}
            .approval_tabs_process_nodes .el-step.is-vertical .el-step__line{width: 0.01rem;left:0.09rem}
            .approval_tabs_process_nodes .el-step.is-vertical .el-step__icon.is-icon{width:0.18rem;height:0.18rem}`,
      items: [
        {
          type: 'approval-steps',
          // active: 0,
          direction: 'vertical',
          space: '100px',
          items: [],
          created: (vm) => {
            const approvalNodes = vm.$ds.processDatas?.approvalNodes || []
            // 前置处理
            let renderArr = [],
              groupMap = new Map() // {groupId: []}

            approvalNodes.forEach((item) => {
              if (item.groupId) {
                if (!groupMap.has(item.groupId)) {
                  groupMap.set(item.groupId, [item])
                } else {
                  let tArr = groupMap.get(item.groupId)
                  tArr.push(item) && groupMap.set(item.groupId, tArr)
                }
              } else {
                groupMap.set('NoGroup_' + item.id, [item])
              }
            })

            groupMap.forEach((value, key) => {
              renderArr.push(value)
            })

            const array = renderArr?.map((item) => {
              const resItem = {
                type: 'container',
                style: {
                  width: '90%',
                  border: '1px solid #d9d9d9',
                  'border-radius': '10px',
                  padding: '10px 0 10px 10px'
                  // marginBottom: '20px'
                },
                items: []
              }
              item.map((gItem, gIndex) => {
                const cardItem = {
                  type: 'container',
                  style: {
                    display: 'flex',
                    alignItems: 'center'
                  },
                  items: [
                    {
                      type: 'container',
                      style: {
                        width: '10px',
                        height: '10px',
                        border: '2px solid',
                        borderColor: '#67c23a',
                        borderRadius: '50%',
                        display: 'inline-block',
                        marginRight: '10px'
                      },
                      formatItem: (row, node) => {
                        if (!gItem.isExecuted && gItem.isCurrentNode) {
                          node.style.borderColor = '#F7AC03'
                        } else if (!gItem.isExecuted && !gItem.isCurrentNode) {
                          node.style.borderColor = '#CCCCCC'
                        }
                        return node
                      }
                    },
                    {
                      type: 'container',
                      items: [
                        {
                          type: 'text',
                          value: '',
                          style: {
                            color: '#999999',
                            fontSize: '13px'
                          },
                          formatItem: (row, node) => {
                            node.value = gItem.name
                            return node
                          }
                        },
                        {
                          type: 'text',
                          value: '',
                          style: {
                            display: 'block',
                            color: '#333333',
                            fontSize: '14px'
                          },
                          formatItem: (row, node) => {
                            node.value = gItem.assignee?.label
                            return node
                          }
                        }
                      ]
                    }
                  ]
                }
                resItem.items.push(cardItem)
                if (gItem.isExecuted) {
                  resItem.icon = 'iconfont icon-chenggong'
                } else if (!gItem.isExecuted && gItem.isCurrentNode) {
                  // vm.data.active = gIndex
                  resItem.icon = 'iconfont icon-chaoshi'
                } else {
                  resItem.icon = 'iconfont icon-weishenpi'
                }

                if (gIndex < item.length - 1) {
                  cardItem.style.marginBottom = '20px'
                }
              })
              return resItem
            })

            array.map((item) => {
              vm.app.updatePageNode(item, vm, () => {
                vm.data.items.push(item)
              })
            })

            // 图标相对右侧的框垂直居中
            setTimeout(() => {
              const iconArrs = Array.from(
                vm.instance?.$el?.querySelectorAll('.el-step.is-vertical')
              )
              const lineEls = []

              iconArrs.forEach((item, index) => {
                const iconEl = item.querySelector('.el-step__icon.is-icon')
                const nextIconEl = iconArrs[index + 1]?.querySelector('.el-step__icon.is-icon')

                if (nextIconEl) {
                  const upperRect = iconEl?.getBoundingClientRect()
                  const lowerRect = nextIconEl?.getBoundingClientRect()
                  const distance = lowerRect.top - upperRect.bottom

                  const lineEl = item.querySelector('.el-step.is-vertical .el-step__line')
                  lineEls.push(lineEl)

                  lineEl && (lineEl.style.height = distance + 'px')
                }
              })

              lineEls.forEach((lineEl) => {
                lineEl && (lineEl.style.top = '18px')
              })
            }, 0)
          },
          mounted: (vm) => {}
        }
      ]
    }
  ]
}
