/**
 * 颜色到CSS Filter转换工具
 * 可以将任意颜色转换为CSS filter属性值，用于改变图标颜色
 * 特别适用于将白色图标转换为指定颜色
 */

class ColorFilterConverter {
  /**
   * 将各种颜色格式转换为RGB
   * @param {string} color - 颜色值，支持 #fff, #ffffff, #ffffffff, rgb(), rgba() 等格式
   * @returns {Object} RGB对象 {r, g, b}
   */
  static hexToRgb(color) {
    if (!color || typeof color !== 'string') return null

    color = color.trim()

    // RGB/RGBA 格式处理
    const rgbMatch = color.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*[\d.]+)?\s*\)/i)
    if (rgbMatch) {
      return {
        r: parseInt(rgbMatch[1], 10),
        g: parseInt(rgbMatch[2], 10),
        b: parseInt(rgbMatch[3], 10)
      }
    }

    // 十六进制格式处理
    let hex = color.replace('#', '').toLowerCase()

    // 3位 -> 6位
    if (hex.length === 3) {
      hex = hex
        .split('')
        .map((c) => c + c)
        .join('')
    }
    // 8位 -> 6位 (去除alpha)
    else if (hex.length === 8) {
      hex = hex.substring(0, 6)
    }
    // 4位 -> 6位 (去除alpha)
    else if (hex.length === 4) {
      hex = hex.substring(0, 3)
      hex = hex
        .split('')
        .map((c) => c + c)
        .join('')
    }

    // 验证并解析6位十六进制
    const result = /^([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
    return result
      ? {
          r: parseInt(result[1], 16),
          g: parseInt(result[2], 16),
          b: parseInt(result[3], 16)
        }
      : null
  }

  /**
   * 将RGB转换为HSL
   * @param {number} r - 红色分量 (0-255)
   * @param {number} g - 绿色分量 (0-255)
   * @param {number} b - 蓝色分量 (0-255)
   * @returns {Object} HSL对象 {h, s, l}
   */
  static rgbToHsl(r, g, b) {
    r /= 255
    g /= 255
    b /= 255

    const max = Math.max(r, g, b)
    const min = Math.min(r, g, b)
    let h,
      s,
      l = (max + min) / 2

    if (max === min) {
      h = s = 0 // 无色
    } else {
      const d = max - min
      s = l > 0.5 ? d / (2 - max - min) : d / (max + min)

      switch (max) {
        case r:
          h = (g - b) / d + (g < b ? 6 : 0)
          break
        case g:
          h = (b - r) / d + 2
          break
        case b:
          h = (r - g) / d + 4
          break
      }
      h /= 6
    }

    return {
      h: Math.round(h * 360),
      s: Math.round(s * 100),
      l: Math.round(l * 100)
    }
  }

  /**
   * 计算颜色的相对亮度
   * @param {number} r - 红色分量 (0-255)
   * @param {number} g - 绿色分量 (0-255)
   * @param {number} b - 蓝色分量 (0-255)
   * @returns {number} 相对亮度 (0-1)
   */
  static getLuminance(r, g, b) {
    const [rs, gs, bs] = [r, g, b].map((c) => {
      c = c / 255
      return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)
    })
    return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs
  }

  /**
   * 将颜色转换为CSS filter字符串
   * @param {string} targetColor - 目标颜色 (如: #AD053D)
   * @param {string} sourceColor - 源颜色 (默认: #FFFFFF 白色)
   * @returns {string} CSS filter字符串
   */
  static colorToFilter(targetColor, sourceColor = '#FFFFFF') {
    const targetRgb = this.hexToRgb(targetColor)
    const sourceRgb = this.hexToRgb(sourceColor)

    if (!targetRgb || !sourceRgb) {
      throw new Error('无效的颜色格式')
    }

    const targetHsl = this.rgbToHsl(targetRgb.r, targetRgb.g, targetRgb.b)
    const sourceHsl = this.rgbToHsl(sourceRgb.r, sourceRgb.g, sourceRgb.b)

    // 计算亮度差异
    const targetLuminance = this.getLuminance(targetRgb.r, targetRgb.g, targetRgb.b)
    const sourceLuminance = this.getLuminance(sourceRgb.r, sourceRgb.g, sourceRgb.b)

    // 计算各种filter值
    const brightness = Math.round((targetLuminance / sourceLuminance) * 100)
    const hueRotate = targetHsl.h - sourceHsl.h
    const saturate =
      targetHsl.s > 0 ? Math.round((targetHsl.s / Math.max(sourceHsl.s, 1)) * 100) : 0

    // 对于从白色转换，需要特殊处理
    if (sourceColor.toUpperCase() === '#FFFFFF') {
      return this.whiteToColorFilter(targetColor)
    }

    let filters = []

    if (brightness !== 100) {
      filters.push(`brightness(${brightness}%)`)
    }

    if (hueRotate !== 0) {
      filters.push(`hue-rotate(${hueRotate}deg)`)
    }

    if (saturate !== 100 && saturate !== 0) {
      filters.push(`saturate(${saturate}%)`)
    }

    return filters.length > 0 ? filters.join(' ') : 'none'
  }

  /**
   * 专门用于从白色转换到目标颜色的优化算法
   * @param {string} targetColor - 目标颜色
   * @returns {string} CSS filter字符串
   */
  static whiteToColorFilter(targetColor) {
    const rgb = this.hexToRgb(targetColor)
    if (!rgb) {
      throw new Error('无效的颜色格式')
    }

    const hsl = this.rgbToHsl(rgb.r, rgb.g, rgb.b)

    // 使用更精确的算法来处理从白色的转换
    let filters = []

    // 首先反转颜色 (白色变黑色)
    filters.push('invert(1)')

    // 然后应用色相旋转
    if (hsl.h !== 0) {
      filters.push(`hue-rotate(${hsl.h}deg)`)
    }

    // 调整饱和度
    if (hsl.s > 0) {
      filters.push(`saturate(${Math.max(hsl.s * 0.01, 0.1)})`)
    }

    // 调整亮度 (因为invert后需要重新调整)
    const brightness = 100 - hsl.l
    if (brightness !== 50) {
      filters.push(`brightness(${brightness}%)`)
    }

    return filters.join(' ')
  }

  /**
   * 简化版本：直接计算白色图标到目标颜色的filter
   * 这个方法更适合实际使用
   * @param {string} color - 目标颜色 (如: #AD053D)
   * @returns {string} CSS filter字符串
   */
  static getFilterForColor(color) {
    const rgb = this.hexToRgb(color)
    if (!rgb) {
      throw new Error('无效的颜色格式')
    }

    // 将RGB值标准化到0-1范围
    const r = rgb.r / 255
    const g = rgb.g / 255
    const b = rgb.b / 255

    // 计算HSL
    const max = Math.max(r, g, b)
    const min = Math.min(r, g, b)
    const diff = max - min
    const sum = max + min
    const l = sum / 2

    let h = 0
    let s = 0

    if (diff !== 0) {
      s = l > 0.5 ? diff / (2 - sum) : diff / sum

      switch (max) {
        case r:
          h = (g - b) / diff + (g < b ? 6 : 0)
          break
        case g:
          h = (b - r) / diff + 2
          break
        case b:
          h = (r - g) / diff + 4
          break
      }
      h /= 6
    }

    h = Math.round(h * 360)
    s = Math.round(s * 100)
    const lightness = Math.round(l * 100)

    // 构建filter字符串
    let filters = []

    // 对于深色，先反转
    if (lightness < 50) {
      filters.push('invert(1)')

      // 调整色相
      if (h !== 0) {
        filters.push(`hue-rotate(${h}deg)`)
      }

      // 调整饱和度
      if (s > 0) {
        filters.push(`saturate(${s * 2}%)`) // 增强饱和度
      }

      // 调整亮度
      const adjustedBrightness = Math.round((1 - lightness / 100) * 100)
      filters.push(`brightness(${adjustedBrightness}%)`)
    } else {
      // 对于浅色，使用不同的策略
      filters.push(`brightness(${lightness}%)`)

      if (h !== 0) {
        filters.push(`hue-rotate(${h}deg)`)
      }

      if (s > 0) {
        filters.push(`saturate(${s}%)`)
      }
    }

    return filters.join(' ')
  }

  /**
   * ============ 高精度：SPSA拟合求解器 ============
   * 将目标色（十六进制）拟合为从黑色起点经滤镜链产生的近似色
   * 滤镜顺序：invert → sepia → saturate → hue-rotate → brightness → contrast
   * 输出的CSS会在前缀加上 brightness(0) saturate(100%) 以统一输入图形到黑色，增强稳定性
   */
  static clamp01(v) {
    if (v < 0) return 0
    if (v > 1) return 1
    return v
  }

  static clamp(v, min, max) {
    if (v < min) return min
    if (v > max) return max
    return v
  }

  static applyInvert(color, amount) {
    // c' = c*(1-a) + (1-c)*a
    const a = ColorFilterConverter.clamp01(amount)
    return [
      color[0] + a * (1 - 2 * color[0]),
      color[1] + a * (1 - 2 * color[1]),
      color[2] + a * (1 - 2 * color[2])
    ]
  }

  static applyBrightness(color, amount) {
    // c' = c * amount
    const a = Math.max(0, amount)
    return [
      ColorFilterConverter.clamp(color[0] * a, 0, 1),
      ColorFilterConverter.clamp(color[1] * a, 0, 1),
      ColorFilterConverter.clamp(color[2] * a, 0, 1)
    ]
  }

  static applyContrast(color, amount) {
    // c' = (c - 0.5) * amount + 0.5
    const a = Math.max(0, amount)
    return [
      ColorFilterConverter.clamp((color[0] - 0.5) * a + 0.5, 0, 1),
      ColorFilterConverter.clamp((color[1] - 0.5) * a + 0.5, 0, 1),
      ColorFilterConverter.clamp((color[2] - 0.5) * a + 0.5, 0, 1)
    ]
  }

  static multiplyMatrix(color, m) {
    const r = color[0],
      g = color[1],
      b = color[2]
    const r2 = r * m[0][0] + g * m[0][1] + b * m[0][2]
    const g2 = r * m[1][0] + g * m[1][1] + b * m[1][2]
    const b2 = r * m[2][0] + g * m[2][1] + b * m[2][2]
    return [
      ColorFilterConverter.clamp(r2, 0, 1),
      ColorFilterConverter.clamp(g2, 0, 1),
      ColorFilterConverter.clamp(b2, 0, 1)
    ]
  }

  static getSepiaMatrix(amount) {
    // CSS sepia(amount): 在 I 与 Sepia 矩阵之间线性插值
    const a = ColorFilterConverter.clamp01(amount)
    const S = [
      [0.393, 0.769, 0.189],
      [0.349, 0.686, 0.168],
      [0.272, 0.534, 0.131]
    ]
    const I = [
      [1, 0, 0],
      [0, 1, 0],
      [0, 0, 1]
    ]
    const M = [
      [
        I[0][0] + a * (S[0][0] - I[0][0]),
        I[0][1] + a * (S[0][1] - I[0][1]),
        I[0][2] + a * (S[0][2] - I[0][2])
      ],
      [
        I[1][0] + a * (S[1][0] - I[1][0]),
        I[1][1] + a * (S[1][1] - I[1][1]),
        I[1][2] + a * (S[1][2] - I[1][2])
      ],
      [
        I[2][0] + a * (S[2][0] - I[2][0]),
        I[2][1] + a * (S[2][1] - I[2][1]),
        I[2][2] + a * (S[2][2] - I[2][2])
      ]
    ]
    return M
  }

  static getSaturateMatrix(amount) {
    // CSS saturate(amount): amount 为比例（1为100%）
    const a = Math.max(0, amount)
    const rw = 0.213,
      gw = 0.715,
      bw = 0.072
    return [
      [rw + (1 - rw) * a, gw - gw * a, bw - bw * a],
      [rw - rw * a, gw + (1 - gw) * a, bw - bw * a],
      [rw - rw * a, gw - gw * a, bw + (1 - bw) * a]
    ]
  }

  static getHueRotateMatrix(deg) {
    // CSS hue-rotate(deg)
    const rad = (deg * Math.PI) / 180
    const cos = Math.cos(rad)
    const sin = Math.sin(rad)
    const rw = 0.213,
      gw = 0.715,
      bw = 0.072
    return [
      [
        rw + cos * (1 - rw) + sin * -rw,
        gw + cos * -gw + sin * -gw,
        bw + cos * -bw + sin * (1 - bw)
      ],
      [
        rw + cos * -rw + sin * 0.143,
        gw + cos * (1 - gw) + sin * 0.14,
        bw + cos * -bw + sin * -0.283
      ],
      [rw + cos * -rw + sin * -(1 - rw), gw + cos * -gw + sin * gw, bw + cos * (1 - bw) + sin * bw]
    ]
  }

  static applyMatrix(color, matrix) {
    return ColorFilterConverter.multiplyMatrix(color, matrix)
  }

  static applyFiltersFromBlack(params) {
    // 起点：黑色
    let c = [0, 0, 0]
    c = ColorFilterConverter.applyInvert(c, params.invert)
    c = ColorFilterConverter.applyMatrix(c, ColorFilterConverter.getSepiaMatrix(params.sepia))
    c = ColorFilterConverter.applyMatrix(c, ColorFilterConverter.getSaturateMatrix(params.saturate))
    c = ColorFilterConverter.applyMatrix(c, ColorFilterConverter.getHueRotateMatrix(params.hue))
    c = ColorFilterConverter.applyBrightness(c, params.brightness)
    c = ColorFilterConverter.applyContrast(c, params.contrast)
    return c
  }

  static rgbTo01(rgb) {
    return [rgb.r / 255, rgb.g / 255, rgb.b / 255]
  }

  static cssFromParams(p) {
    const inv = Math.round(p.invert * 100)
    const sep = Math.round(p.sepia * 100)
    const sat = Math.round(p.saturate * 100)
    const hue = Math.round(((p.hue % 360) + 360) % 360)
    const bri = Math.round(p.brightness * 100)
    const con = Math.round(p.contrast * 100)
    return `brightness(0) saturate(100%) invert(${inv}%) sepia(${sep}%) saturate(${sat}%) hue-rotate(${hue}deg) brightness(${bri}%) contrast(${con}%)`
  }

  static lossFor(params, target01) {
    const c = ColorFilterConverter.applyFiltersFromBlack(params)
    const dr = c[0] - target01[0]
    const dg = c[1] - target01[1]
    const db = c[2] - target01[2]
    return dr * dr + dg * dg + db * db
  }

  static mapFromUnit(x) {
    // x ∈ [0,1] → 真实参数范围
    return {
      invert: x[0],
      sepia: x[1],
      saturate: 0 + x[2] * 10, // 0–10（0%–1000%）
      hue: 0 + x[3] * 360, // 0–360deg
      brightness: 0 + x[4] * 2, // 0–200%
      contrast: 0 + x[5] * 2 // 0–200%
    }
  }

  static solve(color, options = {}) {
    const targetRgb = ColorFilterConverter.hexToRgb(color)
    if (!targetRgb)
      throw new Error('无效的颜色格式，支持格式：rgb(), rgba(), #fff, #ffffff, #ffffffff')
    const target01 = ColorFilterConverter.rgbTo01(targetRgb)

    const maxIter = options.iterations || 800
    const restarts = options.restarts || 2

    const alpha = 0.602 // 学习率衰减
    const gamma = 0.101 // 扰动衰减
    const a0 = 0.15 // 基础学习率（单位空间）
    const c0 = 0.1 // 基础扰动幅度
    const A = 50 // 稳定项

    let best = { loss: Infinity, params: null }

    for (let r = 0; r < restarts; r++) {
      // 随机初始化到[0,1]
      let x = new Array(6).fill(0).map(() => Math.random())

      // 轻度启发：若目标较暗，提高invert起点
      const lightness = (target01[0] + target01[1] + target01[2]) / 3
      if (lightness < 0.5) x[0] = Math.max(x[0], 0.6)

      for (let k = 0; k < maxIter; k++) {
        const ak = a0 / Math.pow(k + 1 + A, alpha)
        const ck = c0 / Math.pow(k + 1, gamma)

        // 生成±1扰动向量
        const delta = new Array(6).fill(0).map(() => (Math.random() < 0.5 ? -1 : 1))

        const xPlus = x.map((v, i) => ColorFilterConverter.clamp01(v + ck * delta[i]))
        const xMinus = x.map((v, i) => ColorFilterConverter.clamp01(v - ck * delta[i]))

        const pPlus = ColorFilterConverter.mapFromUnit(xPlus)
        const pMinus = ColorFilterConverter.mapFromUnit(xMinus)

        const yPlus = ColorFilterConverter.lossFor(pPlus, target01)
        const yMinus = ColorFilterConverter.lossFor(pMinus, target01)

        const gk = new Array(6)
        for (let i = 0; i < 6; i++) {
          gk[i] = (yPlus - yMinus) / (2 * ck * delta[i])
        }

        // 更新
        x = x.map((v, i) => ColorFilterConverter.clamp01(v - ak * gk[i]))

        // 保持当前最好
        const pNow = ColorFilterConverter.mapFromUnit(x)
        const lossNow = ColorFilterConverter.lossFor(pNow, target01)
        if (lossNow < best.loss) {
          best = { loss: lossNow, params: { ...pNow } }
        }
      }
    }

    return {
      params: best.params,
      loss: best.loss,
      css: ColorFilterConverter.cssFromParams(best.params),
      target: color
    }
  }

  static solveToFilter(color, options) {
    const res = ColorFilterConverter.solve(color, options)
    return res.css
  }
}

// 导出类和便捷函数
window.ColorFilterConverter = ColorFilterConverter

/**
 * 便捷函数：将颜色转换为filter
 * @param {string} color - 目标颜色
 * @returns {string} CSS filter字符串
 */
function colorToFilter(color) {
  return ColorFilterConverter.getFilterForColor(color)
}

// 导出便捷函数
window.colorToFilter = colorToFilter

// 便捷求解函数：直接返回CSS filter字符串
export function solveColorFilter(color, options) {
  return ColorFilterConverter.solveToFilter(color, options)
}
export function getBgLuminance(color) {
  let { r, g, b } = formatColor(color)
  const rsRGB = r / 255
  const gsRGB = g / 255
  const bsRGB = b / 255
  const rLinear = rsRGB <= 0.03928 ? rsRGB / 12.92 : Math.pow((rsRGB + 0.055) / 1.055, 2.4)
  const gLinear = gsRGB <= 0.03928 ? gsRGB / 12.92 : Math.pow((gsRGB + 0.055) / 1.055, 2.4)
  const bLinear = bsRGB <= 0.03928 ? bsRGB / 12.92 : Math.pow((bsRGB + 0.055) / 1.055, 2.4)

  // 计算相对亮度（WCAG标准）
  return 0.2126 * rLinear + 0.7152 * gLinear + 0.0722 * bLinear
}
function formatColor(color) {
  let r, g, b
  if (color.startsWith('#')) {
    // HEX格式
    const hex = color.substring(1)
    if (hex.length === 3) {
      r = parseInt(hex[0] + hex[0], 16)
      g = parseInt(hex[1] + hex[1], 16)
      b = parseInt(hex[2] + hex[2], 16)
    } else if (hex.length === 6) {
      r = parseInt(hex.substring(0, 2), 16)
      g = parseInt(hex.substring(2, 4), 16)
      b = parseInt(hex.substring(4, 6), 16)
    } else if (hex.length === 4 || hex.length === 8) {
      // 忽略alpha通道，只使用RGB部分
      r = parseInt(hex.substring(0, 2), 16)
      g = parseInt(hex.substring(2, 4), 16)
      b = parseInt(hex.substring(4, 6), 16)
    }
  } else if (color.startsWith('rgb')) {
    // RGB或RGBA格式
    const match = color.match(/(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/)

    if (match) {
      r = parseInt(match[1])
      g = parseInt(match[2])
      b = parseInt(match[3])
    }
  }
  // 确保值在0-255范围内
  r = Math.max(0, Math.min(255, r))
  g = Math.max(0, Math.min(255, g))
  b = Math.max(0, Math.min(255, b))
  return { r, g, b }
}

window.solveColorFilter = solveColorFilter

// 如果是Node.js环境
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    ColorFilterConverter,
    colorToFilter,
    solveColorFilter,
    getBgLuminance
  }
}
