export const handlerBizPage = (nodeId, options = {}) => {
  let curNodeId = nodeId
  let handlers = {
    dataHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          if (property === 'pre') {
            return pre
          } else if (property === 'loadView') {
            // loadView接口返回的数据
            return curNode.$ds.tableView?.data
          } else if (property === 'isOpenDetail') {
            return curNode?.$ds?.isDetail
          } else if (property === 'model') {
            return tableMainVm?.$ds?._metaParamsModel
          } else if (property === 'app') {
            return tableMainVm?.$ds?._metaParamsApp
          }
        }
      }
    },
    reqHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode && property === 'loadView') {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          val = tableMainVm?.data?.ds_config?.list?.find((i) => i.name === 'tableView')
        }
        return val
      }
    },
    baseMethodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode && property === 'queryView') {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          let __srcHookFn = { ...tableMainVm?.data?.__srcHookFn }
          val = __srcHookFn?.['commands.' + property]
        }
        return val
      }
    },
    methodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode && property === 'queryView') {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          let distHookFn = { ...tableMainVm?.data?.commands }
          val = distHookFn?.[property]
        }
        return val
      }
    },
    nodesHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode && property === 'self') {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          return curNode.$select(pre + 'container_main')
        }
      }
    }
  }
  return handlers
}
