import { handlerBizSearch } from './searchHandler'
import { handlerBizGrid } from './gridHandler'

export const bizTabsHandler = (curNodeId) => {
  return {
    get: (target, property, receiver) => {
      let val = null
      if (typeof property !== 'string') return val
      let curNode = tech_app.page.getNode(curNodeId)
      let nodes = curNode.$select(curNode.$ds.idPre + 'form-tabs-node')
      let node = nodes?.data?.items?.find(
        (i) => i.id === curNode.$ds.idPre + 'tab_' + property + '_container_main_content'
      )
      if (node?.id) {
        let container_main_content = curNode.$select(node.id)
        let idPreTab = container_main_content?.$ds?.idPreTab
        let tableMainVm = curNode.$select(idPreTab + 'table_main')
        let tableVm = curNode.$select(idPreTab + 'table_main_table')
        let tableMainWrapVm = curNode.$select(idPreTab + 'table_main_wrap')
        let hookObj = {
          canCreate: 'canCreate',
          canDelete: 'canDelete',
          canEdit: 'canEdit',
          onConfirm: 'deleteConfirm',
          beforeQuery: 'beforeQuery',
          query: 'query',
          afterQuery: 'afterQuery',
          queryCount: 'queryCount',
          select: 'select',
          cancelSelect: 'cancelSelect',
          delete: 'tabTableDelete'
        }
        val = new Proxy(
          {},
          {
            get: (target, property, receiver) => {
              if (property === 'grid') {
                return new Proxy(
                  {},
                  {
                    get: (target, property, receiver) => {
                      if (property === 'data') {
                        let dataArr = [
                          'tableView',
                          'paging',
                          'tableDataCount',
                          'tableData',
                          'tableFilter',
                          'tableFilterTags',
                          'treeFilter',
                          'tabUniqueTag'
                        ]
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              if (dataArr.includes(property)) {
                                return tableMainVm?.$ds?.[property]
                              }
                            }
                          }
                        )
                      } else if (property === 'req') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              return tableMainVm?.data?.ds_config?.list?.find(
                                (i) => i.name === property
                              )
                            }
                          }
                        )
                      } else if (property === 'baseMethods') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              let srcHookFn = {
                                ...tableMainWrapVm?.data?.__srcHookFn,
                                ...tableVm?.data?.__srcHookFn
                              }
                              if (
                                typeof property === 'string' &&
                                hookObj[property] &&
                                srcHookFn?.['commands.' + hookObj[property]]
                              ) {
                                return srcHookFn?.['commands.' + hookObj[property]]
                              }
                            }
                          }
                        )
                      } else if (property === 'methods') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              let distHookFn = {
                                ...tableMainWrapVm?.data?.commands,
                                ...tableVm?.data?.commands
                              }
                              if (
                                typeof property === 'string' &&
                                hookObj[property] &&
                                distHookFn?.[hookObj[property]]
                              ) {
                                return distHookFn[hookObj[property]]
                              } else if (property === 'runRefresh') {
                                // 刷新方法
                                return function () {
                                  let runRefreshVm = curNode.$select(
                                    idPreTab + 'table_main_toolbar_refresh'
                                  )
                                  runRefreshVm?.instance?.click()
                                }
                              } else if (property === 'toPage') {
                                // 跳转到表格某页
                                return function (val) {
                                  let pagingVm = curNode.$select(idPreTab + 'table_main_paging')
                                  if (pagingVm?.instance) {
                                    pagingVm.instance.pageVal = val
                                    pagingVm.instance.pageChange(val)
                                  }
                                }
                              } else if (property === 'addErData') {
                                return function (data, tableVm) {
                                  tableVm.$cmd.dealTableErCatch('add', data, tableVm, 'tableData')
                                }
                              }
                            }
                          }
                        )
                      } else if (property === 'nodes') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              if (property === 'self') {
                                return tableVm
                              } else if (property === 'tbarNodes') {
                                let toolbarBtn = curNode.$select(
                                  idPreTab + 'table_main_toolbar_btns'
                                )
                                return new Proxy(
                                  {},
                                  {
                                    get: (target, property, receiver) => {
                                      let id = toolbarBtn?.data?.items?.[property]?.id
                                      if (id) return curNode.$select(id)
                                    }
                                  }
                                )
                              } else if (property === 'buttonNodes') {
                                let operation = curNode.$select(
                                  idPreTab + 'table_main_table_column_operation'
                                )
                                return new Proxy(
                                  {},
                                  {
                                    get: (target, property, receiver) => {
                                      let id = operation?.data?.items?.[property]?.id
                                      if (id) return curNode.$select(id)
                                    }
                                  }
                                )
                              } else if (property === 'refreshNode') {
                                return curNode.$select(idPreTab + 'table_main_toolbar_refresh')
                              }
                            }
                          }
                        )
                      } else if (property === 'edit') {
                        let handlers = handlerBizGrid(node.id)
                        return new Proxy({}, handlers.editHandler)
                      }
                    }
                  }
                )
              } else if (property === 'search') {
                let handlers = handlerBizSearch(node.id)
                return new Proxy(
                  {},
                  {
                    get: (target, property, receiver) => {
                      switch (property) {
                        case 'data':
                          return new Proxy({}, handlers.dataHandler)
                        case 'req':
                          return new Proxy({}, handlers.reqHandler)
                        case 'baseMethods':
                          return new Proxy({}, handlers.baseMethodsHandler)
                        case 'methods':
                          return new Proxy({}, handlers.methodsHandler)
                        case 'nodes':
                          return new Proxy({}, handlers.nodesHandler)
                        default:
                          break
                      }
                    }
                  }
                )
              } else if (property === 'drawerForm') {
                // 抽屉表单
                let tableDrawer = curNode.$select(idPreTab + 'table_drawer')
                let tableDrawerForm = curNode.$select(idPreTab + 'table_drawer_form')
                let containerMain = curNode.$select(idPreTab + 'container_main_content')
                let hookArr = ['queryView', 'beforeQuery', 'query', 'afterQuery', 'init', 'save']
                return new Proxy(
                  {},
                  {
                    get: (target, property, receiver) => {
                      if (property === 'data') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              if (property === 'form') {
                                let formData = tableDrawerForm?.$ds?.form || {}
                                return new Proxy(
                                  { ...formData },
                                  {
                                    // 动态设置子属性代理
                                    get: (target, property, receiver) => {
                                      return target[property]
                                    },
                                    set: (target, property, value, receiver) => {
                                      let setSuccess = true // 设置状态 true表示成功
                                      if (formData[property] !== undefined) {
                                        formData[property] = value
                                      }
                                      return setSuccess
                                    }
                                  }
                                )
                              }
                            },
                            set: (target, property, value, receiver) => {
                              let setSuccess = true // 设置状态 true表示成功
                              if (property === 'form') {
                                let formData = tableDrawerForm?.$ds?.form || {}
                                for (let k in value) {
                                  if (formData[k] !== undefined) {
                                    formData[k] = value[k]
                                  }
                                }
                              }
                              return setSuccess
                            }
                          }
                        )
                      } else if (property === 'baseMethods') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              let srcHookFn = {
                                ...tableDrawer?.data?.__srcHookFn,
                                ...containerMain?.data?.__srcHookFn
                              }
                              if (['created', 'mounted', 'destroy'].includes(property)) {
                                return srcHookFn?.[property]
                              } else if (
                                typeof property === 'string' &&
                                hookArr.includes(property) &&
                                srcHookFn?.['commands.' + property]
                              ) {
                                return srcHookFn?.['commands.' + property]
                              }
                            }
                          }
                        )
                      } else if (property === 'methods') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              let distHookFn = { ...containerMain?.data?.commands }
                              if (['created', 'mounted', 'destroy'].includes(property)) {
                                return tableDrawer?.data?.[property]
                              } else if (
                                typeof property === 'string' &&
                                hookArr.includes(property) &&
                                distHookFn?.[property]
                              ) {
                                return distHookFn?.[property]
                              }
                            }
                          }
                        )
                      } else if (property === 'nodes') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              if (property === 'self') {
                                return tableDrawerForm
                              } else if (property === 'drawerNode') {
                                return tableDrawer
                              }
                            }
                          }
                        )
                      }
                    }
                  }
                )
              } else if (property === 'addRel') {
                let addRelVm = curNode.$select(idPreTab + 'dialog_pop_select_table')
                let hookArr = [
                  'queryView',
                  'beforeQuery',
                  'query',
                  'afterQuery',
                  'queryCount',
                  'save'
                ]
                return new Proxy(
                  {},
                  {
                    get: (target, property, receiver) => {
                      if (property === 'data') {
                        let props = [
                          'optionList',
                          'checkedList',
                          'selectedList',
                          'tableDataCount',
                          'tableView',
                          'selectedDisplay'
                        ]
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              if (property === 'tableData') {
                                return addRelVm?.$ds?.tablePopData
                              } else if (props.includes(property)) {
                                return addRelVm?.$ds?.[property]
                              }
                            }
                          }
                        )
                      } else if (property === 'req') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              let obj = {
                                tableDataCount: 'tableDataCount',
                                tableData: 'tablePopData',
                                tableView: 'tableView'
                              }
                              return addRelVm?.data?.ds_config?.list?.find(
                                (i) => i.name === obj[property]
                              )
                            }
                          }
                        )
                      } else if (property === 'baseMethods') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              let srcHookFn = {
                                ...addRelVm?.data?.__srcHookFn
                              }

                              if (['created', 'mounted', 'destroy'].includes(property)) {
                                return srcHookFn?.[property]
                              } else if (
                                typeof property === 'string' &&
                                hookArr.includes(property) &&
                                srcHookFn?.['commands.' + property]
                              ) {
                                return srcHookFn?.['commands.' + property]
                              }
                            }
                          }
                        )
                      } else if (property === 'methods') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              let distHookFn = { ...addRelVm?.data?.commands }
                              if (['created', 'mounted', 'destroy'].includes(property)) {
                                return addRelVm?.data?.[property]
                              } else if (
                                typeof property === 'string' &&
                                hookArr.includes(property) &&
                                distHookFn?.[property]
                              ) {
                                return distHookFn?.[property]
                              }
                            }
                          }
                        )
                      } else if (property === 'nodes') {
                        return new Proxy(
                          {},
                          {
                            get: (target, property, receiver) => {
                              if (property === 'self') {
                                return addRelVm
                              } else if (property === 'searchNode') {
                                // 搜索按钮节点
                                return addRelVm.$select(
                                  idPreTab + 'table_pop_form_ctn_items_1_items_0'
                                )
                              } else if (property === 'resetNode') {
                                // 重置按钮节点
                                return addRelVm.$select(
                                  idPreTab + 'table_pop_form_ctn_items_1_items_1'
                                )
                              } else if (property === 'refreshNode') {
                                // 刷新按钮节点
                                return addRelVm.$select(idPreTab + 'table_pop_refresh')
                              } else if (property === 'tableNode') {
                                // 表格节点
                                return addRelVm.$select(idPreTab + 'table_pop_content')
                              }
                            }
                          }
                        )
                      }
                    }
                  }
                )
              }
            }
          }
        )
      }
      return val
    }
  }
}

export const handlerBizForm = (nodeId, options = {}) => {
  let curNodeId = nodeId
  let handlers = {
    dataHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          if (property === 'form') {
            let formData = curNode.$select(pre + 'form_main_detail_top_common')?.$ds?.form || {}
            val = new Proxy(
              { ...formData },
              {
                // 动态设置子属性代理
                get: (target, property, receiver) => {
                  return target[property]
                },
                set: (target, property, value, receiver) => {
                  let setSuccess = true // 设置状态 true表示成功
                  if (formData[property] !== undefined) {
                    formData[property] = value
                  }
                  return setSuccess
                }
              }
            )
          } else if (property === 'clickType') {
            let table_detail = curNode.$select(pre + 'table_detail')
            return table_detail?.$ds?.clickType
          } else if (property === 'model') {
            return tableMainVm?.$ds?._metaParamsModel
          } else if (property === 'app') {
            return tableMainVm?.$ds?._metaParamsApp
          }
        }
        return val
      },
      set: (target, property, value, receiver) => {
        let setSuccess = true // 设置状态 true表示成功
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          if (property === 'form') {
            let formData = curNode.$select(pre + 'form_main_detail_top_common')?.$ds?.form || {}
            for (let k in value) {
              if (formData[k] !== undefined) {
                formData[k] = value[k]
              }
            }
          }
        }
        return setSuccess
      }
    },
    reqHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          if (property === 'formUpdate') {
            let formMainVm = curNode.$select(pre + 'form_main_detail_top_common')
            val = formMainVm?.data?.ds_config?.list?.find((i) => i.name === property)
          } else if (property === 'tableData') {
            let tableMainVm = curNode.$select(pre + 'table_main')
            val = tableMainVm?.data?.ds_config?.list?.find((i) => i.name === property)
          }
        }
        return val
      }
    },
    baseMethodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let formVm = curNode.$select(pre + 'form_main_detail_top')
          let formMainVm = curNode.$select(pre + 'container_form_main_wrap')
          let __srcHookFn = { ...formVm?.data?.__srcHookFn, ...formMainVm?.data?.__srcHookFn }
          let hookFn = [
            'beforeQuery',
            'query',
            'afterQuery',
            'init',
            'beforeSave',
            'save',
            'afterSave',
            'validate'
          ]
          if (['created', 'mounted', 'destroy'].includes(property)) {
            val = __srcHookFn?.[property]
          } else if (hookFn.includes(property)) {
            val = __srcHookFn?.['commands.' + property]
          }
        }
        return val
      }
    },
    methodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let formVm = curNode.$select(pre + 'form_main_detail_top')
          let formMainVm = curNode.$select(pre + 'container_form_main_wrap')
          let pagingVm = curNode.$select(pre + 'form_main_header_paging')
          let hookFn = [
            'beforeQuery',
            'query',
            'afterQuery',
            'init',
            'beforeSave',
            'save',
            'afterSave',
            'validate'
          ]
          if (['created', 'mounted', 'destroy'].includes(property)) {
            val = formMainVm?.data?.[property]
          } else if (hookFn.includes(property)) {
            val = formVm?.data?.commands?.[property]
          } else if (property === 'runSave') {
            return function () {
              let saveVm = curNode.$select(pre + 'form_main_detail_top_save') // 保存按钮
              saveVm?.instance?.click()
            }
          } else if (property === 'runRefresh') {
            return function () {
              let refreshVm = curNode.$select(pre + 'form_main_header_refresh') // 刷新按钮
              refreshVm?.instance?.click()
            }
          } else if (property === 'toNext') {
            return function () {
              pagingVm?.instance?.$el?.querySelector('.paging-box.el-icon-arrow-right')?.click()
            }
          } else if (property === 'toPrev') {
            return function () {
              pagingVm?.instance?.$el?.querySelector('.paging-box.el-icon-arrow-left')?.click()
            }
          }
        }
        return val
      }
    },
    nodesHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          if (property === 'self') {
            return curNode.$select(pre + 'form_main_detail_top')
          } else if (property === 'saveNode') {
            return curNode.$select(pre + 'form_main_detail_top_save')
          }
        }
      }
    },
    tabsHandler: bizTabsHandler(curNodeId)
  }
  return handlers
}
