export default {
  // 搜索条件设置弹窗
  type: 'dialog',
  id: 'dialog_meta_set_search_item',
  width: '80%',
  title: Tech.$t('seniorTable.queryConditionSetting'),
  display: false,
  hasFooter: true,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  bind_on_opreates: (params) => {
    const { self: vm, value } = params
    const idPre = vm.$cmd.getIdPre(vm)
    if (value.type === 'cancel') {
      value.close()
      vm.$select(idPre + 'dialog_meta_set_search_item').$ds.isCancel = true
    } else {
      vm.$select(idPre + 'dialog_meta_set_search_item').$ds.isCancel = false
      const tableVm = vm.$select(idPre + 'set_search_table')
      let commonForm = vm.$select(idPre + 'form_main_table_search_common')
      const { views } = commonForm.$ds.tableView.data
      let searchView = window.Tech._cloneDeep(views?.search)
      //需要从loadView中拿数据，目前有缓存从缓存中拿初始数据
      const cacheData = sessionStorage.getItem(idPre + 'SEARCH_CONFIG')
      const cacheView = cacheData ? JSON.parse(cacheData) : null
      const tableMainVm = vm.$select(idPre + 'table_main_table')
      const seniorTable = vm.$cmd.getUiSchemeData(tableMainVm)
      let searchSeniorTable = seniorTable ? seniorTable.search : null
      if (cacheView) {
        searchView = cacheView
      } else if (searchSeniorTable) {
        searchView = searchSeniorTable
      }
      const tableList = tableVm.data.tableData
      let list = []
      let isMinus = false
      let haveFloat = false
      // tableList.forEach((ele) => {
      //   ele.sort = ele.sort || 0
      // })
      tableList.forEach((item) => {
        if (item.sort || item.sort === 0) {
          list.push(item.sort)
          if (item.sort < 0 || !Number.isInteger(item.sort)) {
            isMinus = true
          }
        } else {
          list.push(0)
        }
        if (item.row && (item.row < 0 || !Number.isInteger(item.row))) {
          haveFloat = true
        }
      })
      // 判断如果有负数或者小数点的序号提示修改
      if (isMinus) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.hasMinusHint'))
        return
      }
      // 判断如果有负数或者小数点的行组提示修改
      if (haveFloat) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.rowErrorHint'))
        return
      }
      // 判断是否有重复的序号
      if (new Set(list).size !== list.length) {
        window.ELEMENT.Message.error(Tech.$t('seniorTable.theSameSortExists'))
        return
      }
      let columns = searchView?.body.columns
      for (let item of columns) {
        let obj = {}
        for (let i = 0; i < tableList.length; i++) {
          if (typeof item === 'string' && item === tableList[i].name) {
            obj.name = tableList[i].name
          } else if (Object.prototype.toString.call(item) === '[object Object]') {
            obj = item
          }
          if (obj.name === tableList[i].name) {
            obj.displayName = tableList[i].displayName
            obj.sort = tableList[i].sort || 0
            obj.display = tableList[i].seniorTableDisplay
            obj.fold = tableList[i].fold
            obj.span = tableList[i].span
            obj.row = tableList[i].row
            obj.operator = tableList[i].operator
            obj.custom = true
          }
        }
        columns[columns.indexOf(item)] = obj
      }
      columns.sort((a, b) => a.sort - b.sort)
      // 缓存columns，设置查询条件的运算符的时候要用
      tableMainVm.$ds.seniorTable = tableMainVm.$ds.seniorTable
        ? tableMainVm.$ds.seniorTable
        : {
            grid: [], // 高级表格数据
            form: null,
            search: null,
            gridConfig: []
          }
      tableMainVm.$ds.seniorTable.search = searchView
      if (searchView) {
        sessionStorage.setItem(vm.$ds.idPre + 'SEARCH_CONFIG', JSON.stringify(searchView))
      }
      // console.log(data)
      const tableMain = vm.$select(idPre + 'table_main_wrap')
      // 存储一下查询条件，回显要用
      sessionStorage.setItem(idPre + 'SEARCH_FILTER', JSON.stringify(tableMain.$ds.tableFilter))

      // 设置本地缓存
      const dropdownForm = vm.$select(idPre + 'form_main_table_search_dropdown')
      let search_form_data = {
        // 缓存现有搜索的数据
        tableFilter: commonForm.$ds.tableFilter,
        tableFilterTags: commonForm.$ds.tableFilterTags,
        formData: { ...commonForm.$ds.form, ...dropdownForm?.$ds.form }
      }
      sessionStorage.setItem(idPre + 'SEARCH_FORM_DATA', JSON.stringify(search_form_data))
      tableMain.$ds.resing = false // 把resing重置成false
      tableMain.$cmd.initTableSearch(tableMain, searchView)
      value.close()
    }
  },
  items: [
    // {
    //   type: 'form',
    //   id: 'form_meta_set_search',
    //   formConfig: {
    //     inline: false,
    //     labelPosition: 'left'
    //   },
    //   dataSource: {
    //     form: { filed: '' }
    //   },
    //   items: [
    //     {
    //       type: 'input',
    //       text: '查找',
    //       name: 'field'
    //     }
    //   ]
    // },
    {
      type: 'container',
      id: 'set_search_table_box',
      className: 'set_search_table_box',
      dataSource: {
        fieldList: [],
        isCancel: false
      },
      created: (vm) => {
        const idPre = vm.$cmd.fromTab(vm) ? vm.$ds.idPreTab : vm.$ds.idPre
        const tableVm = vm.$select(idPre + 'set_search_table')
        //需要从loadView中拿数据，目前有缓存从缓存中拿初始数据
        const cacheData = sessionStorage.getItem(idPre + 'SEARCH_CONFIG')
        const cacheView = cacheData ? JSON.parse(cacheData) : null
        // 如果使用了方案后查询条件设置的弹窗数据需要从缓存中取实时数据
        if (vm.$ds.fieldList.length === 0 || vm.$ds.isCancel || cacheView) {
          const tableMain = vm.$select(idPre + 'table_main_table')
          const seniorTable = vm.$cmd.getUiSchemeData(tableMain)
          let searchView = seniorTable ? seniorTable.search : null
          const { views, fields } = tableMain.$ds.tableView.data
          let viewColumns = views?.search?.body?.columns || []
          let cacheViewColumns = cacheView?.body?.columns || viewColumns
          cacheViewColumns?.forEach((item) => {
            if (item.display !== false && !item.hidden && !item.hide && item.type !== 'hidden') {
              item.seniorTableDisplay = true
            } else {
              item.seniorTableDisplay = false
            }
          })
          // 拿到视图里的columns先过滤掉视图配置了隐藏的字段
          viewColumns = viewColumns.filter(
            (item) => item.display !== false && !item.hidden && !item.hide && item.type !== 'hidden'
          )
          const viewColumnsList = vm.$cmd.meta.getColumnForFieldsList(viewColumns, fields)
          let showColumns = viewColumnsList
          let seniorSearchColumn = []
          if (cacheView) {
            seniorSearchColumn = cacheView?.body?.columns || []
          } else if (!cacheView && searchView?.body?.columns) {
            seniorSearchColumn = searchView?.body?.columns || []
          }
          if (seniorSearchColumn?.length > 0) {
            const seniorSearchColumnList = vm.$cmd.meta.getColumnForFieldsList(
              seniorSearchColumn,
              fields
            )
            // 如果是走的缓存和方案，需过滤掉视图内没有的字段，再合并视图新增的字段
            for (let i = 0; i < viewColumnsList.length; i++) {
              for (let j = 0; j < seniorSearchColumnList.length; j++) {
                if (seniorSearchColumnList[j].name === viewColumnsList[i].name) {
                  viewColumnsList[i] = { ...viewColumnsList[i], ...seniorSearchColumnList[j] }
                }
              }
            }
            showColumns = viewColumnsList
          }
          // 如果存在编辑过的设置查询条件，需要用最新的缓存里面的排序数据
          if (cacheView || searchView) {
            // 遍历showColumns，为没有sort字段的项添加默认sort值
            for (let i = 0; i < showColumns.length; i++) {
              if (showColumns[i].sort === undefined) {
                showColumns[i].sort = i + 1
              }
            }
            // 按照sort值排序
            showColumns.sort((a, b) => a?.sort - b?.sort)
          } else {
            for (let i = 0; i < showColumns.length; i++) {
              showColumns[i].sort = i + 1
            }
          }
          vm.$ds.fieldList = showColumns
        } else {
          const tableList = tableVm.data.tableData
          tableList.forEach((item) => {
            item.sort = item.sort || 0
          })
          tableList.sort((a, b) => a?.sort - b?.sort)
          for (let i = 0; i < tableList.length; i++) {
            tableList[i].sort = i + 1
          }
        }
        // console.log('tableList', tableVm.data.tableData)
        tableVm.data.tableData.sort((a, b) => a?.sort - b?.sort)
      },
      css: `
              .set_search_table_box .vxe-table--render-default.vxe-editable .vxe-body--column{
                padding: 0.05rem 0;
              }
              .set_search_table_box .vxe-table--render-default .vxe-cell{
                white-space: normal !important;
                text-overflow: inherit !important;
              }
            `,
      items: [
        {
          type: 'table',
          isEdit: true,
          id: 'set_search_table',
          style: {
            minHeight: '3.5rem'
          },
          bind_tableData: '$ds.fieldList',
          gridRowDrop: true,
          draggableHandle: '.el-button',
          items: [
            {
              type: 'container',
              field: 'draggable',
              name: 'draggable',
              style: {
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center'
              },
              width: 60,
              title: '',
              items: [
                {
                  type: 'button',
                  options: {
                    icon: 'el-icon-rank',
                    size: 'mini',
                    type: 'text'
                  }
                }
              ]
            },
            // {
            //   type: 'seq',
            //   width: 60,
            //   title: '#'
            // },
            {
              type: 'number',
              field: 'sort',
              name: 'sort',
              maxValue: 100,
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('gridView.sort')
            },
            {
              type: 'switch',
              field: 'seniorTableDisplay',
              name: 'seniorTableDisplay',
              title: Tech.$t('seniorTable.display'),
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              }
            },
            {
              type: 'text',
              field: 'name',
              title: Tech.$t('seniorTable.fieldName')
            },
            {
              field: 'displayName',
              type: 'input',
              name: 'displayName',
              title: Tech.$t('seniorTable.displayName'),
              formatItem: (row, item) => {
                item.displayName = row.label ? row.label : row.displayName
                return item
              }
            },
            {
              type: 'switch',
              field: 'fold',
              name: 'fold',
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.collapsible')
            },
            {
              type: 'number',
              field: 'row',
              name: 'row',
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.rowGroup')
            },
            {
              type: 'select',
              field: 'span',
              name: 'span',
              options: [
                { label: 4, value: 4 },
                { label: 6, value: 6 },
                { label: 8, value: 8 },
                { label: 12, value: 12 },
                { label: 16, value: 16 },
                { label: 24, value: 24 }
              ],
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.width')
            },
            {
              type: 'select',
              field: 'operator',
              name: 'operator',
              options: [
                { label: Tech.$t('seniorTable.leftFuzzyMatching'), value: 'left' },
                { label: Tech.$t('seniorTable.rightFuzzyMatching'), value: 'right' },
                { label: Tech.$t('seniorTable.equalTo'), value: '=' },
                { label: Tech.$t('seniorTable.contain'), value: 'include' },
                { label: Tech.$t('seniorTable.greaterThan'), value: '>' },
                { label: Tech.$t('seniorTable.greaterOrEqualTo'), value: '>=' },
                { label: Tech.$t('seniorTable.lessThan'), value: '<' },
                { label: Tech.$t('seniorTable.lessThanOrEqualTo'), value: '<=' }
              ],
              model: {},
              formatItem: (row, item) => {
                item.model = row
                const type = row.dataType?.toLowerCase()
                if (type === 'string' || type === 'text') {
                  item.options = [
                    { label: Tech.$t('seniorTable.leftFuzzyMatching'), value: 'left' },
                    { label: Tech.$t('seniorTable.rightFuzzyMatching'), value: 'right' },
                    { label: Tech.$t('seniorTable.equalTo'), value: 'all' },
                    { label: Tech.$t('seniorTable.contain'), value: '' }
                  ]
                } else if (type === 'date' || type === 'datetime') {
                  if (row.dateRange) {
                    row.operator = '='
                    item.disabled = true
                  } else {
                    item.options = [
                      { label: Tech.$t('seniorTable.equalTo'), value: '=' },
                      { label: Tech.$t('seniorTable.greaterThan'), value: '>' },
                      { label: Tech.$t('seniorTable.greaterOrEqualTo'), value: '>=' },
                      { label: Tech.$t('seniorTable.lessThan'), value: '<' },
                      { label: Tech.$t('seniorTable.lessThanOrEqualTo'), value: '<=' }
                    ]
                  }
                } else {
                  row.operator = '='
                  item.disabled = true
                }
                return item
              },
              title: Tech.$t('seniorTable.defaultOperator')
            },
            {
              type: 'operation',
              field: 'operate',
              title: Tech.$t('seniorTable.controls'),
              fixed: 'right',
              items: [
                {
                  text: Tech.$t('seniorTable.pinned'),
                  options: {
                    type: 'text'
                  }
                }
              ]
            }
          ],
          bind_on_clickOptionBtn: (params) => {
            const { self: vm, value } = params
            vm.$ds.fieldList = vm.data.tableData // 同步tableData数据
            const curSort = value.scope.row.sort
            let obj = {}
            //遍历修改序号
            vm.$ds.fieldList.forEach((item) => {
              if (item.sort === 1) {
                item.sort = curSort
              }
              if (item.name === value.scope.row.name) {
                item.sort = 1
                obj = { ...item }
              }
            })
            for (let i = 0; i < vm.$ds.fieldList.length; i++) {
              if (vm.$ds.fieldList[i].name === value.scope.row.name) {
                vm.$ds.fieldList.splice(i, 1)
              }
            }
            vm.$ds.fieldList.unshift(obj)
          },
          bind_on_dragRowEnd: (params) => {
            const { self: vm } = params
            const idPre = vm.$cmd.getIdPre(vm)
            const tableVm = vm.$select(idPre + 'set_search_table')
            vm.$ds.fieldList = tableVm.data.tableData // 同步tableData数据
            vm.$ds.fieldList.map((item, index) => (item.sort = index + 1))
            // vm.$cmd.updateSort(vm)
            if (tableVm.instance) {
              tableVm.instance.updateTable()
              tableVm.instance.$nextTick(() => {
                tableVm.instance.rowDrop() // 滚动到对应位置
              })
            }
          }
        }
      ]
    }
  ]
}
