import topLogoIcon from '../../img/login/logogs.png'
import txIcon from '../../img/app/icon-tx.png'
// import header from '../../snest/header';
// import snest from '../../snest';
import iconHome from '../../img/app/icon-home.png'
import iconExit from '../../img/app/icon-exit.png'
export default {
  type: 'container',
  id: 'container_meta_header_top',
  style: {
    height: '0.6rem',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    backgroundColor: 'var(--header-bg, #3D4547)'
  },
  name: '顶部',
  created: (vm) => {
    // snest.header.init(vm);
    if (tech?.TABIFRAME?.inner) {
      // tabiframe内部情况先隐藏
      vm.data.style.display = 'none'
    }
  },
  events: [],
  items: [
    {
      type: 'container',
      id: 'container_meta_header_left',
      style: {
        display: 'flex'
      },
      items: [
        {
          type: 'container',
          id: 'container_meta_header_logo',
          items: [
            {
              type: 'text',
              // value: Tech.$t('common.title'),
              value: Tech.$t('basicPlatformInformation.title'),
              style: {
                color: 'var(--title-text-color,#FFFFFF)',
                'font-size': '0.2rem',
                'line-height': '0.4rem',
                'margin-left': '0.8rem'
              }
            }
          ],
          created: (vm) => {
            if (window?.Tech?.staticIcon?.['$views.static.icon.platformLogo']) {
              vm.data.style.backgroundImage =
                window.Tech.staticIcon['$views.static.icon.platformLogo']
            }
          },
          style: {
            // maxWidth: '2.62rem',
            height: '.4rem',
            marginLeft: '0.14rem',
            backgroundImage: topLogoIcon,
            backgroundPosition: 0,
            backgroundRepeat: 'no-repeat',
            backgroundSize: 'contain',
            cursor: 'pointer',
            whiteSpace: 'nowrap',
            overflow: 'hidden',
            textOverflow: 'ellipsis'
          },
          bind_on_click: (params) => {
            window.open(window.location.origin + window.tech?.routerBase, '_self')
          }
        },
        {
          type: 'button',
          id: 'container_meta_header_menu_shrink',
          style: {
            marginLeft: '0.4rem',
            'font-size': '0.22rem',
            color: '#FFFFFF'
          },
          created: (vm) => {
            const isShrink = localStorage.getItem('isShrink')
            vm.data.options.icon =
              isShrink === null || isShrink === 'true' ? 'el-icon-s-fold' : 'el-icon-s-unfold'
          },
          options: {
            type: 'text',
            icon: 'el-icon-s-fold'
          },
          dataSource: {
            isShrink: false
          },
          bind_on_click: (params) => {
            let menuObj = params.self.$select('menu_meta_siderbar')
            localStorage.setItem('isShrink', menuObj.data.style.width === 0 ? true : false) //不能使用$ds，刷新页面时会重置为false
            // menuObj.data.display = menuObj.data.display ? false : true
            menuObj.data.style.minWidth = menuObj.data.style.width === 0 ? 200 : 0
            menuObj.data.style.width = menuObj.data.style.width === 0 ? menuObj.data.width : 0 //根据已显示的宽度做变换
            params.self.data.options.icon =
              menuObj.data.style.width === 0 ? 'el-icon-s-unfold' : 'el-icon-s-fold'
            // params.self.$ds.isShrink = !params.self.$ds.isShrink
            // localStorage.setItem('menu-shrink', menuObj.data.display)
          }
        }
      ]
    },
    {
      type: 'container',
      id: 'container_meta_header_right',
      css: `
      .chang-lang-popper{
        background: #3D4547;
          border: #3D4547;
        }
        .chang-lang-popper .el-select-dropdown__item{
          color: #fff;
        }
        .chang-lang-popper .el-select-dropdown__item.hover,.chang-lang-popper .el-select-dropdown__item:hover{
          background: #828282;
        }
        .change-lang-select .el-input__inner{padding: 0;background:transparent;border-color: transparent;color: #fff;width: 80px;}
        .change-lang-select .el-select:hover .el-input__inner,.change-lang-select .el-input__inner:hover,.change-lang-select .el-select .el-input__inner:focus,.change-lang-select .el-range-editor.is-active,.change-lang-select .el-range-editor.is-active:hover,.change-lang-select .el-select .el-input.is-focus .el-input__inner{
          border-color: transparent;
          color: transparent;
          text-shadow: 0 0 0 #fff;
        }
      `,
      style: {
        minWidth: '3rem',
        width: 'atuo',
        height: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
        marginRight: '0.17rem',
        position: 'relative'
      },
      items: [
        {
          type: 'container',
          id: 'user_change_role'
        },
        {
          type: 'meta-dropdown',
          id: 'dropdown_meta_header_skin',
          className: 'dropdown-001',
          dropdownClassName: 'dropdown_meta_header_skin_menu',
          css: '.dropdown-001 .el-button--text{color: #fff} .dropdown_meta_header_skin_menu .el-dropdown-menu__item {padding: 0;}',
          style: {
            // width: '0.45rem',
            position: 'relative'
            // margin: '0 0 0 10px'
            // marginLeft: 10
          },
          dropdownStyle: {
            //弹窗的style样式
            width: '1rem',
            padding: '0.1rem 0',
            textAlign: 'center'
          },
          placement: 'bottom',
          dataSource: {
            skinText: Tech.$t('common.skin')
          },
          created(vm) {
            const themeCacheKey = window.Tech?.theme?.cacheKey || 'TECH-THEME'
            let localTheme = localStorage.getItem(themeCacheKey)
            if (localTheme && localTheme !== 'undefined') {
              localTheme = JSON.parse(localTheme)
              const langVal = localTheme?.langVal || localTheme?.label
              vm.$ds.skinText = langVal ? Tech.$t(`header.${langVal}`) : Tech.$t('common.skin') //缓存适应国际化

              // 判断是否国际化
              if (window?.techUseMultiLang) {
                setTimeout(() => {
                  //拿到皮肤列表
                  let skinLang = vm.$select('container_meta_header_skin')?.data?.items || []
                  let curSkin = skinLang.find((item) => item?.id == localTheme?.options?.id)
                  if (curSkin?.value) {
                    // 设置列表现有的翻译文字
                    vm.$ds.skinText = curSkin.value
                  }
                }, 200)
              }
            }
          },
          bind_on_command: (params) => {
            try {
              if (window.$tech?.skinChangeMenuIconColor) {
                // 皮肤切换更改菜单图标颜色
                const sidebar = params.self.$select('container_meta_sidebar')
                sidebar.$cmd.skinChangeIconColor(sidebar)
                const apps = params.self.$select('sidebar_top_apps_container')
                params.self.instance.$nextTick(() => {
                  apps?.data?.items.forEach((item) => {
                    const button = document.getElementById(item.id + '_button')
                    button.style.filter = 'none'
                    button.style.filter = sidebar.$ds.sidebarIconColor
                  })
                })
              }
            } catch (error) {}
          },
          items: [
            {
              name: 'defaultBtn', // 'customBtn',自定义的按钮，可以是任意的组件
              buttonClose: {
                bind_text: '${$ds.skinText}',
                icon: 'el-icon-arrow-down'
              },
              buttonOpen: {
                bind_text: '${$ds.skinText}',
                icon: 'el-icon-arrow-up'
              }
            },
            {
              type: 'container',
              id: 'container_meta_header_skin',
              commands: {
                syncTabIframeTheme: (vm) => {
                  // console.log(' == syncTabIframeTheme vmId === ', vmId)
                  let tabsObj = vm.$select('tabs_meta_main_content_labels')
                  if (tabsObj?.data?.items) {
                    vm.$select('tabs_meta_main_content_labels').data.items.map((item) => {
                      if (item.type === 'wujie') {
                        window.WujieVue.bus.$emit('TABIFRAME_THEME', {
                          type: 'TABIFRAME_THEME',
                          clickNodeId: vm.data.id
                        })
                      }
                      // iframe 的处理
                      if (item.type === 'iframe') {
                        let iframe = document.getElementById(item.id)
                        iframe.contentWindow.postMessage(
                          {
                            type: 'TABIFRAME_THEME',
                            clickNodeId: vm.data.id
                          },
                          '*'
                        )
                      }
                    })
                    for (let i = 0; i < window.frames.length; i++) {
                      window.frames[i].postMessage(
                        {
                          type: 'TABIFRAME_THEME_WUJIE_DEGRADE',
                          clickNodeId: vm.data.id
                        },
                        '*'
                      )
                    }
                  }
                }
              },
              created: (vm) => {
                vm.data.items = []
                let tmpItems = []
                setTimeout(() => {
                  // console.log(' ==== window.Tech.theme === ', window.Tech.theme)
                  if (window?.Tech?.theme?.list) {
                    window?.Tech?.theme?.list.map((sItem, sIndex) => {
                      let mergeOptions = sItem?.options || {}
                      tmpItems.push({
                        type: 'button',
                        value: sItem.label || '',
                        className: 'header_dropdown_button',
                        style: {
                          height: '0.36rem',
                          width: '100%',
                          padding: '0',
                          margin: '0',
                          border: '0',
                          lineHeight: '0.36rem',
                          color: '#666',
                          fontSize: '0.14rem',
                          backgroundColor: '#fff'
                        },
                        bind_on_click: async (params) => {
                          document.querySelector('body').className = 'skin_red'
                          params.self.$ds.skinText = sItem.label || ''
                          const item = sItem
                          if (!window.Tech.theme) return
                          let theme = window.Tech.theme.class?.[item.value]
                          if (!theme) {
                            console.error(Tech.$t('common.skinError') + item.value)
                          }
                          // if(theme === 'default') document.title = 'IIOT';
                          else if (theme['--title']) document.title = theme['--title']
                          localStorage.setItem('TECH-THEME', JSON.stringify(item))
                          let str = ''
                          let themeClass = {}
                          if (themeClass[item.value]) {
                            document.documentElement.setAttribute('style', themeClass[item.value])
                            var myEvent = new Event('resize')
                            window.dispatchEvent(myEvent)
                            return
                          }
                          if (!themeClass[item.value] && theme !== 'default') {
                            for (let key in theme) {
                              let val = theme[key]
                              // console.log(val, val.startsWith);
                              if (val.startsWith('url(/dependencies')) {
                                if (location.hostname.indexOf('localhost') === -1) {
                                  val = val.replace(
                                    'url(/',
                                    'url(' + process.env.DEPENDENCIES_BASE_URL
                                  )
                                }
                              }
                              str += `${key}:${val};`
                            }
                          }
                          if (!themeClass[item.value]) {
                            // 缓存后，下次使用不需要重新组装
                            themeClass[item.value] = str
                          }
                          document.documentElement.setAttribute('style', str)
                          var myEvent = new Event('resize')
                          window.dispatchEvent(myEvent)
                          document.documentElement.setAttribute('theme', 'themedefault')
                          params.self.$cmd.syncTabIframeTheme(params.self)
                        },
                        ...mergeOptions // 合并全局变量定义的参数选项 window.Tech.theme.list[i]
                      })
                    })
                  }

                  tmpItems.map((skinItem) => {
                    vm.app.updatePageNode(skinItem, vm, () => {
                      vm.data.items.push(skinItem)
                    })
                  })
                  // 去value重复
                  try {
                    let findIds = []
                    let uniName = []
                    vm.data.items.map((fItem, fIndex) => {
                      if (uniName.includes(fItem?.value)) {
                        findIds.push(fIndex)
                      } else {
                        uniName.push(fItem?.value)
                      }
                    })
                    findIds.map((dItem) => {
                      vm.data.items.splice(dItem, 1)
                    })
                  } catch (e) {}
                })

                // 展示头像方法
                const showUserFn = (userInfo) => {
                  if (userInfo) {
                    const userIco = vm.$select('meta_header_user_icon')
                    const profile_text = vm.$select('container_meta_header_user_top_profile_text')
                    const profile_photo = vm.$select('container_meta_header_user_top_profile_photo')
                    // 设置header头像
                    if (userInfo?.avatar && userInfo?.avatar?.bucket && userInfo?.avatar?.key) {
                      //  // 下拉框的头像 和 header的头像
                      let { bucket, key } = userInfo?.avatar
                      profile_photo.data.src = userIco.data.src = `/fileSystem/${bucket}/${key}`
                      profile_text.data.display = false
                      // 25/5/15 给backgroundImage设置图片地址，浏览器会默认发送简单请求获取图片，不会携带orgin，不满足zky安全限制
                      // vm.data.style.backgroundImage = `/api/file/preview?id=${userInfo.avatar.id}&token=${token}`
                    } else {
                      // 如果没有头像则隐藏image
                      userIco.data.display = profile_photo.data.display = false
                      // 展示头像文字
                      profile_text.data.display = true
                      setTimeout(() => {
                        const selfdefine = document.querySelector('#dropdown_meta_header_user .el-dropdown-selfdefine');
                        // 为鼠标进入事件添加监听器
                        selfdefine.addEventListener('mouseenter', function() {
                        // 在这里可以添加其他逻辑，比如改变样式、显示信息等
                        setTimeout(() => {
                          const child = document.createElement('span')
                          child.className = 'dropdown_meta_header_user_suspension_text'
                          child.innerHTML = userInfo?.name
                          selfdefine.appendChild(child)
                        }, 100);
                      });
              
                      // 为鼠标离开事件添加监听器
                      selfdefine.addEventListener('mouseleave', function() {
                        setTimeout(() => {
                          const child = document.querySelector('.dropdown_meta_header_user_suspension_text');
                          selfdefine.removeChild(child)
                        }, 300);
                        });
                      });
                      if (userInfo?.name?.[0]) {
                        const user_name = vm.$select('header_user_name_btn')
                        profile_text.data.value = user_name.data.buttonOpen.text = user_name.data.buttonClose.text = userInfo.name[0]
                      }
                    }

                    // 计算文字的宽度
                    const getTextWidth = (text, font) => {
                      const canvas = document.createElement('canvas')
                      const context = canvas.getContext('2d')
                      context.font = font
                      const metrics = context.measureText(text)
                      return metrics.width
                    }
                    let profile_info = vm.$select('container_meta_header_user_top_profile_info')
                    // 个人名称
                    const nameWidth =  getTextWidth(userInfo.name, '12px')
                    let nameNode = null
                    if (nameWidth > 105) {
                      nameNode = {
                        type: 'tooltip',
                        content: userInfo.name,
                        placement: 'top',
                        items: [
                          {
                            type: 'text',
                            style: { fontSize: '12px', color: '#333333' },
                            value: userInfo.name
                          }
                        ]
                      }
                    } else {
                      nameNode = {
                        type: 'text',
                        style: { fontSize: '12px', color: '#333333' },
                        value: userInfo.name
                      }
                    }
                    profile_info.app.updatePageNode(nameNode, profile_info, () => {
                      profile_info.data.items.push(nameNode)
                    })
                    // 租户名称
                    const companyName = userInfo?.tenant_id?.label || userInfo?.curSgAndRule?.actionScopeName
                    const companyWidth = getTextWidth(companyName, '10px')
                    let companyNode = null
                    if (companyWidth > 105) {
                      companyNode = {
                        type: 'tooltip',
                        content: companyName,
                        placement: 'top',
                        items: [
                          {
                            type: 'text',
                            style: { fontSize: '10px', color: '#999999' },
                            value: companyName
                          }
                        ]
                      }
                    } else {
                      companyNode = {
                        type: 'text',
                        style: { fontSize: '10px', color: '#999999' },
                        value: companyName
                      }
                    }
                    profile_info.app.updatePageNode(companyNode, profile_info, () => {
                      profile_info.data.items.push(companyNode)
                    })
                  }
                }
                // 如果有了profile 就不用走监听
                if (window?.tech?.userInfo?.hasOwnProperty('advancedComponentAdmin')) {
                  showUserFn(window.tech.userInfo)
                } else {
                  window.Tech.tBus.$on('getProfileUserInfo', (userInfo) => {
                    showUserFn(userInfo)
                  })
                }
       
              },
              items: []
            }
          ]
        },
        {
          type: 'container',
          id: 'container_meta_header_user_icon',
          bind_on_click: (params) => {
            document.querySelector('#dropdown_meta_header_user button').click()
          },
          display: true,
          style: {
            width: '0.4rem',
            height: '0.4rem',
            marginLeft: '0.15rem',
            borderRadius: '50%',
            overflow: 'hidden',
            position: 'absolute',
            zIndex: 1
          },
          items: [
            {
              type: 'image',
              id: 'meta_header_user_icon',
              src: '',
              width: '100%',
              height: '100%',
              className: 'user_avatar_icon',
              style: {
                width: '100%',
                height: '100%'
              },
              preview: false,
              created: (vm) => {}
            }
          ]
        },
        {
          type: 'meta-dropdown',
          id: 'dropdown_meta_header_user',
          className: 'dropdown-001',
          dropdownClassName: 'dropdown_meta_header_user_menu',
          css: `
            .dropdown_meta_header_user_menu .el-dropdown-menu__item {
              padding: 0;
            }
            #dropdown_meta_header_user .el-dropdown-selfdefine {
              height: .4rem;
              line-height: .4rem;
              width: .4rem;
              border-radius: 100%;
              background: #fff;
              text-align: center;
              position: relative;
            }

            .dropdown_meta_header_user_suspension_text {
              position: absolute;
              font-size: 12px;
              top: 7px;
              right: 40px;
              line-height: 20px;
              padding: 0 8px;
               justify-content: center;
              align-items: center;
              border-radius: 2px;
              border: 1px solid #F4F4F4;
              background: #FFF;
              box-shadow: 2px 2px 4px 0 #00000033;
              white-space: nowrap;
            }

            #dropdown_meta_header_user .el-dropdown-selfdefine button{
              color: #1E6AFF;
              font-size: 16px;
              font-weight: bold;
              padding: 0;
            }
            .meta-dropdown-css-dropdown_meta_header_user {
              top: .63rem !important;
            }
          `,
          style: {
            position: 'relative',
            // margin: '0 0 0 10px',
            marginLeft: 10
          },
          dropdownStyle: {
            width: '1.3rem',
            padding: '0.1rem 0'
          },
          placement: 'bottom',
          created: (vm) => {
            const curLang = window.Tech.LANG.locale
            if (curLang === 'zh-CN') {
              vm.data.dropdownStyle.width = '2rem'
              vm.data.dropdownStyle.top = '6rem'
            } else {
              vm.data.dropdownStyle.width = '3rem'
              vm.data.dropdownStyle.top = '6rem'
            }
            // 迁移jinfu单点登录不显示用户名问题代码
            window.Tech.tBus.$on('getProfileUserInfo', vm.$cmd.getProfileUserInfo)
          },
          beforeDestroy: (vm) => {
            window.Tech.tBus.$off('getProfileUserInfo', vm.$cmd.getProfileUserInfo)
          },
          items: [
            {
              name: 'defaultBtn', // 'customBtn',自定义的按钮，可以是任意的组件
              id: 'header_user_name_btn',
              buttonClose: {
                text: ''
              },
              buttonOpen: {
                text: ''
              }
            },
            {
              type: 'container',
              id: 'container_meta_header_user_top',
              items: [
                {
                  type: 'container',
                  css: `
                    #container_meta_header_user_top_profile {
                      display: flex;
                      padding: 0px 15px;
                      justify-content: flex-start;
                      margin-bottom: 3x;
                    }
                    #container_meta_header_user_top_profile_info {
                      display: flex;
                      flex-direction: column;
                      line-height: 17px;
                      overflow-x: hidden;
                      cursor: default;
                    }
                    .container_meta_header_user_top_profile_photo {
                      margin-right: 4px;
                      border: 2px solid #F1F1F1;
                      width: .35rem;
                      height: .35rem;
                      border-radius: .5rem;
                    }
                    #container_meta_header_user_top_profile_info span {
                      white-space: nowrap;
                      display: block;
                      overflow: hidden;
                      text-overflow: ellipsis;
                    }

                    #container_meta_header_user_top_profile_text {
                      background: #fff;
                      color: #1E6AFF;
                      border-radius: 100px;
                      padding: 0;
                      width: 0.36rem;
                      height: 0.36rem;
                      margin-right: .05rem;
                      font-size: .14rem;
                      font-weight: bold;
                      display: block;
                      text-align: center;
                      border: 1px solid #e5e5e5;
                      line-height: 0.34rem;
                    }
                  `,
                  id: 'container_meta_header_user_top_profile',
                  items: [
                    {
                      type: 'container',
                      items: [
                        {
                          type: 'image',
                          src: txIcon,
                          className: 'container_meta_header_user_top_profile_photo',
                          id: 'container_meta_header_user_top_profile_photo',
                          preview: false,
                          display: true
                        },
                        {
                          type: 'container',
                          id: 'container_meta_header_user_top_profile_text',
                          display: false,
                          items: [
                            {
                              type: 'text',
                              value: ''
                            }
                          ]
                        },
                      ]
                    },
                    {
                      type: 'container',
                      id: 'container_meta_header_user_top_profile_info',
                      items: []
                    }
                  ]
                },
                {
                  type: 'button',
                  id: 'button_meta_header_user_index',
                  value: Tech.$t('common.home'),
                  style: {
                    width: '100%',
                    height: '0.36rem',
                    padding: '0 0.2rem',
                    margin: '0',
                    border: '0',
                    lineHeight: '0.36rem',
                    color: '#606266',
                    fontSize: '0.14rem',
                    backgroundColor: '#fff',
                    textAlign: 'left',
                    display: 'flex',
                    alignItems: 'center'
                  },
                  className: 'header_dropdown_button',
                  css:
                    '.header_dropdown_button .meta-el-icon-home {width: 0.18rem;height:0.18rem;display: inline-block;background-position: center center; background-repeat: no-repeat; background-size: 100% 100%;background-image: url(' +
                    iconHome +
                    ');}',
                  options: {
                    icon: 'meta-el-icon-home'
                  },
                  bind_on_click: (params) => {
                    const routerBase = window.tech?.global?.routerBase
                    window.location.href = routerBase
                      ? window.location.origin + routerBase
                      : window.location.origin
                  }
                },
                {
                  type: 'button',
                  id: 'button_meta_header_user_rest_pwd',
                  value: Tech.$t('common.changePassword'),
                  style: {
                    width: '100%',
                    height: '0.36rem',
                    paddingLeft: '0.2rem',
                    margin: '0',
                    border: '0',
                    lineHeight: '0.36rem',
                    color: '#606266',
                    fontSize: '0.14rem',
                    backgroundColor: '#fff',
                    display: 'flex',
                    alignItems: 'center'
                  },
                  className: 'header_dropdown_button',
                  css: '.header_dropdown_button .el-icon-edit {display: inline-block;width: 0.14rem;height:0.14rem;font-weight: bold;font-size: 0.12rem;background-position: center center;color: #B9B9B9}',
                  options: {
                    icon: 'el-icon-edit'
                  },
                  bind_on_click: (params) => {}
                },
                {
                  type: 'button',
                  id: 'button_meta_header_user_exit',
                  value: Tech.$t('common.logOut'),
                  style: {
                    width: '100%',
                    height: '0.36rem',
                    paddingLeft: '0.2rem',
                    margin: '0',
                    border: '0',
                    lineHeight: '0.36rem',
                    color: '#606266',
                    fontSize: '0.14rem',
                    backgroundColor: '#fff',
                    display: 'flex',
                    alignItems: 'center'
                  },
                  className: 'header_dropdown_button',
                  css:
                    '.header_dropdown_button .meta-el-icon-exit {display: inline-block;width: 0.14rem;height:0.14rem;background-position: center center;background-repeat: no-repeat;background-size: 100% 100%;background-image: url(' +
                    iconExit +
                    ');}',
                  options: {
                    icon: 'meta-el-icon-exit'
                  },

                  ds_config: {
                    list: [
                      {
                        name: 'logout',
                        type: 'meta',
                        autoRequest: false,
                        method: 'save',
                        options: {
                          // reqControl: {
                          //   path: '/root/rpc/login'
                          // },
                          params: {
                            args: {},
                            service: 'logout',
                            model: 'rbac_user'
                          },
                          reqControl: {
                            showMsg: false
                          }
                        }
                      }
                    ]
                  },
                  bind_on_click: async (params) => {
                    const vm = params.self
                    let args = {}
                    if (window?.tech?.SSO?.logoutType) {
                      args.logoutType = window.tech.SSO.logoutType
                    }

                    // 删除缓存的租户id
                    if (window?.tech?.tenantId) {
                      delete window.tech.tenantId
                    }

                    // 通知子iframe退出登陆
                    if (tech?.TABIFRAME && !tech?.TABIFRAME?.inner) {
                      try {
                        setTimeout(() => {
                          let tabsObj = vm.$select('tabs_meta_main_content_labels')
                          if (tabsObj?.data?.items) {
                            tabsObj.data.items.map((item) => {
                              let tabMenuName = item.menu.name
                              let iframeObj = document.getElementById(tabMenuName + '_iframe_main')
                              if (iframeObj) {
                                iframeObj.contentWindow.postMessage(
                                  {
                                    type: 'TABIFRAME_LOGOUT'
                                  },
                                  tech.TABIFRAME.contentHost
                                )
                              }
                            })
                          }
                        })
                      } catch (e) {}
                    }

                    let res = {}
                    try {
                      res = await vm.request('logout', {
                        args
                      })
                    } catch (e) {
                      console.log(' logout e == ', e)
                    }

                    let instance = vm.instance
                    // 清除数据，菜单数据、tabs页面数据
                    Object.assign(vm.$select('container_meta_sidebar_container').$ds, {
                      activeName: '',
                      appsMenus: [],
                      apps: []
                    })
                    vm.$select('tabs_meta_main_content_labels').data.items = []
                    try {
                      window.Tech.token.reste()
                      instance.$router.push('/')
                      instance.$store.commit('App/reset')
                    } catch (e) {}
                    // instance.$router.push('/')
                    // instance.Tech.token.reste()
                    // instance.$store.commit('App/reset')
                    window.Tech.token.remove()
                    sessionStorage.removeItem('tabs_meta_main_content_labels')

                    // 清除目录缓存
                    vm.$select('menu_meta_siderbar').data.cacheProduct = {}

                    // 清空loadview数据缓存
                    if (window?.tech?.loadViewCache) {
                      window.tech.loadViewCache = null
                    }

                    // 清空自定义权限数据缓存
                    if (window?.tech?.customPermissionCache) {
                      window.tech.customPermissionCache = null
                    }
                    // 清空用户信息
                    if (window?.tech?.userInfo) {
                      window.tech.userInfo = {}
                    }
                    if (res?.data?.redirectUrl && window?.tech?.SSO?.loginUrl) {
                      window.Tech.cookies.remove('userInfo')
                      window.Tech.cookies.remove('sieIiotToken')
                      let appendLocation = window.location.href + '#tryback' // 添加返回标识
                      let logoutUrl =
                        res.data.redirectUrl +
                        '?service=' +
                        encodeURIComponent(
                          window.tech.SSO.loginUrl +
                            '?location=' +
                            encodeURIComponent(appendLocation)
                        )
                      window.location.replace(logoutUrl)
                    } else {
                      let cleanCache = () => {
                        try {
                          // 补充清理缓存解决苹果电脑退出登录问题
                          window.Tech.cookies.remove('userInfo')
                          window.localStorage.removeItem('userInfo')
                          window.localStorage.removeItem('token')
                          window.localStorage.removeItem('userInfoMore')
                          window.localStorage.removeItem('username')
                        } catch (e) {}
                      }
                      if (!window.$wujie && window.tech?.checkVersion?.autoCheck == true) {
                        sessionStorage.setItem('nextLoginUpdate', null)
                        cleanCache()
                        cleanCache = null
                        window.location.reload()
                      } else {
                        cleanCache()
                        cleanCache = null
                        vm.app.openPage('page_meta_login')
                        // if (window?.techUseMultiLang) { // 退出登录，如果是多语言，则刷新页面
                        // window.location.reload()
                        // }
                      }
                    }
                  }
                }
              ]
            }
          ]
        },
        {
          type: 'container',
          id: 'pop_top_rest_pwd_container',
          items: []
        }
      ]
    }
  ]
}
