export default {
  // 密码到期提醒弹窗
  type: 'dialog',
  showCancel: true,
  id: 'container_password_expire_remind',
  width: '35%',
  title: Tech.$t('common.passwordExpirationDays'),
  display: false,
  bind_on_opreates: async (params) => {
    const { self: vm, value } = params
    if (value.type === 'confirm') {
      // 打开修改密码弹窗
      vm.$select('button_meta_header_user_rest_pwd').instance.click()
    }
    value.close()
  },
  items: [
    {
      type: 'text',
      id: 'container_password_expire_notice_text',
      value: ''
    }
  ]
}
