export default {
  // 保存个人查询方案弹窗
  type: 'dialog',
  id: 'dialog_meta_table_save_search_scheme',
  width: '25%',
  title: Tech.$t('seniorTable.saveIndividualQueryPlan'),
  display: false,
  hasFooter: true,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  bind_on_opreates: async (params) => {
    const { self: vm, value } = params
    if (value.type === 'cancel') {
      value.close()
    } else {
      // 保存个人查询
      const idPre = vm.$cmd.getIdPre(vm)
      const saveForm = vm.$select(idPre + 'form_meta_table_save_search')
      const commonForm = vm.$select(idPre + 'form_main_table_search_common')
      const dropdownForm = vm.$select(idPre + 'form_main_table_search_dropdown')
      const formVal = await saveForm.instance.submit()
      console.log('---- formVal.isOpen', formVal.isOpen)
      formVal.isOpen = !!formVal.isOpen
      let searchData = {
        // 缓存搜索的数据
        tableFilter: commonForm.$ds.tableFilter,
        tableFilterTags: commonForm.$ds.tableFilterTags,
        formData: { ...commonForm.$ds.form, ...dropdownForm?.$ds.form }
      }
      let params = {
        args: {
          values: {
            signId: `${commonForm.$ds.tableView.data.views?.search.view_id}&${vm.$cmd.getIdPre(
              vm
            )}container_table_search`,
            signType: 'searchScheme',
            signContent: JSON.stringify(searchData),
            ...formVal
          }
        },
        model: 'rbac_user_prefer',
        tag: 'master',
        service: 'saveScheme',
        app: 'iidp-user-prefer'
      }
      const res = await commonForm.request('saveScheme', params)
      if (res.error) {
        window.ELEMENT.Message.error(res.error.message)
      } else {
        window.ELEMENT.Message.success(Tech.$t('common.saveSuccess'))
      }
      Object.keys(saveForm.$ds.form).forEach((key) => {
        // 清空表单数据
        saveForm.$ds.form[key] = null
      })
      value.close()
    }
  },
  items: [
    {
      type: 'form',
      id: 'form_meta_table_save_search',
      formConfig: {
        inline: false,
        labelPosition: 'left',
        labelWidth: '80px'
      },
      dataSource: {
        form: { name: '', description: '', isOpen: false },
        isAdmin: false
      },
      created: (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        const pageVm = vm.$select(idPre + 'container_main_content')
        vm.$ds.isAdmin = pageVm.$ds.isAdmin
      },
      items: [
        {
          type: 'input',
          text: Tech.$t('seniorTable.schemeName'),
          require: true,
          name: 'name',
          rules: [
            {
              required: true,
              trigger: 'blur',
              message: Tech.$t('seniorTable.pleaseEnterSchemeName')
            }
          ]
        },
        {
          type: 'input',
          text: Tech.$t('seniorTable.schemeDescription'),
          name: 'description'
        },
        {
          type: 'switch',
          text: Tech.$t('seniorTable.whetherToSetItToPublicSolution'),
          name: 'isOpen',
          bind_display: '$ds.isAdmin',
          style: {
            height: '32px'
          }
        }
      ]
    }
  ]
}
