export function openDropdown() {
  let view = {
    type: 'meta-dropdown',
    hideOnClick: false,
    // buttonControl: true,
    layoutStyle: {
      width: '100%'
    },
    style: {
      // width: '100%'
    },
    contentStyle: {
      width: '100%'
    },
    dropdownStyle: {
      marginTop: '0.6rem',
      width: '100%',
      // width: '5rem',
      minWidth: '4.5rem',
      padding: 0,
      // position: 'fixed',
      // width: '5.6rem',
      'z-index': 1000
    },
    bind_on_visibleChange: (params) => {
      if (params.value && params.self?.data?.items?.[1]) {
        params.self.data.items[1].display = false
        params.self.instance.$nextTick(() => {
          params.self.data.items[1].display = true
          window.setTimeout(() => {
            params.self?.instance?.tBus?.$emit('triggerContainerShow')
          }, 300)
        })
      }
    },
    created: (vm) => {
      vm.$ds.selectObj = null // 每次创建时重置选中值
      vm.$ds.defaultCheck = []

      // 隐藏 搜索tag列表栏
      // let searchTagsList = vm.$select('role_select_remark_tb_bTSearch_form_main_table_search');
      // searchTagsList.data.style.display = 'none';
    },
    dataSource: {
      selectObj: null,
      defaultCheck: []
    },
    items: [
      {
        type: 'form-container', // container form-container
        id: 'dropdown_control',
        __name: 'custom', // 使用meta-dropdown组件第一个自定义item
        items: []
      },
      {
        type: 'container',
        id: 'dropdown_content',
        items: []
      }
    ]
  }
  return view
}
