export default {
  // 分表策略管理 取值模型字段 弹窗选择器扩展
  shard_strategy_menu_pre_container_main_content: {
    selector: {
      attr: 'id',
      value: 'shard_strategy_menu_pre_table_main'
    },
    beforeOperate: (app, operateItem, options) => {
      options.element.css = `
        #shard_strategy_menu_pre_container_main_content {
          display: flex
        }
        #shard_strategy_menu_pre_container_main_content_tree {
         height: calc(100% - 7px) !important

        }
        #shard_strategy_menu_pre_container_main_content {
          height: auto !important
        }
        #shard_strategy_menu_pre_container_main_content_tree .ii-tree-main {
          overflow: auto;
          width: 200px;
        }
       #shard_strategy_menu_form_main_detail_top_common_items_0_items_modelMetaId_view_customClick .body {
          overflow: hidden;
          height: calc(-300px + 100vh);
        }
        #shard_strategy_menu_form_main_detail_top_common_items_0_items_modelMetaId_view_customClick .body>div,
        #shard_strategy_menu_form_main_detail_top_common_items_0_items_modelMetaId_view_customClick .body>div>div,
        #shard_strategy_menu_form_main_detail_top_common_items_0_items_modelMetaId_view_customClick .body>div>div>div,
        #shard_strategy_menu_form_main_detail_top_common_items_0_items_modelMetaId_view_customClick .body>div>div>div>div{
          height: 100%;
          overflow: hidden;
        }
        #shard_strategy_menu_pre_table_main {
          overflow-x:auto;
        }
        #shard_strategy_menu_pre_table_toolbar_create, #shard_strategy_menu_pre_table_toolbar_delete {
          display: none
        }
        #shard_strategy_menu_pre_table_main {
          width: 100%
        }
        #shard_strategy_menu_pre_table_main_toolbar {
          display: none !important
        }
      `
      let tableDataDsConfig = options.element.ds_config.list.find(
        (item) => item.name === 'tableData'
      )
      if (!options._ui_view_seed_menu_table_main_reqPrep) {
        options._ui_view_seed_menu_table_main_reqPrep = true
        let srcFn = tableDataDsConfig.reqPrep

        tableDataDsConfig.reqPrep = (vm, options, config) => {
          options.params.args.value = {
            keyword: null,
            appName: vm.$ds?.currentAppName || '',
            type: vm.$ds?.currentAppType || '',
            metaId: vm.$ds?.metaId,
            appTag: vm.$ds?.appTag || ''
          }
          options.params.model = 'tenant_action_dimension'
          options.params.service = 'getModelNameByApp'
          options.params.app = 'sie-snest-tenant'
          let table_main_table = vm.$select('shard_strategy_menu_pre_table_main_table')
          let index = table_main_table.data.items.findIndex((item) => item?.name == 'operate')

          if (index > -1) {
            table_main_table.data.items.splice(index, 1)
          }
          srcFn(vm, options, config)
        }
      }
      let tableDataDsConfigs = options.element.ds_config.list.find(
        (item) => item.name === 'tableView'
      )
      tableDataDsConfigs.reqAfter = operateItem.view.ds_config.list[1].reqAfter
      return operateItem.view
    },
    type: 'before',
    view: {
      type: 'tree',
      toolbarConfig: {
        search: true // 显示搜索项
      },
      id: 'shard_strategy_menu_pre_container_main_content_tree',
      ds_config: {
        list: [
          {
            type: 'meta',
            name: 'modelMetaTreeData',
            autoRequest: true,
            options: {
              params: {
                args: {
                  useDisplayForModel: true
                },
                service: 'listApp',
                app: 'sie-iidp-datasource',
                model: 'base_shard_strategy'
              }
            },
            reqAfter: (vm, res, config) => {
              if (res?.data) {
                const getParentIds = (list, id) => {
                  return list.reduce((ids, item) => {
                    if (item.id === id) {
                      ids.push(item.id)

                      if (item.parentId) {
                        return ids.concat(getParentIds(list, item.parentId))
                      }
                    }
                    return ids
                  }, [])
                }
                // 默认选中处理
                const checkHandler = async () => {
                  setTimeout(() => {
                    const tabTree = vm.$select(
                      'shard_strategy_menu_pre_container_main_content_tree'
                    )
                    const formNode = vm.$select(
                      'shard_strategy_menu__drawer_form_main_detail_top_common'
                    )
                    if (formNode && tabTree?.instance) {
                      const treeNode = tabTree?.instance.$refs.tree
                      // 获取表单的数据信息 - 来源接口 search
                      const mainTableRowData = formNode.$ds.mainTableRowData
                      const appId = mainTableRowData.appId
                      // 获取appId以及所有父级信息
                      const parentIds = getParentIds(res.data, appId)
                      // 如果没有节点信息就不继续执行
                      if (parentIds.length <= 0) return false
                      try {
                        // 展开所有父级节点信息
                        parentIds.forEach((id) => (treeNode.store.nodesMap[id].expanded = true))
                        // 设置选择的节点信息
                        tabTree.instance.setCurrentKey(parentIds[0])
                        setTimeout(() => {
                          // 默认进行点击选中信息
                          tabTree?.instance.$el.querySelector('.is-current').firstChild.click()

                          setTimeout(() => {
                            const vxeTable = vm.$select('shard_strategy_menu_pre_table_main_table')
                            const item = vxeTable.instance.tableData.find(
                              (item) => item.metaId === formNode.$ds.modelMetaId
                            )
                            // 清除所有的选择
                            vxeTable.instance.$refs.xGrid.clearRadioRow()
                            // 设置当前选中
                            vxeTable.instance.$refs.xGrid.setRadioRow(item)
                            // 主动触发事件
                            vxeTable.instance.radioChange()
                          }, 5e2)
                        }, 3e2)
                      } catch (e) {
                        checkHandler()
                      }
                    }
                  }, 2e2)
                }
                checkHandler()

                return res.data
              }
            }
          },
          {
            name: 'tableView',
            reqAfter: async (vm, res, config) => {
              if (res?.data) {
                res.data.views.grid.body.columns = res.data.views.grid.body.columns.filter(
                  (item) => item.name == 'name'
                )
                res.data.views.search.body.columns = res.data.views.search.body.columns.filter(
                  (item) => item.name == 'name'
                )
                res.data.fields.name.displayName = Tech.$t('actionScope.modelName')
                return res
              }
            }
          }
        ]
      },
      dataSource: {
        modelMetaTreeData: [],
        currentAppName: null
      },
      transformTotree: true,
      bind_data: '$ds.modelMetaTreeData',
      bind_on_clickTreeNode: (params) => {
        let { self: vm, value } = params
        let tableMain = vm.$select('shard_strategy_menu_pre_table_main')
        tableMain.$ds.currentAppName = value.selectedData.data?.appName || null
        tableMain.$ds.currentAppType = value.selectedData.data?.type || null
        tableMain.$ds.currentAppId = value.selectedData.data?.id || null
        tableMain.$ds.appTag = value.selectedData.data?.appTag || null
        tableMain.$ds.metaId = value.selectedData.data?.metaId || null
        tableMain.request('tableData')
      }
    }
  }
}
