import getOnlyLookRequired from '../../../from-fields/form/onlyLookRequired'

export function openDialog() {
  let view = {
    // view视图协议 里面的click行为协议
    // 弹窗
    type: 'dialog',
    width: '',
    title: '',
    display: true,
    dataSource: {
      selectObj: null,
      defaultCheck: []
    },
    hasFooter: true,
    showConfirm: true,
    showCancel: true,
    confirmText: Tech.$t('toolbar.dialogConfirm'),
    cancelText: Tech.$t('toolbar.dialogCancle'),
    customButtons: [], // 弹框确认按钮前配置按钮
    customMiddleButtons: [], // 弹框确认按钮和取消按钮中间配置按钮
    created(vm) {
      vm.$ds.openView = vm.data.openView
      vm.data.title = vm.data.openView.title
      vm.data.hasFooter = vm.data.openView.hasFooter === false ? false : true
      vm.data.showConfirm = vm.data.openView.showConfirm === false ? false : true
      vm.data.showCancel = vm.data.openView.showCancel === false ? false : true
      vm.data.confirmText = vm.data.openView.confirmText || Tech.$t('toolbar.dialogConfirm')
      vm.data.cancelText = vm.data.openView.cancelText || Tech.$t('toolbar.dialogCancle')
      vm.data.width = vm.data.openView.width || '80%'
      vm.data.marginTop = vm.data.openView.marginTop || 130
      if (vm.$ds.openView?.showSaveAndCreate) {
        vm.data.customButtons = [
          {
            text: Tech.$t('detailView.createdSave'),
            action: 'saveAndCreate'
          }
        ]
      }
      const tableMain = vm.$select(vm.$ds.__fromIdPre + 'table_main')
      if (tableMain) {
        // 判断是不是显示只看必填项
        const isOnlyLookRequired =
          tableMain?.$ds?.tableView?.data?.views?.form?.body.onlyLookRequired || false
        if (isOnlyLookRequired) {
          setTimeout(() => {
            const curForm = vm.$select(vm.$ds.idPre + 'form_main_detail_top_common')
            if (curForm) {
              const config = getOnlyLookRequired()
              // 更换ID
              config.id = vm.$ds.idPre + config.id
              config.mounted = (_vm) => {
                const checkEl = _vm?.instance?.$el
                if (checkEl) {
                  const choiceDialogEl = vm?.instance?.$el?.querySelector?.('#choice-dialog')
                  if (choiceDialogEl) {
                    const footerEl = choiceDialogEl.querySelector('.footer')
                    if (footerEl) {
                      footerEl.style.alignItems = 'center'
                      checkEl.style.marginRight = '16px'
                      footerEl.insertBefore(checkEl, footerEl.firstChild)
                    }
                  }
                }
              }
              // 添加只看必填项节点
              vm.app.updatePageNode(config, vm, () => {
                vm.data.items.push(config)
              })
            }
          }, 200)
        }
      }
    },
    mounted(vm) {},
    items: [],
    ds_config: {
      list: [
        {
          name: 'confirm',
          type: 'meta',
          options: {
            params: {}
          }
        }
      ]
    },
    commands: {
      saveGride: (vm) => {},
      saveForm: () => {},
      // 搜索展开项样式设置
      addClass: (vm, params, preId, key) => {
        tech_app.utils.addClass(
          key,
          `
          .meta-dropdown-css-${preId}form_main_table_search_btn, 
          .meta-dropdown-css-${preId}container_table_search_wrap_items_1,.meta-dropdown-css-${preId}form_main_table_search_btn li,.meta-dropdown-css-${preId}container_table_search_wrap_items_1 li,
          .meta-dropdown-css-${preId}form_main_table_search_btn li:hover,.meta-dropdown-css-${preId}container_table_search_wrap_items_1 li:hover{
            z-index: 2210!important;
          }
          .meta-dropdown-css-${preId}dropdown_pop_form {
            left: ${params.left}px !important;
            width: ${params.width}px !important;;
            transform-origin: center center;
            background: none !important;
            padding: 0 !important;
            border: 0 !important;
            -webkit-box-shadow: none!important;
            box-shadow: none!important;
            top: ${params.top}px !important;
            display: flex;
            align-items: center;
            justify-content: center;
            z-index: 2210!important;
          }
          .meta-dropdown-css-${preId}dropdown_pop_form li  {
            width: ${params.width}px !important;
            -webkit-box-shadow: 0 0.04rem 0.11rem #eaeaea !important;
            box-shadow: 0 0.04rem 0.11rem #eaeaea !important;
            background: #fff !important;
            z-index: 2210!important;
          }
          .meta-dropdown-css-${preId}dropdown_pop_form li:hover{
            -webkit-box-shadow: 0 0.04rem 0.11rem #eaeaea !important;
            box-shadow: 0 0.04rem 0.11rem #eaeaea !important;
            background: #fff !important;
            z-index: 2210!important;
          }
      `
        )
      },
      // 兼容接口返回的 message 格式
      getResMessage: (messageData) => {
        let finalMessage = Tech.$t('detailView.successHint')
        if (typeof messageData === 'string') {
          finalMessage = messageData
        } else if (typeof messageData === 'object' && messageData !== null) {
          finalMessage = messageData?.text
        }
        return finalMessage
      }
    },
    bind_on_opreates: async (params) => {
      const { self: vm, value } = params
      if (value?.type == 'cancel') {
        vm.data.display = false
      }

      // 编辑并新增按钮
      if (value?.type == 'saveAndCreate') {
        const table_detail = vm.$select(`${vm.$ds.idPre}table_detail`)
        // 默认情况
        // 表单，点击详情页面保存并新增按钮
        if (table_detail?.$ds?.isSingleFormView) {
          const saveBtn = table_detail.$select(`${vm.$ds.idPre}form_main_detail_top_save_add`)
          let result = await saveBtn.$cmd.saveForm({ self: saveBtn })
          if (saveBtn.$ds.isFormSucc) {
            if (result?.data?.message) {
              let finalMessage = vm?.$cmd?.getResMessage(result?.data?.message)
              window.ELEMENT.Message.success(finalMessage)
            } else {
              window.ELEMENT.Message.success(Tech.$t('detailView.successHint'))
            }
          }
        }
      }

      if (value?.type == 'confirm') {
        if (vm.$ds?.openView?.isFromTable) {
          return
        }
        let result = {}
        const table_detail = vm.$select(`${vm.$ds.idPre}table_detail`)
        // 默认情况
        // 表单，点击详情页面保存按钮
        if (table_detail?.$ds?.isSingleFormView) {
          const saveBtn = table_detail.$select(`${vm.$ds.idPre}form_main_detail_top_save`)
          result = await saveBtn.$cmd.saveForm({ self: saveBtn })
          if (!saveBtn.$ds.isFormSucc) {
            return
          }
          if (result?.data?.message) {
            let finalMessage = vm?.$cmd?.getResMessage(result?.data?.message)
            window.ELEMENT.Message.success(finalMessage)
          } else {
            window.ELEMENT.Message.success(Tech.$t('detailView.successHint'))
          }
        }

        // 表格情况
        if (vm.$ds?.openView?.type?.indexOf('grid') > -1) {
          // 配置api情况
          // 防重点
          if (vm._savingForm) {
            return
          }
          vm._savingForm = true
          if (vm._savingFormTimer) {
            window.clearTimeout(vm._savingFormTimer)
            vm._savingFormTimer = null
          }
          vm._savingFormTimer = window.setTimeout(() => {
            if (params?.self) {
              vm._savingForm = false
            }
          }, 2500)
          // loading初始化
          let loadingInstance = null
          let loadingOptions = { text: Tech.$t('detailView.saveLoading') }
          if (!loadingInstance && !vm.$ds?.openView?.gridNoLoading) {
            loadingInstance = window.ELEMENT.Loading.service(loadingOptions)
          }
          // 主表格
          const mainTableNode = vm.$select(vm.$ds.idPre + 'table_main_wrap')
          // save配置
          const gridSaveConfig = vm.$ds?.openView?.api?.grid?.save
          if (gridSaveConfig) {
            const originParams = {
              model: vm.$ds.openView.model,
              service: 'search'
            }
            result = await vm.$cmd.meta.openViewApi({
              apiConfig: gridSaveConfig,
              vm: mainTableNode,
              dsConfigName: 'confirm',
              originParams
            })
            if (result?.error) {
              window.ELEMENT.Message.error(result?.error?.message ?? Tech.$t('common.requestEr'))
              // 关闭loading
              loadingInstance?.close()
              return
            }
            if (result?.data?.message) {
              let finalMessage = vm?.$cmd?.getResMessage(result?.data?.message)
              window.ELEMENT.Message.success(finalMessage)
            } else {
              window.ELEMENT.Message.success(Tech.$t('detailView.successHint'))
            }
          }
          if (vm._savingFormTimer) {
            window.clearTimeout(vm._savingFormTimer)
            vm._savingFormTimer = null
          }
          vm._savingForm = false
          // 关闭loading
          loadingInstance?.close()
        }
        // 自定义确认按钮事件
        let cusConfirm = vm.$ds.openView.confirm
        if (cusConfirm) {
          if (Object.prototype.toString.call(cusConfirm) === '[object String]') {
            try {
              cusConfirm = window.tech_app.utils._cloneDeep(vm.$ds.openView.confirm)
              cusConfirm = new Function('return ' + cusConfirm)()
            } catch (error) {
              console.log(' === openView Api reqPrep error == ', error)
            }
          }
          const ctnVm = vm.$select(`${vm.$ds.idPre}container_main`)
          let confirmResult = undefined
          if (ctnVm.$cmd.isAsync(cusConfirm)) {
            confirmResult = await cusConfirm(vm, result)
          } else {
            confirmResult = cusConfirm(vm, result)
          }
          if (confirmResult === false) {
            return
          }
        }

        vm.data.display = false
      }
    },
    bind_on_setDropdownOffset: (params) => {
      // 弹框拖动时，隐藏展开项
      const dropdownObj = params.self.$select(
        params.self.$ds?.openView?.preId + 'dropdown_pop_form'
      )
      if (dropdownObj?.$ds?.isOpen) {
        if (dropdownObj?.instance?.setOpen) {
          dropdownObj.instance.setOpen(false)
        }
      }
    }
  }
  return view
}
