import cloneDeep from 'lodash/cloneDeep'

// 处理表单匹配正则
const dealFormReg = (param, formObj, form = {}, linkageObj = {}) => {
  let appendParams = {}
  if (linkageObj?.appendParamsFn) {
    try {
      if (Object.prototype.toString.call(linkageObj.appendParamsFn) === '[object String]') {
        try {
          linkageObj.appendParamsFn = new Function('return ' + linkageObj.appendParamsFn).bind(
            window
          )
        } catch (e) {
          console.log(' === change appendParamsFn function error == ', e)
        }
      }
      appendParams = linkageObj.appendParamsFn(formObj)
      try {
        if (typeof appendParams === 'function') {
          appendParams = appendParams(formObj)
        }
      } catch (e) {
        console.log(' === appendParams   fn err == ', appendParams)
      }
      console.log(' === appendParams == ', appendParams)
    } catch (e) {
      console.log(' === appendParamsFn err == ', linkageObj.appendParamsFn)
    }
  }
  let id = ''
  if (form?.vm?.$ds?.mainTableRowData?.id !== undefined) {
    id = form.vm.$ds.mainTableRowData.id
  }
  let appendSearchForm = {} // 拼接搜索上下表单项情况
  try {
    if (form?.config?.[0]?.id) {
      let tmpId = form.config[0].id
      let tmpPre = tech_app.page.getNode(tmpId)?.$ds?.idPre
      if (tmpPre && tmpId.indexOf('form_main_table_search_dropdown') !== -1) {
        // 需要拼接搜索的上表单
        let topForm = tech_app.page.getNode(tmpPre + 'form_main_table_search_common')
        appendSearchForm = topForm?.$ds?.form || {}
      } else if (tmpPre && tmpId.indexOf('form_main_table_search_common') !== -1) {
        // 需要拼接搜索的下表单
        let bottomForm = tech_app.page.getNode(tmpPre + 'form_main_table_search_dropdown')
        appendSearchForm = bottomForm?.$ds?.form || {}
      }
    }
  } catch (e) {
    // console.log(' === 联动 拼接搜索上下表单项情况 error == ', e)
  }
  let newFormObj = {
    id,
    ...appendSearchForm,
    ...formObj,
    ...appendParams
  }
  for (let formKey in newFormObj) {
    let reg = new RegExp('\\$\\{' + formKey + '\\}', 'g')
    let paramType = Object.prototype.toString.call(param)
    if (paramType === '[object Object]' || paramType === '[object Array]') {
      let paramStr = JSON.stringify(param)
      paramStr = paramStr.replace(reg, newFormObj[formKey])
      param = JSON.parse(paramStr)
    } else {
      let distParamType = Object.prototype.toString.call(newFormObj[formKey])
      if (
        linkageObj?.assign && // 配置 assign 则可以直接赋值
        (distParamType === '[object Object]' || distParamType === '[object Array]')
      ) {
        param = newFormObj[formKey]
      } else {
        param = param.replace(reg, newFormObj[formKey])
      }
    }
  }
  return param
}

// 获取联动参数 与替换模板
export const getLinkageParams = (config, f) => {
  // config 为itemConfig
  let reObj = {}
  if (config?.linkage?.type === 'filter') {
    reObj = []
    // 替换参数模板 filter 情况
    if (config?.linkage?.params) {
      // console.log(' ===== f ===== ', f);
      setLinkageFilter(config, f?.values || {}, f)
    }

    if (config?.linkage?.__filter) {
      reObj = config.linkage.__filter
    }
  } else {
    // 替换参数模板 params 情况
    if (config?.linkage?.params) {
      setLinkageParams(config, f?.values || {}, f)
    }

    if (config?.linkage?.__params) {
      reObj = config.linkage.__params
    } else if (config?.linkage?.params) {
      reObj = config.linkage.params
    }
  }
  return reObj
}

// 设置联动参数 与替换模板 filter情况
export const setLinkageFilter = (config, formObj, form) => {
  // config 为itemConfig
  if (config?.linkage?.params) {
    let getParams = cloneDeep(config.linkage.params)
    let newParams = []
    // console.log(' ==== formObj === ', formObj);
    // console.log(' ==== config === ', config);
    // 把params里面的数组取出
    for (let i = 0; i < getParams.length; i++) {
      if (Object.prototype.toString.call(getParams[i]) === '[object Array]') {
        let paramType = Object.prototype.toString.call(getParams[i][2])
        if (
          getParams[i]?.[2] &&
          (paramType === '[object String]' ||
            paramType === '[object Object]' ||
            paramType === '[object Array]')
        ) {
          // for (let formKey in formObj) {
          //   let reg = new RegExp('\\$\\{'+formKey+'\\}','g');
          //   getParams[i][2] = getParams[i][2].replace(reg, formObj[formKey]);
          // }
          getParams[i][2] = dealFormReg(getParams[i][2], formObj, form, config.linkage)
          if (getParams[i][2].indexOf('${') !== -1) {
            console.log(' 替换filter模板参数有误 ', i, config)
          }
        }
        if (getParams[i]?.[2] !== 'null' && getParams[i]?.[2] !== '') {
          newParams.push(getParams[i])
        }
      }
    }

    config.linkage.__filter = newParams
    // console.log(' === config === ', config);
    // reObj = config.__params;
  }
}

// 设置联动参数 与替换模板 params情况
export const setLinkageParams = (config, formObj, form) => {
  // config 为itemConfig
  if (config?.linkage?.params) {
    let srcParams = cloneDeep(config.linkage.params)
    let newParams = {}
    for (let k in srcParams) {
      let tmp = srcParams[k]
      let paramType = Object.prototype.toString.call(tmp)
      if (
        tmp &&
        (paramType === '[object String]' ||
          paramType === '[object Object]' ||
          paramType === '[object Array]')
      ) {
        // for (let formKey in formObj) {
        //   let reg = new RegExp('\\$\\{'+formKey+'\\}','g');
        //   tmp = tmp.replace(reg, formObj[formKey]);
        // }
        tmp = dealFormReg(tmp, formObj, form, config.linkage)
      }
      if (tmp !== 'null') {
        newParams[k] = tmp
      }
      if (tmp.indexOf('${') !== -1) {
        console.log(' 替换params模板参数有误 ', k, config)
      }
    }
    config.linkage.__params = newParams
    // console.log(' === config === ', config);
    // reObj = config.__params;
  }
}

// 检测form字段变化
export const checkFormChange = (compConfig, itemConfig, modelMeta) => {
  if (
    itemConfig?.onChange &&
    Object.prototype.toString.call(itemConfig.onChange) === '[object String]'
  ) {
    try {
      itemConfig.onChange = new Function('return ' + itemConfig.onChange)()
      compConfig.onChange = itemConfig.onChange
    } catch (e) {
      console.log(' === config.onChange error == ', config.onChange, e)
    }
  }
  if (!compConfig?.onChange && itemConfig?.linkage) {
    let linkage = itemConfig.linkage
    compConfig.onChange = async (f, v) => {
      let formObj = f?.values || {}
      // 清空联动的孩子
      if (linkage?.children) {
        for (let i = 0; i < linkage.children.length; i++) {
          let getChildName = linkage.children[i]
          formObj[getChildName] = null
          let getChildNameValues = getChildName + '___values'
          if (formObj[getChildNameValues]) {
            formObj[getChildNameValues] = null
          }
        }
      }
    }
  }
}
