// 模板应用的openView协议的实现
export const templateOpenView = async (element, eventName, params) => {
  let view = element?.data?.view?.[eventName] // view协议视图
  if (view && !view?.__originView) {
    const selectVm = element?.$select(element?.$ds?.operateId)
    // 如果是从工作流打开的openView，关闭openView中的isFlowFormView
    if (selectVm?.$ds?.isFlowFormView) {
      element.$ds.isFlowFormView = false
    }
    view.__originView = window.Tech._cloneDeep(view)
  }
  element.$ds.firstOpen = true
  if (!view) return
  let showType = params.showType
  // let model = params.model;
  // let type = params.type;
  if (!params.view && params.type) {
    // 补全view参数与loadmenu接口一致
    params.view = params.type
  }
  if (params.view && !params.type) {
    // 补全type参数
    params.type = params.view
  }
  let containerView = null
  let containerItems = null
  switch (showType) {
    case 'dialog': // 弹窗展开情况
      containerView = openDialog()
      containerItems = containerView.items
      // appendStyle('tech-dialog', params?.zIndex)
      break
    case 'drawer': // 抽屉展开情况
      containerView = openDrawer()
      containerItems = containerView.items[1].items
      // appendStyle('tech-drawer', params?.zIndex)
      break
    case 'dropdown': // 下拉展开情况
      containerView = openDropdown()
      containerItems = containerView.items[1].items
      let dataCopy = window.Tech._cloneDeep(element.data)
      // console.log(' === eventName == ', eventName);
      delete dataCopy.view[eventName]
      let dataCopy2 = window.Tech._cloneDeep(dataCopy)
      delete dataCopy2.id
      delete dataCopy2.name
      delete dataCopy2.view
      delete dataCopy2.text
      delete dataCopy2.dataSource
      containerView = {
        ...dataCopy2,
        ...containerView
      }
      // console.log(' ==== dataCopy === ', dataCopy);
      dataCopy['__notUseView_' + eventName] = true
      containerView.items[0].items.push(dataCopy)
      // appendStyle('tech-dropdown-pop', params?.zIndex)
      break
    default: // 普通容器展开清空
      containerView = container()
      containerItems = containerView.items
      // appendStyle('choice-dialog-wrapper', params?.zIndex)
      break
  }

  // insertPage 原来的页面视图逻辑放进containerItems 则 containerView的items
  let idPre =
    view.idPre ||
    view.preId ||
    view.addId ||
    params.idPre ||
    params.preId ||
    params.addId ||
    params.name
  let addView = insertPage(params, idPre)
  // openView 无界情况
  if (params?.micro?.type == 'wujie') {
    let app = params?.micro?.info
    let dynamicWujie = vm.$cmd.meta.views.wujie
    let wujiePage = window.Tech._cloneDeep(dynamicWujie)
    let wujiePageParent = vm.$select(app.id + app.sequence + app.model + '_items_0')
    let insertLoading = wujiePageParent?.data?.loadingInstance ? false : true
    let wujiePageContainer = null
    if (insertLoading) {
      let insertId = app.id + app.sequence + app.model + '_wujie_container'
      wujiePageContainer = {
        type: 'container',
        id: insertId,
        loadingInstance: null,
        items: []
      }
      wujiePageContainer.items.push(wujiePage)
      wujiePageContainer.mounted = (vm) => {
        let loading = document.getElementById(insertId)
        wujiePageParent = vm.$select(insertId)
        wujiePageParent.data.loadingInstance = window.ELEMENT.Loading.service({
          target: loading,
          background: '#FFF'
        })
      }
    }
    // wujiePage.url = app.url
    wujiePage.name = app.label || ''
    wujiePage.props = app?.wujieConfig?.props || {}
    wujiePage.idPre = idPre
    wujiePage.id = wujiePage.idPre + wujiePage.id
    wujiePage.wujieName = app.name + wujiePage.id
    wujiePage.menu = app
    wujiePage.props.model = app.model
    wujiePage.props.view = app.view
    wujiePage.props.viewType = 'openView'
    let microConfig = {
      micro: 'wujie',
      insert: 'self',
      notify: 'wujie',
      api: 'restful'
    }
    wujiePage.microApp = createMicroApp(microConfig)
    wujiePage.beforeDestroy = (vm) => {
      vm.data.microApp = null
    }
    let appsMenus = vm.$select('search_menus_pop_container').$ds.appsMenus

    function getPath(menu) {
      let parent = appsMenus.find((item) => item.id == menu.parent_ids)
      app.path = `/${parent.name}` + app.path
      if (parent.parent_ids) {
        getPath(parent)
      }
    }
    function noMatchMenu() {
      // 无匹配菜单关闭loading并提示
      wujiePageParent?.data?.loadingInstance.close()
      window.ELEMENT.Message.error(Tech.$t('detailView.noMenuData'))
    }
    if (!app.menuId) {
      noMatchMenu()
      return
    }
    let menu = appsMenus.find((item) => item.id == app.menuId)
    if (!menu) {
      noMatchMenu()
      return
    }
    app.path = `/${menu.name}`
    if (menu) getPath(menu)
    app.url = app.path
    wujiePage.url = tech.routerBase + wujiePage.microApp.getWujieUrl(app, vm.instance?.$route || '')
    if (params.clickType && params.type) {
      let tabId = app.id + app.sequence + app.model
      wujiePage.url += `?clickType=${params.clickType}&view=form&id=${
        params.rowId || null
      }&tabId=${tabId}`
    }
    if (params?.micro?.degrade || window.tech.wujieDegrade?.[addView?.props?.model]) {
      // wujie因特殊页面不兼容问题，设置降级
      wujiePage.degrade = true
    }
    if (wujiePage) {
      if (!wujiePage.dataSource) {
        wujiePage.dataSource = {}
      }
      const menuConfig = wujiePage.microApp.rebuildMenu(appsMenus)
      let appMenuConfig = menuConfig.find((item) => item.id == app.menuId)
      let menuConfigView = JSON.parse(appMenuConfig.view)
      wujiePage.props.menuConfig = menuConfigView.wujie.menuConfig //  [product, appMenuConfig] // 菜单配置信息存到节点数据源
      wujiePage.props.menuConfig._menuId = appMenuConfig.id
      wujiePage.props.token = Tech.token.get()
      wujiePage.dataSource.menuConfig = app
      wujiePage.dataSource.idPre = idPre // idPre存到节点数据源
    }
    wujiePage.props.changeRem = false
    wujiePage.loadError = () => {
      wujiePageParent?.data?.loadingInstance.close()
    }
    wujiePage.beforeLoad = (appWindow) => {
      appWindow.techOpenView = true // openView里面的无界 添加 techOpenView 标识
      if (params?.micro?.wujieNoPadding || window.tech.wujieNoPadding?.[addView?.props?.model]) {
        // wujie因特殊页面不兼容问题，修改页面padding样式
        appWindow.wujieNoPadding = true
        const wujieObj = document.getElementById(wujiePage.id)
        wujieObj.style.width = 'calc(100% + 16px)'
        wujieObj.style.height = 'calc(100% + 8px)'
        wujieObj.style.marginTop = '-8px'
        wujieObj.style.marginLeft = '-8px'
      }
      appWindow.wujieOpenViewParentId = wujiePage.id
      if (!appWindow.tech) {
        appWindow.tech = {}
      }
      appWindow.__WUJIE.lifecycles.afterMount = () => {
        wujiePageParent?.data?.loadingInstance.close()
      }
      appWindow.tech.TABINSERT = {
        // openView里面的无界 添加自己嵌自己配置
        insert: 'self',
        notify: 'wujie',
        micro: 'wujie'
      }
      appWindow.__WUJIE_MOUNT = (e) => {
        wujiePageParent?.data?.loadingInstance.close()
        if (window.tech.wujieDegrade?.[addView?.props?.model]) {
          // wujie降级iframe样式调整
          let container = document.querySelector('#' + wujiePage.id + '> iframe')
          container.setAttribute('style', 'width: 100%; height: calc(100% - 2px)')
        }
        let shadowRoot = document.getElementsByClassName('wujie_iframe')[0]?.shadowRoot
        if (shadowRoot?.childNodes?.length > 1) {
          for (let i = 0; i < shadowRoot.childNodes.length; i++) {
            if (i < shadowRoot.childNodes.length - 1) {
              if (
                shadowRoot.childNodes[i]?.children?.[0]?.tagName === 'DIV' &&
                !shadowRoot.childNodes[i]?.children?.[2]
              ) {
                shadowRoot.childNodes[i].remove()
              }
            }
          }
        }
      }
    }
    addView = insertLoading ? wujiePageContainer : wujiePage
  }
  if (!addView.style) {
    addView.style = {}
  }
  if (!addView.dataSource) {
    addView.dataSource = {}
  }
  // 补全menuConfig数据源
  addView.dataSource.menuConfig = params
  addView.dataSource._metaParamsApp = params?.app ? params.app : element?.$ds?._metaParamsApp
  addView.dataSource.fromOpenview = true
  addView.dataSource.originIdPre = element?.$ds?.idPre
  addView.dataSource.originIdPreTab = element?.$ds?.idPreTab
  addView.style.height = '4rem'
  addView.dataSource.showTableMinHeight = params.mainTableHeight || '2rem' // 主表格高度
  addView.dataSource.showErTableMinHeight = params.erTableHeight || '' // 子表格高度
  addView.dataSource.useAdvancedTable = params.useAdvancedTable
  addView.dataSource.viewType = params.view
  // openview可配置表格高度
  if (params.tableHeight) {
    addView.dataSource.tableHeight = params.tableHeight // 主表格高度
  }
  // 补充处理
  switch (showType) {
    case 'dialog': // 弹窗展开情况
      addView.style.height = params.height || '4rem'
      containerView.dataSource.idPre = idPre
      containerView.className = idPre + 'className'
      containerView.css = `.${idPre}className.choice-dialog-wrapper.ii-base-style .choice-dialog .body{padding: 0 10px 0 10px}`
      break
    case 'drawer': // 抽屉展开情况
      addView.style.height = '8rem'
      containerView.dataSource.idPre = idPre
      break
    case 'dropdown': // 下拉展开情况
      // 追加替换自身标识
      containerView.__replaceSelf = true
      break
    default: // 普通容器展开清空
      // addView.dataSource.showTableMinHeight = params.mainTableHeight || '4rem'
      addView.style.height = '100%'
      // 来源于弹窗选择器的做特殊处理
      if (params.deriveFromCustomSelect) {
        addView.style.height = params.height || '4rem'
      }
      break
  }
  // 如果是多租户版本，获取自定义权限数据
  const userInfo = window.tech.userInfo
  let permissionObj = {
    permission: [],
    permissionApi: {}
  }
  if (userInfo?.installedTenant) {
    await element.$cmd.meta.getCustomPermissionV2(permissionObj, {
      menuId: params.menuId,
      appName: element.$ds._metaParamsApp
    })
    // console.log(permissionObj)
  }
  addView.dataSource.customPermission = permissionObj.permission
  addView.dataSource.customPermissionApi = permissionObj.permissionApi
  containerItems.push(addView)

  // 深度合并原来的前端视图
  if (!containerView) {
    containerView = {}
  }
  let distView = window.tech_app.utils.deepMerge(containerView, view.__originView, ['id', 'name'])
  // let __originView = view.__originView;
  element.data.view[eventName] = {
    ...distView
    // __originView
  }

  // console.log(' === element.data.view[eventName] === ', element.data.view[eventName]);
}
