import { WujieMenu, MenuConfig } from './micro-app-data'
const wujieMenuTransform = (menu: WujieMenu): WujieMenu => {
  const originView = menu.view!
  const ignoreMenu = ['wujie']
  const isWujieView = isJSONString(originView) && JSON.parse(originView).wujie
  const rebuildUrl =
    ignoreMenu.includes(originView) || isWujieView ? menu.url : location.origin + tech.routerBase
  const isRebuildView = !ignoreMenu.includes(originView) //标识是否菜单原来就是配置wujie

  const wujieMenuConfig = {
    wujie: {
      changeRem: false,
      menuConfig: {
        view: originView,
        name: menu.name,
        app: menu.app,
        model: menu.model,
        isRebuildView
      }
    }
  }

  return {
    ...menu,
    url: rebuildUrl,
    isRebuildView,
    view: JSON.stringify(wujieMenuConfig)
  }
}

function isJSONString(str) {
  try {
    JSON.parse(str)
    return true
  } catch (e) {
    return false
  }
}

export { wujieMenuTransform, isJSONString }
