<template>
  <!-- <div class="tech-page"> -->
  <!-- <tech-m-form
      :config="config"
      :initValues="initValues"
      :selfAdaptionW="false"
      labelWidth="100px"
      labelPosition="right"
      height="1000px"
      style="margin:15px">
    </tech-m-form> -->
  <tech-page v-if="show" :config="pageConfig" :app="coreApp"> </tech-page>
  <!-- </div> -->
</template>

<script lang="ts">
import { defineComponent } from 'vue'

// 依赖包引入
import { Core, getUrlParam, LowcodeRender } from '../../importCommon/core.js'

export default defineComponent({
  name: 'tech-empty-app',
  props: {
    appConfig: {
      type: Object,
      default: () => {}
    }
  },
  data() {
    return {
      show: false,
      coreApp: {},
      pageConfig: {},
      config: [
        {
          type: 'row',
          id: 'row_001',
          items: [
            {
              name: 'name',
              text: '模型名称',
              onChange: (state, v, { model }) => {
                // console.log(state, v, model);
              }
            },
            {
              name: 'name1',
              text: '模型名称1'
            }
            // {
            //   type: 'container',
            //   items: [{
            //     name: 'tt',
            //     text: 'tt'
            //   }, {
            //     name: 'tt1',
            //     text: 'tt1'
            //   }]
            // }
          ]
        }
      ],
      initValues: {
        name: 'ttt'
      }
    }
  },
  mounted() {},
  methods: {
    async loadCommon(useVue: any, options: any) {
      // 加载公共配置common.js 后面可以通过接口异步加载
      // @ts-ignore
      await LowcodeRender.RenderCommon(options.common || {}, useVue)
      let commonAppConfig = {}
      if (options?.common?.config?.designWidth) {
        // 在common里面抽取启动core的入参
        // @ts-ignore
        commonAppConfig.designWidth = options.common.config.designWidth
      }
      if (options?.common?.config?.useRem !== undefined) {
        // @ts-ignore
        commonAppConfig.useRem = options.common.config.useRem
      }
      if (options?.common?.config?.ratio) {
        // @ts-ignore
        commonAppConfig.ratio = options.common.config.ratio
      }
      if (options?.common?.config?.changeCalcWidth) {
        // @ts-ignore
        commonAppConfig.changeCalcWidth = options.common.config.changeCalcWidth
      }

      // 解析schemajs
      // 在url上获取当前页面id
      const curPage = getUrlParam('page')
      // console.log(' === curPage === ', curPage);

      // console.log(' *** === schemaObj === ', schemaObj);
      let coreConfig = {
        config: options.schema || {},
        curPage: curPage,
        extendView: options.extendView || {}, // 入参extendView
        ...this.appConfig, // 融入外部入参配置
        ...commonAppConfig // 融入common里面的配置
      }
      // console.log(' ===== coreConfig === ', coreConfig);
      if (window?.Tech?.coreApp) {
        window.Tech.coreApp = null
      }
      const coreApp = new Core(coreConfig)
      // @ts-ignore
      if (window.Tech) {
        // @ts-ignore
        window.Tech.coreApp = coreApp
      }
      // 引入core方法组件挂载到 $coreApp
      useVue.prototype.$coreApp = coreApp
      useVue.prototype.$utils = {
        // 定义vue对象的update方法
        update: () => {
          this.update()
        }
      }
      if (!coreApp.utils) {
        coreApp.utils = {}
      }
      coreApp.utils.update = () => {
        this.update()
      }

      // 添加钩子
      // coreApp里面添加一个hook钩子对象
      // @ts-ignore
      coreApp.hook = options.hook || {}
    },
    // 初始化
    async init(useVue: any, options: any) {
      // console.log(' === empty app == ', options);
      await this.loadCommon(useVue, options)
      this.update()
    },
    update() {
      // @ts-ignore
      this.coreApp = this.$coreApp
      // @ts-ignore
      this.pageConfig = this.$coreApp?.page?.data || {}
      this.show = false
      this.$nextTick(() => {
        this.show = true
        this.$nextTick(() => {
          // 下一个时钟周期触发重置html标签的font-size
          // @ts-ignore
          this.coreApp.calcResetFontsize()
        })
      })
    }
  },
  setup() {
    return {}
  }
})
</script>
<style scoped>
.tech-page {
  /* width: 100%;
  height: 100%; */
}
</style>
<style lang="scss">
html,
body,
#app {
  width: 100%;
  height: 100%;
}

#app {
  position: relative;
  overflow: auto;
}

#app::-webkit-scrollbar {
  width: 0 !important;
  display: none;
}
</style>
