import { generateRuleForm } from './row_permission_condition_tree'

// 租户/用户角色——数据权限
export default function (preName) {
  const rules_box_id = preName + 'rules_box'
  const row_permission_container_id = preName + 'row_permission_container'
  return [
    {
      type: 'container',
      id: row_permission_container_id,
      dataSource: {
        rules: []
      },
      created: (vm) => {
        vm.$ds.rules = []
        vm.$ds.all = false
      },
      items: [
        {
          type: 'container',
          style: {
            bind_display: "${$ds.all ? 'none' : 'block'}"
          },
          id: rules_box_id,
          items: []
        },

        {
          type: 'button',
          value: Tech.$t('common.addRuleBtn'),
          style: {
            bind_display: "${($ds.all) ? 'none' : 'block'}",
            margin: '16px'
          },
          options: {
            type: 'default',
            size: 'small',
            icon: 'el-icon-plus'
          },
          // 绑定按钮的点击事件
          bind_on_click: (params) => {
            console.log(params, params.self)
            const box = params.self.$select(rules_box_id)
            const dom = generateRuleForm(preName)
            box.app.updatePageNode(dom, box, () => {
              box.data.items.push(dom)
            })
          }
        }
      ]
    }
  ]
}
