export default {
  // 使用个人界面方案弹窗
  type: 'dialog',
  id: 'dialog_meta_use_page_scheme',
  width: '80%',
  title: Tech.$t('seniorTable.usePersonalInterfaceSolution'),
  display: false,
  hasFooter: false,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  bind_on_opreates: (params) => {
    const { self: vm, value } = params
    if (value.type === 'cancel') {
      value.close()
    } else {
      const idPre = vm.$cmd.getIdPre(vm)
      const tableVm = vm.$select(idPre + 'use_page_scheme_table')
      const selectData = tableVm.$ds.checkData
      const data = selectData.signContent
      if (data) {
        const signContent = JSON.parse(data)
        // 使用界面方案，更新search视图
        const tableMain = vm.$select(idPre + 'table_main_wrap')
        tableMain.$cmd.initTableSearch(vm, signContent.search)
        if (signContent.search) {
          sessionStorage.setItem(idPre + 'SEARCH_CONFIG', JSON.stringify(signContent.search))
        }
        // 设置常用选项
        const multilayerSelect = vm.$select(idPre + 'grid_dynamic_config')
        multilayerSelect.$ds.initValue = signContent.gridConfig
        // 设置表单布局
        const formMain = vm.$select(vm.$ds.idPre + 'form_main_detail_top_header')
        if (signContent.form) {
          if (formMain) {
            formMain.$cmd.initPage(vm, signContent.form)
          } else {
            sessionStorage.setItem(idPre + 'FORM_VIEW', JSON.stringify(signContent.form))
          }
        }
        // 拿到弹窗表格的数据 对表格列设置
        const table_main_table = vm.$select(idPre + 'table_main_table')
        if (signContent.grid && signContent.grid.length > 0) {
          signContent.grid.forEach((item) => {
            vm.$cmd.setGridColumns(table_main_table, item)
          })
        }
      }
      value.close()
    }
  },
  items: [
    // 使用方案复制弹窗
    {
      type: 'dialog',
      id: 'use_page_scheme_copy_dialog',
      display: false,
      hasFooter: true,
      width: '30%',
      confirmText: Tech.$t('seniorTable.saveDefaultSchemeBtn'),
      style: {
        marginTop: '0.6rem'
      },
      options: {},
      items: [
        {
          type: 'text',
          id: 'table_main_del_dialog_icon',
          style: {
            'font-size': '0.60rem',
            color: 'rgb(245,108,108)',
            'text-align': 'center',
            display: 'block'
          },
          className: 'iconfont icon-baojing'
        },
        {
          type: 'text',
          id: 'table_main_del_dialog_text',
          style: {
            'font-size': '0.16rem',
            'font-weight': '700',
            'text-align': 'center',
            display: 'block',
            'margin-top': '0.15rem'
          },
          value: Tech.$t('seniorTable.copySchemeHint')
        }
      ],
      customMiddleButtons: [
        {
          //自定义按钮
          text: Tech.$t('seniorTable.saveUiSchemeBtn'),
          action: 'saveDefault'
        }
      ],
      bind_on_opreates: async (params) => {
        const { self: vm, value } = params
        const idPre = vm.$cmd.getIdPre(vm)
        const pageScheme = vm.$select(idPre + 'use_page_scheme_table_box')

        if (value.type === 'cancel') {
          value.close()
        } else if (value.type === 'confirm') {
          pageScheme.$cmd.copySchemeFn(vm, 1)
          value.close()
        } else {
          pageScheme.$cmd.copySchemeFn(vm, 2)
          value.close()
        }
      }
    },
    {
      type: 'container',
      id: 'use_page_scheme_table_box',
      className: 'use_page_scheme_table_box',
      dataSource: {
        fieldList: [],
        manageFieldList: [],
        checkData: null,
        selectedSchemeId: ''
      },
      created: async (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        const pageVm = vm.$select(idPre + 'container_main_content')
        const tableVm = vm.$select(idPre + 'use_page_personal_scheme_table')
        let index = tableVm.data.items.findIndex((item) => item.name == 'isOpen')
        // 不是管理员删掉 表格是否默认列
        if (index > -1 && !pageVm.$ds.isAdmin) tableVm.data.items.splice(index, 1)
      },
      commands: {
        searchUserSchemeFn: async (vm) => {
          const idPre = vm.$cmd.getIdPre(vm)
          const tableWrap = vm.$select(idPre + 'table_main_wrap')
          const tableVm = vm.$select(idPre + 'use_page_personal_scheme_table')
          let commonForm = vm.$select(idPre + 'form_main_table_search_common')
          let signId = tableWrap.$ds.seniorTableSignId
          let params = {
            args: {
              signId: signId,
              signType: 'uiScheme'
            },
            model: 'rbac_user_prefer',
            tag: 'master',
            service: 'queryUserPreferenceGrouped',
            app: 'iidp-user-prefer'
          }
          let res = await commonForm.request('getScheme', params)
          if (res?.data) {
            const data = res.data
            vm.$ds.fieldList = data.personal
            tableVm.data.tableData = data.personal
            vm.$ds.manageFieldList = data.adminPublic
            // 默认选中
            // vm.data.defaultCheck = [res.data.find((item) => item.isSelected)?.id]
            tableVm.data.defaultCheck = [vm.$ds.selectedSchemeId]
          }
        },
        // 复制
        copySchemeFn: async (vm, type) => {
          const idPre = vm.$cmd.getIdPre(vm)
          const pageScheme = vm.$select(idPre + 'use_page_scheme_table_box')
          const row = pageScheme.$ds.copyData
          const tableWrap = vm.$select(idPre + 'table_main_wrap')
          const tableSearch = vm.$select(idPre + 'form_main_table_search_common')
          const signId = tableWrap.$ds.seniorTableSignId
          const param = {
            model: 'rbac_user_prefer',
            service: 'saveScheme',
            args: {
              values: {
                name: row.name,
                signId: signId,
                signType: 'uiScheme',
                signContent: row.signContent,
                description: row.desc,
                isOpen: false, // 跟建微和明哲确认，万和项目要求默认值是false
                isDefault: type === 1 ? true : false // 跟建微和明哲确认，万和项目要求默认值是false
              },
              useDisplayForModel: true
            }
          }
          const res = await tableSearch.request('saveScheme', param)
          if (res.error) {
            window.ELEMENT.Message.error(res.error.message)
          } else {
            window.ELEMENT.Message.success(Tech.$t('seniorTable.copySuccessfully'))
            pageScheme.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
          }
        },
        // 清除loadView缓存
        clearLoadViewCache: (vm) => {
          // 设置默认方案后，需要清除loadView接口的缓存，关闭菜单后重新打开需要重新从loadView里面拿默认的方案
          const menuConfig = vm.$ds.menuConfig
          let appName = menuConfig.app
          // 如果是openView渲染的页面的情况menuConfig取不到app
          if (!menuConfig.app) {
            appName = vm.$ds._metaParamsApp
          }
          const loadViewKey = `${appName}_${menuConfig.model}_${menuConfig?.view}`
          if (menuConfig?.model && window.tech?.loadViewCache?.[loadViewKey]) {
            delete window.tech.loadViewCache[loadViewKey]
          }
          // 如果是树表结构需要删2个缓存
          let viewType = vm.$ds.viewType
          const tableLoadViewKey = `${appName}_${menuConfig.model}_${viewType}`
          if (viewType && window.tech?.loadViewCache?.[tableLoadViewKey]) {
            delete window.tech.loadViewCache[tableLoadViewKey]
          }
          // 上下表子表的删除loadView缓存
          if (vm.$ds.tabConfig) {
            const modelName = vm.$ds.tabConfig.model
            const viewType = vm.$ds.tabConfig.argType
            const singleLoadViewKey = `${appName}_${modelName}_${viewType}`
            if (viewType && window.tech?.loadViewCache?.[singleLoadViewKey]) {
              delete window.tech.loadViewCache[singleLoadViewKey]
            }
          }
          // console.log(window.tech.loadViewCache)
        }
      },
      css: `
        .use_page_scheme_table_box .vxe-table--render-default.vxe-editable .vxe-body--column{
          padding: 0.05rem 0;
        }
        // .use_page_scheme_table_box .vxe-table--render-default .vxe-cell{
        //   white-space: normal !important;
        //   text-overflow: inherit !important;
        // }
      `,
      items: [
        {
          type: 'tabs',
          id: 'use_page_scheme_tabs',
          close: false,
          created: async (vm) => {
            vm.$cmd.searchUserSchemeFn(vm)
          },
          css: `
            // #pre_permission_management_functional_permission_menu_container_main_content, #pre_permission_management_service_permission_menu_container_main_content{
            //   background: #e4e7ed;
            // }
            .use_page_scheme_table_box .el-tabs__header{
              height: 40px !important;
              line-height: 40px !important;
            }
            .use_page_scheme_table_box .el-tabs__nav-scroll{
              background: #fff;
            }
            .use_page_scheme_table_box .tech-tabs .el-tabs__item.is-top{
              border:none;
              background: #fff;
              margin-right: 0;
              padding: 0 10px !important;
              height: 40px !important;
              line-height: 40px !important;
            }
            .use_page_scheme_table_box .tech-tabs .el-tabs__item{
              background: #fff !important;
            }
            .use_page_scheme_table_box .tech-tabs .el-tabs__item.is-active{
              color: var(--tabs-active-color, #ad053d) !important;
              border-bottom: 4px solid var(--tabs-active-color, #ad053d) !important;
              z-index: 10;
            }
            .use_page_scheme_table_box  .el-tabs__nav-wrap:after{
                display: block !important;
                z-index: 4;
                height: 1px;
            }
          `,
          items: [
            {
              type: 'container',
              name: Tech.$t('seniorTable.personalScheme'),
              items: [
                {
                  type: 'table',
                  isEdit: true,
                  id: 'use_page_personal_scheme_table',
                  style: {
                    minHeight: '3.5rem',
                    marginTop: '0.1rem'
                  },
                  checkbox: 'single',
                  defaultCheck: [],
                  bind_on_select: (params) => {
                    localStorage.removeItem('VXE_CUSTOM_STORE')
                    let { self: vm, value } = params
                    if (!value.data?.id) return
                    vm.$ds.checkedDataList = [value.data]
                    vm.$ds.selectedSchemeId = value.data.id
                    vm.$ds.checkData = value.data
                    const idPre = vm.$cmd.getIdPre(vm)
                    const tableVm = vm.$select(idPre + 'use_page_scheme_table')
                    const selectData = tableVm.$ds.checkData
                    const data = selectData.signContent
                    if (data) {
                      const signContent = JSON.parse(data)
                      // 使用界面方案，更新search视图
                      const tableMain = vm.$select(idPre + 'table_main_wrap')
                      const { fields, views } = tableMain.$ds.tableView.data
                      if (signContent?.search?.body?.row) {
                        let searchView = { ...views?.search }
                        searchView.body.row = signContent.search.body.row
                      }
                      tableMain.$cmd.initTableSearch(vm, signContent.search)
                      if (signContent.search) {
                        sessionStorage.setItem(
                          idPre + 'SEARCH_CONFIG',
                          JSON.stringify(signContent.search)
                        )
                      }
                      // 设置常用选项
                      const multilayerSelect = vm.$select(idPre + 'grid_dynamic_config')
                      sessionStorage.setItem(
                        idPre + 'grid_dynamic_config',
                        JSON.stringify(signContent.gridConfig)
                      )
                      multilayerSelect.$ds.initValue = signContent.gridConfig
                      // 设置表单布局
                      // const formMain = vm.$select(vm.$ds.idPre + 'form_main_detail_top_header')
                      if (signContent.form) {
                        // if (formMain) {
                        //   formMain.$cmd.initPage(vm, signContent.form)
                        // } else {
                        //   sessionStorage.setItem(idPre + 'FORM_VIEW', JSON.stringify(signContent.form))
                        // }
                        sessionStorage.setItem(
                          idPre + 'FORM_VIEW',
                          JSON.stringify(signContent.form)
                        )
                      }
                      // 拿到弹窗表格的数据 对表格列设置
                      const table_main_table = vm.$select(idPre + 'table_main_table')
                      if (signContent?.operationWidth) {
                        signContent.grid.push({
                          type: 'operation',
                          width: signContent.operationWidth
                        })
                      }
                      if (signContent.grid && signContent.grid.length > 0) {
                        signContent.grid.forEach((item) => {
                          vm.$cmd.setGridColumns(table_main_table, item, signContent.grid)
                        })
                      }
                      // 设置排序
                      let items = table_main_table.data.items.sort((a, b) => a.sort - b.sort)
                      // 更新表格节点
                      let newItems = window.Tech._cloneDeep(items)
                      table_main_table.data.display = false
                      setTimeout(() => {
                        table_main_table.data.items = []
                        newItems.forEach((item) => {
                          table_main_table.app.updatePageNode(item, table_main_table, () => {
                            table_main_table.data.items.push(item)
                          })
                        })
                        table_main_table.data.display = true
                      }, 200)
                      const dialogSearchDropdown = vm.$select(idPre + 'dialog_meta_use_page_scheme')
                      dialogSearchDropdown.data.display = false
                    }
                  },
                  beforeEditMethod: ({ row, column, rowIndex, columnIndex }) => {
                    //根据数据是否可以编辑
                    if (row.isEdit) {
                      return true
                    }
                    return false
                  },
                  bind_tableData: '$ds.fieldList',
                  items: [
                    {
                      type: 'text',
                      field: 'name',
                      title: Tech.$t('seniorTable.schemeName'),
                      editRender: {
                        configs: {
                          editType: 'input'
                        }
                      }
                    },
                    {
                      type: 'text',
                      field: 'description',
                      title: Tech.$t('treeView.des'),
                      editRender: {
                        configs: {
                          editType: 'input'
                        }
                      }
                    },
                    {
                      type: 'switch',
                      field: 'isDefault',
                      name: 'isDefault',
                      model: {},
                      formatItem: (row, item) => {
                        item.model = row
                        return item
                      },
                      title: Tech.$t('seniorTable.defaultOrNot'),
                      bind_on_changeHandler: async (params) => {
                        const { self: vm, value } = params
                        const idPre = vm.$cmd.getIdPre(vm)
                        let commonForm = vm.$select(idPre + 'form_main_table_search_common')
                        let row = value.row
                        const index = row.rowIndex
                        const tableVm = vm.$select(idPre + 'use_page_personal_scheme_table')
                        const rowData = tableVm.data.tableData.find(
                          (item) => item.rowIndex === index
                        )
                        vm.$cmd.clearLoadViewCache(vm)
                        // 去除带下划线前缀的属性
                        Object.keys(rowData).forEach((key) => {
                          if (key.startsWith('_')) {
                            delete rowData[key]
                          }
                        })
                        let param = {
                          args: {
                            values: rowData
                          },
                          model: 'rbac_user_prefer',
                          tag: 'master',
                          service: 'updateOfScheme',
                          app: 'iidp-user-prefer'
                        }
                        const res = await commonForm.request('getScheme', param) // 修改当前行数据
                        if (res.error) {
                          window.ELEMENT.Message.error(res.error.message)
                        } else {
                          window.ELEMENT.Message.success(Tech.$t('seniorTable.successfulSetting'))
                          vm.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
                        }
                      }
                    },
                    {
                      type: 'switch',
                      field: 'isOpen',
                      name: 'isOpen',
                      model: {},
                      formatItem: (row, item) => {
                        item.model = row
                        return item
                      },
                      title: Tech.$t('seniorTable.whetherToMakePublic'),
                      bind_on_changeHandler: async (params) => {
                        const { self: vm, value } = params
                        const idPre = vm.$cmd.getIdPre(vm)
                        let commonForm = vm.$select(idPre + 'form_main_table_search_common')
                        let row = value.row
                        const index = row.rowIndex
                        const tableVm = vm.$select(idPre + 'use_page_personal_scheme_table')
                        // 通过当前行的下标找到tableData内相对应的数据给接口
                        const rowData = tableVm.data.tableData.find(
                          (item) => item.rowIndex === index
                        )
                        // 去除带下划线前缀的属性
                        Object.keys(rowData).forEach((key) => {
                          if (key.startsWith('_')) {
                            delete rowData[key]
                          }
                        })
                        let param = {
                          args: {
                            values: rowData
                          },
                          model: 'rbac_user_prefer',
                          tag: 'master',
                          service: 'updateOfScheme',
                          app: 'iidp-user-prefer'
                        }
                        const res = await commonForm.request('getScheme', param) // 修改当前行数据
                        if (res.error) {
                          window.ELEMENT.Message.error(res.error.message)
                        } else {
                          window.ELEMENT.Message.success(Tech.$t('seniorTable.successfulSetting'))
                          vm.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
                        }
                      }
                    },
                    {
                      type: 'operation',
                      field: 'operate',
                      title: Tech.$t('gridView.operation'),
                      fixed: 'right',
                      items: [
                        {
                          text: Tech.$t('detailView.save'),
                          action: 'update',
                          options: {
                            type: 'text'
                          },
                          enableCondition: (row) => {
                            // 按钮是否禁用
                            return row[0].isEdit
                          }
                        },
                        {
                          text: Tech.$t('toolbar.delete'),
                          action: 'delete',
                          options: {
                            type: 'text'
                          }
                        }
                      ]
                    }
                  ],
                  bind_on_clickOptionBtn: async (params) => {
                    const { self: vm, value } = params
                    let commonForm = vm.$select(vm.$ds.idPre + 'form_main_table_search_common')
                    let btnType = value?.btn?.action //获取操作按钮类型
                    // 针对点击编辑/详情按钮
                    if (btnType == 'delete') {
                      let param = {
                        args: {
                          ids: [value.scope.row.id]
                        },
                        model: 'rbac_user_prefer',
                        tag: 'master',
                        service: 'delete',
                        app: 'iidp-user-prefer'
                      }
                      const res = await commonForm.request('getScheme', param) // 删除当前行数据
                      if (res.error) {
                        window.ELEMENT.Message.error(res.error.message)
                      } else {
                        window.ELEMENT.Message.success(Tech.$t('actionScope.deleteSuccess'))
                        vm.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
                        // 如果是默认方案，删除loadView缓存
                        if (value?.scope?.row?.isDefault) {
                          vm.$cmd.clearLoadViewCache(vm)
                        }
                      }
                    }
                    if (btnType == 'update') {
                      let param = {
                        args: {
                          values: value.scope.row
                        },
                        model: 'rbac_user_prefer',
                        tag: 'master',
                        service: 'updateOfScheme',
                        app: 'iidp-user-prefer'
                      }
                      const res = await commonForm.request('getScheme', param) // 修改当前行数据
                      if (res.error) {
                        window.ELEMENT.Message.error(res.error.message)
                      } else {
                        window.ELEMENT.Message.success(Tech.$t('seniorTable.modifiedSuccessfully'))
                        vm.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
                      }
                    }
                  }
                }
              ]
            },
            {
              type: 'container',
              name: Tech.$t('seniorTable.managerScheme'),
              created: async (vm) => {
                const idPre = vm.$cmd.getIdPre(vm)
                const pageVm = vm.$select(idPre + 'container_main_content')
                if (pageVm.$ds.isAdmin) {
                  vm.data.display = false
                }
                vm.$cmd.searchUserSchemeFn(vm)
              },
              items: [
                {
                  type: 'table',
                  isEdit: true,
                  id: 'use_page_scheme_table',
                  style: {
                    minHeight: '3.5rem',
                    marginTop: '0.1rem'
                  },
                  bind_tableData: '$ds.manageFieldList',
                  items: [
                    {
                      type: 'text',
                      field: 'name',
                      title: Tech.$t('seniorTable.schemeName')
                    },
                    {
                      type: 'text',
                      field: 'description',
                      title: Tech.$t('treeView.des')
                    },
                    {
                      type: 'switch',
                      field: 'isDefault',
                      name: 'isDefault',
                      disabled: true,
                      model: {},
                      formatItem: (row, item) => {
                        item.model = row
                        return item
                      },
                      title: Tech.$t('seniorTable.defaultOrNot')
                    },
                    {
                      type: 'operation',
                      field: 'operate',
                      title: Tech.$t('gridView.operation'),
                      fixed: 'right',
                      items: [
                        {
                          text: Tech.$t('seniorTable.copy'),
                          action: 'copy',
                          options: {
                            type: 'text'
                          }
                        }
                      ]
                    }
                  ],
                  bind_on_clickOptionBtn: async (params) => {
                    const { self: vm, value } = params
                    let btnType = value?.btn?.action //获取操作按钮类型
                    const idPre = vm.$cmd.getIdPre(vm)
                    const row = value.scope.row
                    const pageScheme = vm.$select(idPre + 'use_page_scheme_table_box')
                    pageScheme.$ds.copyData = row
                    if (btnType == 'copy') {
                      const copyDialog = vm.$select(idPre + 'use_page_scheme_copy_dialog')
                      copyDialog.data.display = true
                    }
                  }
                }
              ]
            }
          ]
        }
      ]
    }
  ]
}
