import _get from 'lodash/get'

// 检查是否有权限
const checkPermission = (vm) => {
  const permissionArr = vm.$ds.permission // TODO vm?.data?.permission // 取permission
  // console.log(' === permissionArr === ', permissionArr)
  let hasPermission = true // 是否有权限
  if (permissionArr) {
    let val = vm.data.t_p
    if (Object.prototype.toString.call(val) === '[object String]') {
      val = [val]
    }
    if (Object.prototype.toString.call(val) === '[object Array]') {
      if (!val.every((v) => permissionArr.includes(v))) {
        hasPermission = false
      }
    }
    if (permissionArr.indexOf('all') > -1) {
      hasPermission = true
    }
  }
  // if (vm?.data?.id === 'row_meta_login_register') { // 注册按钮调试例子代码
  //   console.log(' 注册按钮 === permissionArr == ', permissionArr)
  //   console.log(' 注册按钮 === vm == ', vm)
  //   console.log(' 注册按钮 === hasPermission == ', hasPermission)
  // }
  return hasPermission
}

// 处理没有权限相关 逻辑 响应relaKeys变化 例如 控制 display false
const dealNoPermissionFn = (vm, relaKeys) => {
  for (let k in relaKeys) {
    vm.data[relaKeys[k]] = false
  }
}

// 监听权限相关属性变化
const permissionWatch = (vm, watchKey, cb) => {
  if (vm?.data && window?.Tech?.watchFn && _get(vm.data, watchKey) !== undefined) {
    const watchName = '__permission_' + watchKey + '_watch'
    if (vm?.data?.[watchName]) {
      vm.data[watchName]()
      vm.data[watchName] = null
    }
    let bindData = window.Tech.reactiveFn(vm.data)
    vm.data[watchName] = window.Tech.watchFn(
      () => _get(bindData, watchKey),
      (val) => {
        // console.log(' === watchKey, val === ', watchKey, val)
        cb(val)
      },
      { deep: true, immediate: true }
    )
  }
}
// 监听自定义权限相关属性变化
const customPermissionWatch = (vm, watchKey, cb) => {
  if (vm?.data && window?.Tech?.watchFn && _get(vm.data, watchKey) !== undefined) {
    const watchName = '__custom_permission_' + watchKey + '_watch'
    if (vm?.data?.[watchName]) {
      vm.data[watchName]()
      vm.data[watchName] = null
    }
    let bindData = window.Tech.reactiveFn(vm.data)
    vm.data[watchName] = window.Tech.watchFn(
      () => _get(bindData, watchKey),
      (val) => {
        // console.log(' === watchKey, val === ', watchKey, val)
        cb(val)
      },
      { deep: true, immediate: true }
    )
  }
}

// 向上找数据源 字段名
const getRealDataSourceNode = (node, dataName) => {
  if (node.data?.dataSource?.hasOwnProperty(dataName)) {
    return node
  } else if (node.parent) {
    return getRealDataSourceNode(node.parent, dataName)
  } else {
    return null
  }
}

// 基础权限解析函数
export const basePermission = (vm, config) => {
  // console.log(' === basePermission == ', vm, config)
  let relaKeys = ['display'] // , 'disabled'
  let hasPremission = checkPermission(vm)
  if (!hasPremission) {
    dealNoPermissionFn(vm, relaKeys)
  }
  // 开watch监听 display
  relaKeys.map((item) => {
    permissionWatch(vm, item, (val) => {
      let hasPermission = checkPermission(vm)
      if (!hasPermission) {
        dealNoPermissionFn(vm, relaKeys)
      }
    })
  })
  // 开启自身t_p属性变化监听 例如 bind_t_p
  permissionWatch(vm, 't_p', (val) => {
    let hasPermission = checkPermission(vm)
    if (!hasPermission) {
      dealNoPermissionFn(vm, relaKeys)
    }
  })
  // 开启自身dataSource.permission属性变化监听
  let targetVm = getRealDataSourceNode(vm, 'permission')
  permissionWatch(targetVm, 'dataSource.permission', (val) => {
    // console.log(' ===== watch dataSource.permission == ', val)
    let hasPermission = checkPermission(vm)
    if (!hasPermission) {
      dealNoPermissionFn(vm, relaKeys)
    }
  })
}
// 自定义权限匹配验证函数
const checkCustomPermission = (vm) => {
  const permissionArr = vm.$ds.customPermission // TODO vm?.data?.permission // 取permission
  // console.log(' === permissionArr === ', permissionArr)
  let hasPermission = true // 是否有权限
  if (permissionArr) {
    let val = vm.data.c_p
    if (Object.prototype.toString.call(val) === '[object String]') {
      val = [val]
    }
    if (Object.prototype.toString.call(val) === '[object Array]') {
      if (
        !val.every((v) => {
          if (permissionArr.includes(v)) {
            return true
          }
          // 从auth.json取到的自定义权限用ViewExt.截取判断
          return permissionArr.some((item) => {
            let viewExt = ''
            let custom = ''
            try {
              viewExt = item.split('ViewExt.')[1]
            } catch (error) {
              console.log(' === ViewExt === ', error)
            }
            try {
              custom = v.split('custom_function.')[1]
            } catch (error) {
              console.log(' === custom_function === ', error)
            }
            return viewExt && custom && custom === viewExt
          })
        })
      ) {
        hasPermission = false
      }
    }
  }
  return hasPermission
}
// 自定义权限解析函数
export const customPermission = (vm, config) => {
  // console.log(' === basePermission == ', vm, config)
  let relaKeys = ['display'] // , 'disabled'
  let hasPremission = checkCustomPermission(vm)
  if (!hasPremission) {
    dealNoPermissionFn(vm, relaKeys)
  }
  // 开watch监听 display
  relaKeys.map((item) => {
    customPermissionWatch(vm, item, (val) => {
      let hasPermission = checkCustomPermission(vm)
      if (!hasPermission) {
        dealNoPermissionFn(vm, relaKeys)
      }
    })
  })
  // 开启自身t_p属性变化监听 例如 bind_c_p
  customPermissionWatch(vm, 'c_p', (val) => {
    let hasPermission = checkCustomPermission(vm)
    if (!hasPermission) {
      dealNoPermissionFn(vm, relaKeys)
    }
  })
  // 开启自身dataSource.customPermission属性变化监听
  let targetVm = getRealDataSourceNode(vm, 'customPermission')
  customPermissionWatch(targetVm, 'dataSource.customPermission', (val) => {
    // console.log(' ===== watch dataSource.permission == ', targetVm)
    let hasPermission = checkCustomPermission(vm)
    if (!hasPermission) {
      dealNoPermissionFn(vm, relaKeys)
    }
  })
}
