export default {
  namespaced: true,

  state: {
    userInfo: null,
    appMenus: [],
    curMenu: null
  },

  getters: {
    userInfo(state) {
      return state.userInfo
    },
    appMenus(state) {
      return state.appMenus
    },
    curMenu(state) {
      return state.curMenu
    }
  },

  mutations: {
    // 设置全局用户信息
    setUserInfo(state, data) {
      state.userInfo = data
    },
    // 设置全局菜单信息
    setAppMenus(state, data) {
      state.appMenus = data
    },
    setCurMenu(state, data) {
      state.curMenu = data
    },
    // 重置
    reset(state) {
      state.userInfo = null
      state.appMenus = []
    }
  }
}
