export const handlerBizTree = (nodeId, options = {}) => {
  let curNodeId = nodeId
  let handlers = {
    dataHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let tableMainVm = curNode.$select(pre + 'table_main')
          let treeMainVm = curNode.$select(pre + 'tree_main_wrap')
          if (property === 'showRightType') {
            const { isEmpty, showTable, showForm } = treeMainVm?.$ds
            if (isEmpty) {
              return 'empty'
            } else if (showTable) {
              return 'table'
            } else if (showForm) {
              return 'form'
            }
          } else if (property === 'currentId') {
            return treeMainVm?.$ds?.currentId
          } else if (property === 'currentData') {
            return treeMainVm?.$ds?.currentData
          } else if (property === 'checkedData') {
            let treeVm = curNode.$select(pre + 'tree_main_wrap_left')
            return treeVm?.instance?.$refs?.tree?.getCheckedNodes()
          } else if (property === 'treeViewRes') {
            return treeMainVm?.$ds?.treeViewRes
          } else if (property === 'treeData') {
            return treeMainVm?.$ds?.treeDataList
          } else if (property === 'clickType') {
            return treeMainVm?.$ds?.clickType
          } else if (property === 'model') {
            return tableMainVm?.$ds?._metaParamsModel
          } else if (property === 'app') {
            return tableMainVm?.$ds?._metaParamsApp
          }
        }
      }
    },
    reqHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let treeMainVm = curNode.$select(pre + 'tree_main_wrap')
          let dsConfigArr = ['treeViewRes', 'treeData', 'getFormData', 'formUpdate']
          if (dsConfigArr.includes(property)) {
            val = treeMainVm?.data?.ds_config?.list?.find((i) => i.name === property)
          }
        }
        return val
      }
    },
    baseMethodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode && typeof property === 'string') {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let treeMainVm = curNode.$select(pre + 'tree_main_wrap')
          let __srcHookFn = { ...treeMainVm?.data?.__srcHookFn }
          if (['created', 'mounted', 'destroy'].includes(property)) {
            val = __srcHookFn?.[property]
          } else {
            val = __srcHookFn?.['commands.' + property]
          }
        }
        return val
      }
    },
    methodsHandler: {
      get: (target, property, receiver) => {
        let val = null
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          let treeMainVm = curNode.$select(pre + 'tree_main_wrap')
          val = treeMainVm?.data?.[property]
        }
        return val
      }
    },
    nodesHandler: {
      get: (target, property, receiver) => {
        let curNode = tech_app.page.getNode(curNodeId)
        if (curNode) {
          let pre = curNode.$ds.idPreTab || curNode.$ds.idPre
          if (property === 'self') {
            return curNode.$select(pre + 'tree_main_wrap')
          } else if (property === 'treeNode') {
            return curNode.$select(pre + 'tree_main_wrap_left')
          } else if (property === 'rightFormNode') {
            return curNode.$select(pre + 'tree_main_wrap_right_straight')
          } else if (property === 'rightTableNode') {
            return curNode.$select(pre + 'tree_main_wrap_right_table')
          } else if (property === 'rightFormSaveNode') {
            return curNode.$select(pre + 'tree_main_wrap_right_save')
          }
        }
      }
    }
  }
  return handlers
}
