const getOnlyLookRequired = () => {
  return {
    type: 'checkbox',
    name: 'checkbox',
    text: Tech.$t('gridView.onlyLookRequired'),
    id: 'only_look_required',
    bind_display: "${$ds.clickType !== 'preview'}",
    style: {
      fontWeight: 700,
      'margin-left': '.2rem',
      color: '#666'
    },
    bind_on_change: (() => {
      // 记录原本就需要隐藏的字段信息
      let originHideItems = []
      return (params) => {
        const {
          value: { isCheck }
        } = params
        if (isCheck === null) {
          originHideItems = []
          return
        }
        const idPre = params?.self?.$cmd?.getIdPre?.(params.self) || params.self.$ds.idPre
        const getAllItems = (items = []) => {
          return items.reduce((total, cur) => {
            if ('items' in cur) {
              return total.concat(getAllItems(cur.items))
            } else {
              total.push(cur)
            }
            return total
          }, [])
        }
        const id = idPre + 'form_main_detail_top_common'
        const drawerId = idPre + 'table_drawer_form'
        const formNode = params.self.$select(id) || params.self.$select(drawerId)
        const formItems = formNode?.data?.items || []
        // 获取表单里面所有字段
        const items = getAllItems(formItems)
        if (isCheck) {
          originHideItems = []
          // 记录原本就是隐藏的字段信息
          items.forEach((item) => {
            if (!item.display || item.type === 'hidden' || item.hidden) {
              originHideItems.push(item)
            }
          })
        }
        items.forEach((item) => {
          const isRequired = item.required || !!(item.rules || []).find((rule) => !!rule.required)
          if (!originHideItems.includes(item) && !isRequired) {
            item.display = !isCheck
          }
        })
      }
    })()
  }
}

export default getOnlyLookRequired
