export default {
  // 设置操作列宽弹窗
  type: 'dialog',
  id: 'dialog_meta_table_operation_width',
  width: '20%',
  title: Tech.$t('seniorTable.setingOperationColumnWidth'),
  display: false,
  hasFooter: true,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  bind_on_opreates: (params) => {
    const { self: vm, value } = params
    if (value.type === 'cancel') {
      value.close()
    } else {
      const idPre = vm.$cmd.getIdPre(vm)
      const table_main_table = vm.$select(idPre + 'table_main_table')
      const operationForm = vm.$select(idPre + 'form_meta_set_operation_width')

      // item?.type == 'operation'
      let item = { type: 'operation', width: operationForm.$ds.form.width }
      // 拿到弹窗表格的数据 对表格列设置
      let tableData = []
      if (table_main_table.$ds.seniorTable?.grid?.length) {
        const cloneableData = window.Tech._cloneDeep(table_main_table.$ds.seniorTable.grid)
        tableData = [...cloneableData, { width: operationForm.$ds.form.width }]
      } else {
        tableData.push({ width: operationForm.$ds.form.width })
      }
      vm.$cmd.setGridColumns(table_main_table, item, tableData)

      let newItems = window.Tech._cloneDeep(table_main_table.data.items)
      table_main_table.data.items = []
      newItems.forEach((item) => {
        table_main_table.app.updatePageNode(item, table_main_table, () => {
          table_main_table.data.items.push(item)
        })
      })
      value.close()
    }
  },
  items: [
    {
      type: 'form',
      id: 'form_meta_set_operation_width',
      formConfig: {
        inline: false,
        labelPosition: 'left',
        labelWidth: '72px'
      },
      dataSource: {
        form: { width: undefined }
      },
      items: [
        {
          type: 'input',
          text: Tech.$t('seniorTable.operationColumnWidth'),
          name: 'width',
          bind_on_handleInputBlur: (data) => {
            let { self: vm, value } = data
            const formBox = vm.$select(vm.$ds.idPre + 'form_meta_set_operation_width')
            const width = formBox.$ds.form.width
            if (/\d/.test(width)) {
              if (width?.endsWith('%')) {
                formBox.$ds.form.width = parseInt(width).toString() + '%'
              } else {
                let newWidth = parseInt(width).toString()
                formBox.$ds.form.width = newWidth == 'NaN' ? null : newWidth
              }
            } else {
              formBox.$ds.form.width = null
            }
          }
        }
      ]
    }
  ]
}
