export default {
  type: 'container',
  id: 'approval_process_detail',
  css: `
  .el-collapse-item__wrap{border-bottom:0}
  //#apply_approval_process_detail .el-collapse-item__content .el-col{ min-height: 50px;}
  `,
  style: {
    display: 'flex'
    // height: '100%'
  },
  dataSource: {
    leftSubmitItem: [],
    leftFormId: ''
  },
  ds_config: {
    list: [
      {
        name: 'userProfile',
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {
          params: {
            args: {},
            app: 'workflow',
            service: 'userProfile',
            model: 'wf_process_ui_view'
          }
        }
      }
    ]
  },
  commands: {
    initPage: async (vm, formMain, data) => {
      const table_main = vm.$select(vm.$ds.idPre + 'table_main')
      const table_detail = vm.$select(vm.$ds.idPre + 'table_detail')
      const approvalTemplate = vm.$select(vm.$ds.idPre + 'approval_process_detail')
      const detail_content = vm.$select(vm.$ds.idPre + 'form_main_detail_top_items_1')
      const detail_header = vm.$select(vm.$ds.idPre + 'form_main_detail_top_header')
      let listItems = []
      approvalTemplate.$ds.leftSubmitItem = []
      if (data.items) {
        // 表单数据回显
        data.items.map((srcItem) => {
          vm.$cmd.meta.nestObj(vm, srcItem, 'items', (vm, objItem) => {
            if (objItem?.name) {
              if (objItem?.name.indexOf('.') > -1) {
                objItem.name = objItem.name.replace(/\./g, '___') // 将点替换成三个下划线 否则会引起表单组件报错
              }
              listItems.push(objItem)
            }
          })
        })
      }
      let result = {}
      // 查询审批流左侧表单(或草稿箱)数据
      // const params = {
      //   model: 'wf_process_instance',
      //   service: 'getFormData',
      //   args: {}
      // }
      // if (
      //   table_detail?.$ds?.needGetFormData !== false &&
      //   table_detail?.$ds?.approvalOptions?.needGetFormData !== false
      // ) {
      //   params.args = {
      //     ids: [table_detail?.$ds?.mainTableRowData?.id]
      //   }
      // } else {
      //   params.args = { userProfile: true }
      // }
      // if (table_detail.$ds?.args?.ids) {
      //   //后端视图配置了ids覆盖
      //   const args = window.Tech._cloneDeep(table_detail.$ds.args)
      //   params.args.ids = args.ids
      // }
      // let formData = [{}]
      // if (table_detail.$ds.processDatas?.app && table_detail.$ds.processDatas?.app !== 'null') {
      //   // 兼容后端返回'null'
      //   params.app = table_detail.$ds.processDatas.app // app取loadView返回的app
      //   let formDataRes = []
      //   // let formDataRes = await vm.request('otherService', params)
      //   result.data.formData
      //   formData = formDataRes?.data
      //   // 根据配置字段hiddenStartUser，隐藏操作人信息一栏
      //   if (formData?.hiddenStartUser) {
      //     setTimeout(() => {
      //       let formWrap = vm.$select(vm.$ds.idPre + 'form_main_detail_top_common_items_0')
      //       const formItems = formWrap?.data?.items ?? []
      //       const filteredItems = formItems.filter(
      //         (subItem) => subItem.id !== vm.$ds.idPre + 'startUserGroup'
      //       )
      //       formWrap.data.items = filteredItems
      //     }, 200)
      //   }
      //   let usefulApp = params.app || 'base'
      //   let injectAppNode = vm.$select(vm.$ds.idPre + 'table_detail')
      //   Object.defineProperty(injectAppNode.data.dataSource, '_metaParamsApp', {
      //     value: usefulApp,
      //     writable: true,
      //     configurable: true,
      //     enumerable: true
      //   })
      // } else {
      //   let formDataRes = await vm.request('otherService', params)
      //   formData = formDataRes?.data
      // }
      // 模拟await，确保视图在下一个事件循环周期才渲染
      await new Promise((resolve) => setTimeout(resolve, 0))
      // 新版整合getformdata至loadview中
      let formData = table_detail.$ds.processDatas.formData ?? {}
      //   // 根据配置字段hiddenStartUser，隐藏操作人信息一栏
      if (formData?.hiddenStartUser) {
        setTimeout(() => {
          let formWrap = vm.$select(vm.$ds.idPre + 'form_main_detail_top_common_items_0')
          const formItems = formWrap?.data?.items ?? []
          const filteredItems = formItems.filter(
            (subItem) => subItem.id !== vm.$ds.idPre + 'startUserGroup'
          )
          formWrap.data.items = filteredItems
        }, 200)
      }
      // 新版表单多模型接口数据处理
      for (const key in formData) {
        if (Object.hasOwnProperty.call(formData, key)) {
          if (key === 'model') {
            result[key] = formData[key]
            const model = formData[formData[key]]
            for (const key1 in model) {
              if (Object.hasOwnProperty.call(model, key1)) {
                result[key1] = model[key1]
              }
            }
          } else if (key === 'id') {
            result[key] = formData[key]
          } else if (key !== formData['model']) {
            const model = formData[key]
            for (const key1 in model) {
              if (Object.hasOwnProperty.call(model, key1)) {
                result[key + '___' + key1] = model[key1]
              }
            }
          }
        }
      }
      if (result.id) {
        table_detail.$ds.mainTableRowData.leftFormId = result.id
        approvalTemplate.$ds.leftFormId = result.id
      }

      for (let i in listItems) {
        const hasKey = result.hasOwnProperty(listItems[i].name)
        if (hasKey) {
          listItems[i].defaultValue = result[listItems[i].name]
          //不清楚为什么要将null转化为空字符串，影响了上传，先暂时将上传类型避开
          if (
            (listItems[i].defaultValue === undefined || listItems[i].defaultValue === null) &&
            !['file', 'dict', 'selection', 'enum', 'enummodel', 'condition', 'manytomany'].includes(
              listItems[i].dataType.toLowerCase()
            )
          ) {
            listItems[i].defaultValue = ''
          }
          // 不可编辑时上传按钮不可用
          if (listItems[i].type === 'upload' && vm.$ds.clickType === 'preview') {
            listItems[i].disabled = true
          }
        }
        // 禁用或者只读的时候 点保存时不提交到表单数据
        if (window.$tech?.workflowReadonlySubmit) {
          if (!listItems[i].disabled && !listItems[i].readonly) {
            if (listItems[i]?.groupConf?.id !== 'startUserGroup') {
              approvalTemplate.$ds.leftSubmitItem.push(listItems[i].name)
            }
          }
        } else {
          // 2024-09-26 禁用的也需要进行提交到表单 - 需求提的（吴建微）
          if (listItems[i]?.groupConf?.id !== 'startUserGroup') {
            approvalTemplate.$ds.leftSubmitItem.push(listItems[i].name)
          }
        }
      }

      formMain.items = data.items
      formMain.id = vm.$ds.idPre + 'form_main_detail_top_common'

      let formMainList = [formMain]

      // 通过 formList 长度 - 判断是否开启了多节点 - push 新视图
      let multipleNode = table_detail?.$ds?.processDatas?.formList?.length > 0 ?? false
      if (multipleNode) {
        // 拼接多节点视图数据
        let formList = table_detail?.$ds?.processDatas?.formList ?? []
        let formDataList = table_detail?.$ds?.processDatas?.formData?.formDataList ?? []

        const table_main = vm.$select(vm.$ds.idPre + 'table_main')
        formList.map((item, index) => {
          // 生成表单
          let singleData = table_main.$cmd.meta.formFormat.initForm(
            table_main,
            item?.views?.form,
            item?.fields
          )
          let singleDataForm = formDataList.find((formItem) => formItem.model === item.model)?.[
            item.model
          ]
          if (singleData?.items) {
            // 去除 展示节点 发起人信息
            const formItems = singleData?.items?.[0]?.items ?? []
            const filteredItems = formItems.filter(
              (subItem) => subItem.id !== vm.$ds.idPre + 'startUserGroup'
            )
            singleData.items = filteredItems
            // 表单数据回显
            singleData.items.map((srcItem) => {
              vm.$cmd.meta.nestObj(vm, srcItem, 'items', (vm, objItem) => {
                if (objItem?.name) {
                  if (objItem?.name.indexOf('.') > -1) {
                    objItem.name = objItem.name.replace(/\./g, '___') // 将点替换成三个下划线 否则会引起表单组件报错
                  }
                  objItem.defaultValue = singleDataForm?.[objItem?.name]
                  objItem.disabled = true
                }
              })
            })
          }
          let idPre = item?.views?.form?.view_id ?? ''
          // getView替换表单
          let sigleFormMain = vm.$cmd.meta.getView(
            vm,
            'approvalMultipleNodesForm',
            index + '_' + idPre
          )
          sigleFormMain.displayName = item?.displayName ?? '多节点展示信息' + index
          sigleFormMain.items = singleData.items
          formMainList.push(sigleFormMain)
        })
      }
      // multipleNodeNoCollapse 配置是否需要组件
      // 配置了多节点则显示多节点
      let viewItems =
        multipleNode && !window.tech?.multipleNodeNoCollapse
          ? approvalTemplate.data.items[0].items[0]
          : approvalTemplate.data.items[0]
      viewItems.items = []
      // 获取当前审批人
      const approvalNodes = table_detail?.$ds?.processDatas?.approvalNodes ?? []
      const currentNode = approvalNodes.find((el) => el?.isCurrentNode)
      formMainList.map((item, index) => {
        vm.app.updatePageNode(item, approvalTemplate, () => {
          // 设置当前审批人
          if (!item?.displayName && currentNode && index == 0) {
            item.displayName = currentNode.displayName
          }
          // 把表单视图塞进模板
          viewItems.items.push(item)
        })
      })
      // 重新计算 tab是否隐藏
      setTimeout(() => {
        let comForm = vm.$select(vm.$ds.idPre + 'form_main_detail_top_common')
        vm.$cmd.tabHideRelForm(comForm, comForm.$ds.form)
      }, 100)

      if (table_detail?.$ds?.approvalPageTitle)
        detail_header.$ds.pageTitle = table_detail.$ds.approvalPageTitle

      // 判断是否有暂存按钮
      if (table_detail?.$ds?.processDatas?.form?.temporarySave) {
        detail_header.data.style.position = 'relative'
        let wrap = vm.$select(vm.$ds.idPre + 'container_form_main_wrap')
        wrap.data.style.paddingTop = '40px'
        const buttons = table_detail?.$ds?.processDatas?.form?.views?.form.body?.buttons || []
        // 是否有撤回按钮
        const cancel = buttons.some((el) => el?.actionType == 'Cancel' || el?.code == 'cancel')
        let storageButton = {
          type: 'button',
          value: Tech.$t('workflow.temporaryStorage'),
          options: {
            type: 'plain',
            size: 'mini'
          },
          style: {
            position: 'absolute',
            right: '36.8%',
            top: cancel ? '61px' : '46px',
            background: '#fff',
            border: '0.01rem solid var(--button-primary-bg, #677177)',
            fontSize: '0.14rem',
            lineHeight: '0.13rem',
            color: 'var(--button-primary-bg, #677177)'
          },
          bind_on_click: async (params) => {
            const commonForm = params.self.$select(
              params.self.$ds.idPre + 'form_main_detail_top_common'
            )
            commonForm?.instance?.verifyFormAndScrollView?.()
            let commonRes = await commonForm.instance.submit()
            commonRes = await params.self.$cmd.mergeErFiledValue(params.self, commonRes)
            for (let key in commonRes) {
              if (key.indexOf('__') != -1) {
                delete commonRes[key]
              }
              if (Object.prototype.toString.call(commonRes[key]) === '[object Object]') {
                commonRes[key] = commonRes[key]?.value || ''
              }
            }
            const param = {
              args: {
                formData: commonRes,
                instanceId:
                  commonForm?.$ds?.processDatas?.formData?.wf_process_instance?.instanceId,
                nodeId: commonForm?.$ds?.processDatas?.formData?.id
              },
              app: 'workflow',
              model: 'wf_process_instance',
              service: 'saveDraft'
            }
            let loadingInstance = window.ELEMENT.Loading.service({
              text: Tech.$t('tenant.beSaving')
            })
            setTimeout(() => {
              loadingInstance.close()
            }, 5000)
            const formDataRes = await vm.request('otherService', param)
            loadingInstance.close()
            if (formDataRes?.data) {
              window.ELEMENT.Message.success(Tech.$t('common.saveSuccess'))
            } else {
              window.ELEMENT.Message.error({
                message: formDataRes?.error?.message,
                showMore: formDataRes?.error?.data
              })
            }
          }
        }
        vm.app.updatePageNode(storageButton, detail_header, () => {
          detail_header.data.items.push(storageButton)
        })
      }

      // 重新构建右上角按钮组
      const flowData = table_main.$ds.loadFlowView
      // 过滤掉buttons带有 @defaults
      const buttons = flowData?.views?.form?.body?.buttons || [];
      if (buttons && buttons.length && buttons.some(el => el === '@defaults')) {
        flowData.views.form.body.buttons = [];
      }
      const flowBtns = vm.$cmd.meta.formFormat.formatFlowViewBtns(vm, {
        view: flowData?.views?.form,
        permissions: flowData?.permissions
      })
      flowBtns.forEach((btn) => {
        btn.bind_on_click = async (params) => {
          let commonForm = params.self.$select(
            params.self.$ds.idPre + 'form_main_detail_top_common'
          )
          let args = {}
          if (btn.btnConfig?.actionType === 'Cancel') {
            //撤回按扭的接口参数
            args = {
              id: btn.btnConfig.userTaskId,
              action: btn.action
            }
          } else {
            let submitRes = {}
            const { fields, views } = table_main.$ds.loadFlowView
            // 校验表单并定位到 不通过的字段
            commonForm?.instance?.verifyFormAndScrollView?.()
            let commonRes = await commonForm.instance.submit()
            let table_detail = params.self.$select(params.self.$ds.idPre + 'table_detail')
            // let addMainTableRowData = table_detail.$ds.mainTableRowData || {}
            let row = commonRes
            row = await params.self.$cmd.mergeErFiledValue(params.self, row)
            for (const key in row) {
              if (Object.hasOwnProperty.call(row, key)) {
                if (key.indexOf('filter_') > -1 || key === 'rowIndex') {
                  delete row[key]
                }
                // 保存时删除保留的辅助字段
                const reserveProps = window.techUi?.VxeTable?.$TABLE_ROW_RESERVE_PROPS
                if (reserveProps && Object.values(reserveProps).includes(key)) {
                  delete row[key]
                }
              }
            }
            let distRow = params.self.$cmd.meta.formFormat.transformParams(params.self, row)
            const obj = window.Tech.formatFormSublimtField(fields, distRow)
            for (const key in obj) {
              if (Object.hasOwnProperty.call(obj, key)) {
                if (key.indexOf('__values') > -1) {
                  delete obj[key]
                }
              }
            }
            // 禁用的表单项 无需提交
            approvalTemplate.$ds.leftSubmitItem.map((sItem) => {
              const DataStr = commonRes[sItem]
              if (sItem.indexOf('___') > -1) {
                sItem = sItem.split('___')[1] //提交的时候去掉模型前缀
              }
              submitRes[sItem] = DataStr === '' ? null : DataStr
            })

            args = {
              values: obj,
              action: btn.action,
              serviceVersion: flowData?.serviceVersion,
              model: btn.btnConfig.model
            }
            if (btn.btnConfig?.userTaskId) {
              args.id = btn.btnConfig?.userTaskId
            } //后端返回任务id就要返回
          }
          params.self.data.loading = true
          let submit = await commonForm.request('bpmFormUpdate', {
            model: flowData?.model,
            service: btn.service, //服务在按钮里面直接取
            app: flowData?.app,
            args
          })
          params.self.data.loading = false
          if (submit?.data?.rootInstanceId) {
            if (params.self.$ds.isApproval) {
              const _vm = vm.$select(vm.$ds.idPre + 'approval_empty_container')
              detail_header.$cmd.preBack({ self: _vm.parent })
            } else {
              detail_header.$cmd.preBack(params)
            }
            window.ELEMENT.Message.success(Tech.$t('detailView.successHint'))
          } else {
            window.ELEMENT.Message.error({
              message: submit?.error?.message || Tech.$t('detailView.operationFailure'),
              showMore: submit.error
            })
          }
        }
      })
      const btnView = {
        type: 'container',
        items: flowBtns
      }
      vm.app.updatePageNode(btnView, detail_header, () => {
        flowBtns.length && detail_header.data.items.push(btnView)
      })

      // 需要显示审批节点、审批流程的情况
      if (table_detail.$ds.isApproval) {
        const approvalTabs = vm.$cmd.meta.getView(vm, 'approvalDetailTabs', vm.$ds.idPre)
        const approvalContainer = vm.$select(vm.$ds.idPre + 'form_main_detail_top')

        const form_tabs_items = detail_content.data.items // 原来两个子项（表单+子表）
        // 右侧审批区域展开收起
        form_tabs_items.push({
          type: 'button',
          options: {
            type: 'text',
            size: 'small',
            icon: 'el-icon-d-arrow-right'
          },
          style: {
            position: 'absolute',
            right: 0,
            top: 'calc(50% - .2rem)',
            width: '25px',
            height: '35px',
            color: 'rgb(106, 106, 106)',
            boxShadow: '0 0 8px rgba(0, 0, 0, 0.3)'
          },
          bind_on_click: (params) => {
            const { self: vm, value } = params
            const leftFormVm = vm.$select(vm.$ds.idPre + 'approval_process_detail_left')
            if (!leftFormVm.data.expand) {
              leftFormVm.data.style.width = '100%'
              leftFormVm.data.expand = true
              vm.data.options.icon = 'el-icon-d-arrow-left'
            } else {
              leftFormVm.data.style.width = '65%'
              leftFormVm.data.expand = false
              vm.data.options.icon = 'el-icon-d-arrow-right'
            }
          }
        })
        // 替换approvalContainer的items[1] 把form_tabs_items外层再嵌套层容器 通过flex布局实现左侧表单+子表 右侧流程节点
        const newNodeObj = {
          // 用这个视图替换原本的vm.$ds.idPre + 'form_main_detail_top_items_1'
          type: 'container',
          style: {
            display: 'flex',
            height: '100%',
            overflow: 'auto',
            background: '#e1e7ec'
          },
          items: [
            {
              type: 'container',
              id: vm.$ds.idPre + 'approval_process_detail_left',
              items: form_tabs_items, // 左侧表单+子表
              expand: false,
              style: {
                width: '65%',
                overflow: 'auto',
                background: '#fff',
                position: 'relative'
              }
            },
            {
              type: 'container',
              id: vm.$ds.idPre + 'approval_process_detail_tabs', // 右侧流程节点视图
              className: 'form-tabs-wrap-css',
              display: true,
              style: {
                flex: 1,
                height: '100%',
                overflowY: 'auto',
                overflow: 'overlay',
                background: '#fff',
                marginTop: 0,
                marginLeft: '0.05rem'
              },
              items: [approvalTabs]
            }
          ]
        }
        vm.instance.$nextTick(() => {
          vm.app.updatePageNode(newNodeObj, approvalContainer, () => {
            approvalContainer.data.items.splice(1, 1, newNodeObj)
          })
        })
      }
      if (window.tech?.TwTaskCheckScope) {
        // 通威项目待办进入详情检测作用域是否已变化
        let res = await window.Tech.httpMeta({
          data: {
            params: {
              args: {
                useDisplayForModel: true,
                ids: [tech.userInfo.id]
              },
              model: 'rbac_user',
              tag: 'master',
              service: 'profile',
              app: 'base'
            }
          },
          showMsg: false
        })
        if (
          res?.data?.curSgAndInstance?.[0]?.defaultInstanceId !=
          tech.userInfo?.curSgAndInstance?.[0]?.defaultInstanceId
        ) {
          // 如果作用域被改变，通知作用域切换框进行切换
          // window.Tech.tBus.$emit('cascaderDataChange', res.data.curSgAndInstance)
          let scopeBox = vm.$select('dropdown-tree-table_box')
          if (scopeBox) {
            scopeBox.data.scopeData = res.data.curSgAndInstance
          }
          // window.Tech.tBus.$emit('cascaderDataChangess',xcxx)
        }
      }
    }
  },
  items: [
    {
      type: 'container',
      id: 'container_form_main_wrap',
      className: 'approval_process_detail_form',
      // css: `.approval_process_detail_form
      // .m-form .el-input.is-disabled .el-input__inner, .m-form .el-textarea.is-disabled .el-textarea__inner {
      //   background: #F7F8FA;
      //   border-color: #CCCCCC
      // }`,
      style: {
        width: '100%',
        height: '100%',
        padding: '0.1rem',
        background: '#fff',
        overflowY: 'auto',
        overflow: 'overlay'
      },
      items: [
        {
          type: 'custom-collapse',
          id: 'workflow_custom_collapse_component',
          collapseData: [
            {
              name: 'custom_collapse_component1'
            },
            {
              name: 'custom_collapse_component2'
            }
          ],
          items: [],
          on_handleChange: (params) => {
            const { self: vm, value } = params
            let customStep = vm.$select('custom_step_component')
            customStep.data.active = value
          }
        }
      ]
    }
  ]
}
