const makeMainView = (label, view, idPre) => {
  let page = [window.Tech._cloneDeep(view)]
  window.Tech.utils.recursive(page, {
    props: { children: 'items' },
    chengItem: (item, parent) => {
      item.idPre = idPre
      if (item.id) {
        item.id = item.idPre + item.id
      }
      if (!parent) {
        item.name = label
      }
    }
  })
  return page[0]
}

// 模板应用的openView协议的实现
export function insertPage(params, idPre) {
  let returnView = null
  if (params.type === 'custom') {
    let dynamicEmptyPage = window.tech_app.data.commands.meta.views.emptyPage
    let emptyPage = window.Tech._cloneDeep(dynamicEmptyPage)
    emptyPage.idPre = idPre
    emptyPage.id = emptyPage.idPre + emptyPage.id
    emptyPage.name = params.label || ''
    emptyPage.menu = params
    emptyPage.props.model = params.model
    emptyPage.props.view = params.type

    if (emptyPage) {
      if (!emptyPage.dataSource) {
        emptyPage.dataSource = {}
      }
      emptyPage.dataSource.menuConfig = params // 菜单配置信息存到节点数据源
      emptyPage.dataSource.idPre = idPre // idPre存到节点数据源
      if (params.app) {
        emptyPage.dataSource._metaParamsApp = params.app
      }
      // emptyPage.dataSource._metaParamsApp = params.app || 'base'
      emptyPage.dataSource._metaParamsModel = params.model || ''
    }
    returnView = emptyPage
  } else if (params.type === 'iframe') {
    if (params.url) {
      let dynamicIframe = window.tech_app.data.commands.meta.views.iframe
      let cookiesToken = window.Tech.token.get()
      // let token = cookiesToken ? encodeURIComponent('Bearer ' + cookiesToken) : ''
      let token = cookiesToken
      if (cookiesToken.indexOf('Bearer') !== 0) {
        token = encodeURIComponent('Bearer ' + cookiesToken)
      }
      // 补全url
      let tempUrl = window.Tech.utils.completeLocalUrl(params.url)
      let url = new URL(tempUrl)
      let params2 = new URLSearchParams(url.search)
      params2.set('token', token)
      url.search = '?' + params2.toString()
      let iframePage = window.Tech._cloneDeep(dynamicIframe)
      iframePage.idPre = idPre
      iframePage.id = iframePage.idPre + iframePage.id
      iframePage.name = params.label
      iframePage.menu = params
      iframePage.url = url.href

      if (iframePage) {
        if (!iframePage.dataSource) {
          iframePage.dataSource = {}
        }
        iframePage.dataSource.menuConfig = params // 菜单配置信息存到节点数据源
        iframePage.dataSource.idPre = idPre // idPre存到节点数据源
      }
      returnView = iframePage
    }
  } else if (params.type === 'empty') {
    let dynamicEmptyPage = window.tech_app.data.commands.meta.views.emptyPage
    let emptyPage = window.Tech._cloneDeep(dynamicEmptyPage)
    emptyPage.idPre = idPre
    emptyPage.id = emptyPage.idPre + emptyPage.id
    emptyPage.name = params.label
    emptyPage.menu = params
    emptyPage.items = [
      {
        type: 'container',
        name: emptyPage.name,
        style: {
          width: '100%',
          height: '100%'
        },
        items: [
          {
            type: 'empty',
            value: Tech.$t('gridView.underConstruction'),
            name: 'developing',
            class: '.empty{display: flex;align-items: center; justify-content: center;}'
          }
        ]
      }
    ]

    if (emptyPage) {
      if (!emptyPage.dataSource) {
        emptyPage.dataSource = {}
      }
      emptyPage.dataSource.menuConfig = params // 菜单配置信息存到节点数据源
      emptyPage.dataSource.idPre = idPre // idPre存到节点数据源
    }
    returnView = emptyPage
  } else if (['_blank', '_self', '_top', '_parent'].includes(params.type)) {
    const reg = /http(s)?:\/\/([\w-]+\.)+[\w-]+(\/[\w- .\/?%&=]*)?/
    let url = params.url.replace('{{routerBase}}', window.tech.global.routerBase)

    if (!reg.test(url)) {
      url = window.location.host + url
    }
    var el = document.createElement('a')
    document.body.appendChild(el)
    el.href = url
    el.target = params.type
    el.click()
    document.body.removeChild(el)
  } else {
    let dynamicPage = window.tech_app.data.commands.meta.views.page
    const page = makeMainView(params.label || '', dynamicPage, idPre)
    // openView默认不加 断开数据继承 因为之前很多功能用了 如果有引用地址应用 要手动类似这样配置：
    /*
    view: {
        created: {
          inheritData:false,
          openView: {
            。。
          }
        }
      }
    */
    // if (page.inheritData === undefined) {
    //   page.inheritData = false
    // }
    page.menu = params
    page.props.model = params.model
    page.props.view = params.type

    // 赋值app接口参数
    if (page) {
      if (!page.dataSource) {
        page.dataSource = {}
      }
      page.dataSource.menuConfig = params // 菜单配置信息存到节点数据源
      page.dataSource.idPre = idPre // idPre存到节点数据源
      if (params.app) {
        page.dataSource._metaParamsApp = params.app
      }
      // page.dataSource._metaParamsApp = params.app || 'base'
      page.dataSource._metaParamsModel = params.model || ''
    }
    returnView = page
  }
  // 补充样式
  // if (returnView) {
  //   if (!returnView.style) {
  //     returnView.style = {};
  //   }
  //   returnView.style.height = '4rem';
  // }
  return returnView || {}
}
