import { MenuConfig, MicroConfig, WujieProps, hideDomIds, WujieMenu } from './micro-app-data'
import { wujieMenuTransform, isJSONString } from './micro-common'
import { Route, Location } from 'vue-router'
import WujieVue from '@tech/wujie-vue2'
import { bus } from '@tech/wujie'

export default class WujieMicroApp {
  menu: Array<MenuConfig> = []
  inner: boolean = false
  userInfo: Object | null = null
  bus: typeof bus = WujieVue.bus

  constructor(public readonly microConfig: MicroConfig, public wujieProps: WujieProps) {
    if (microConfig.insert !== 'self' && this.wujieProps) {
      // 子应用执行（里层）
      this._init()
      console.log(this)
    }
  }

  private _init() {
    this.inner = true
    // 原菜单配置wujie不需要重建菜单
    if (this.wujieProps.menuConfig.isRebuildView) {
      this._buildMenu(this.wujieProps.menuConfig)
    }
    this._setToken()

    if (this.microConfig.api && this.microConfig.api === 'restful') {
      this._proxyApi()
    }
    this.getUserInfo().then((res) => {
      console.log('用户：', res)
    })
    // this._setMaxTab()
    this._hideContainer()
  }

  private _setToken() {
    Tech.token.set(this.wujieProps.token)
  }

  private _buildMenu(menuConfig: MenuConfig) {
    if (window.techOpenView) {
      // openView打开wujie情况 重新拼接菜单
      let appsMenus = window?.parent?.tech_app?.page?.getNode?.('search_menus_pop_container')?.$ds
        ?.appsMenus
      let sendMenu = []
      let getParent = (menu) => {
        sendMenu.push(window.Tech._cloneDeep(menu))
        let parent = appsMenus.find((item) => item.id == menu.parent_ids)
        if (parent) {
          getParent(parent)
        }
      }
      let curMenu = appsMenus?.find((it) => it.id === menuConfig._menuId)
      if (curMenu) {
        getParent(curMenu)
      }
      this.menu = sendMenu
      getParent = null
      appsMenus = null
    } else {
      // 菜单配置
      this.menu = [
        {
          //手动添加app菜单
          ...menuConfig,
          name: menuConfig.app,
          product_line: true
        },
        {
          ...menuConfig,
          product: menuConfig.app
        }
      ]
    }
  }

  private _hideContainer() {
    const cssStyle = `{
      display: none!important;
      height: 0px;
      width: 0px;
      margin: 0px;
      padding: 0px;
      border: 0px;
      overflow: hidden;
      shadow: none;
      outline: none;
      z-index: -1;
    }
    `
    let cssStr = '#'
    cssStr += hideDomIds.join(`,
     #`)
    cssStr += cssStyle

    cssStr += `
    #tabs_meta_main_content_labels > div > div.el-tabs__header.is-top {
      display: none;
    }
    .vxe-table--tooltip-wrapper{
      position: fixed;
    }
    .m-select-popper{
      position: absolute !important
    }
  `
    if (!window.wujieNoPadding) {
      cssStr += `#tabs_meta_main_content_labels > div > div.el-tabs__content {
        padding: 0;
      }`
    }
    if (window.techOpenView === true) {
      cssStr += `.el-popper{
        position: absolute !important;
      }`
    }
    tech_app.utils.addClass('micro-inner-class', cssStr)
  }

  private _proxyApi() {
    // 代理Tech.metaApi.metaServe方法
    const proxyMetaApi = new Proxy(Tech.metaApi, {
      get: function (target, prop) {
        console.log(prop)
        if (prop === 'metaServe') {
          return function (
            params,
            conf,
            method = 'service',
            showMsg = true,
            directReturn = false,
            serverPath = '',
            options = {}
          ) {
            const restfulPath = `/${params.app}/master/${params.model}/${params.service}?restful=1`

            return Tech.httpMeta({
              data: {
                params,
                conf,
                method,
                showMsg,
                directReturn,
                restfulPath,
                options
              }
            })
          }
        }
        return target[prop]
      }
    })
    Tech.metaApi = proxyMetaApi

    // 代理Tech.httpMeta方法
    const proxyHttpMeta = new Proxy(Tech.httpMeta, {
      apply: function (target, thisArg, argumentsList) {
        const args = argumentsList[0]
        const restfulPath = `${args.type !== 'api' ? tech.apiHost : ''}/${
          args.data.params.app
        }/master/${args.data.params.model}/${args.data.params.service}?restful=1`
        args.url = restfulPath

        args.type = 'api'

        return target.apply(thisArg, argumentsList)
      }
    })
    Tech.httpMeta = proxyHttpMeta
  }

  public getUserInfo() {
    if (tech.userInfo) return resolve(tech.userInfo)
    return new Promise((resolve, reject) => {
      Tech.httpMeta({
        data: {
          // 参考元模型后端的传参规范
          params: {
            args: {},
            service: 'profile',
            model: 'rbac_user',
            app: 'base'
          }
        }
      }).then((res) => {
        tech.userInfo = res.data
        this.userInfo = res.data
        resolve(tech.userInfo)
      })
    })
  }

  public rebuildMenu(menuList: Array<WujieMenu>) {
    if (this.microConfig.insert !== 'self') return menuList

    let result = menuList.map((item) => {
      if (!item.view) return item

      const isJson = isJSONString(item.view)
      // json格式
      if (isJson || !item.model) return item

      // 转换wujie菜单
      return wujieMenuTransform(item)
    })

    return result
  }

  public goto(jumpObj, otherArgs) {
    // 获取父应用的节点，使用父应用的goto方法
    const menuVm = window.parent.tech_app.page.getNode('menu_meta_siderbar')
    if (menuVm) {
      menuVm.$cmd.meta.goTo(menuVm, jumpObj, otherArgs)
    }
  }

  public toMenu(menuTag) {
    // 获取父应用的节点，使用父应用的goto方法
    const menuVm = window.parent.tech_app.page.getNode('menu_meta_siderbar')
    if (menuVm) {
      menuVm.$cmd.toMenu(menuVm, menuTag)
    }
  }

  public getWujieUrl(menu: WujieMenu, router: Route) {
    if (!menu.path) return ''
    const url = menu.path.substring(1)
    // 添加query到url中
    const query = router.query
    if (query) {
      const queryStr = Object.keys(query)
        .map((key) => `${key}=${query[key]}`)
        .join('&')
      if (queryStr) {
        return `${url}?${queryStr}`
      }
    }
    return url
  }

  public clearQuery(query: Location) {
    let curUrl = new URL(location.href)
    let params = new URLSearchParams(curUrl.search)

    for (let i in query) {
      params.delete(i)
    }
    curUrl.search = '?' + params.toString()
    history.pushState(null, '', curUrl.href)
  }

  public clearLinkSearch(url: String) {
    const matches = url.match(/(\w|\/)+/)
    return matches ? matches[0] : url
  }
}
