<template>
  <empty-app ref="emptyApp"></empty-app>
</template>

<script lang="ts">
import { defineComponent } from 'vue'

// 依赖包引入
import { mergeOptions } from '../../importCommon/core.js'

import EmptyApp from '../EmptyApp/index.js'

import assetJsonObj from './schema/assets.json'
import assetsImportObj from './schema/assetsImport.js'
import commonObj from './schema/common.js'
import hookObj from './schema/hook.js'
import schemaObj from './schema/schema.js'
import { getParams } from './apps/base/index.js'
export default defineComponent({
  name: 'tech-meta-page',
  components: {
    EmptyApp
  },
  data() {
    return {}
  },
  mounted() {},
  methods: {
    getParams() {
      let srcOptions = {
        asset: assetJsonObj,
        assetImport: assetsImportObj,
        common: commonObj,
        schema: schemaObj,
        hook: hookObj
      }

      // 合并模板应用扩展
      let baseExtendOptions = getParams()
      srcOptions = mergeOptions(srcOptions, baseExtendOptions)

      return srcOptions
    },
    // 初始化
    async init(useVue: any, options: any, _useLocalParams: Boolean = false) {
      if (_useLocalParams) {
        options = mergeOptions(this.getParams(), options)
      }
      const showAppOptions = sessionStorage.getItem('showAppOptions')
      if (showAppOptions == 'true') {
        console.log(' === to empty app options === ', options)
      }
      // @ts-ignore
      this.$refs.emptyApp.init(useVue, options)
    }
  },
  setup() {
    return {}
  }
})
</script>
<style scoped>
.meta-page {
  width: 100%;
  height: 100%;
}
</style>
<style lang="scss">
html,
body,
#app {
  width: 100%;
  height: 100%;
}

#app {
  position: relative;
  overflow: auto;
}

#app::-webkit-scrollbar {
  width: 0 !important;
  display: none;
}
</style>
