export default {
  print_directive_custom_extend: {
    type: 'merge',
    selector: {
      attr: 'id',
      value: 'page_meta_index'
    },
    beforeOperate: (app, config, options) => {
      config.view = {
        def_directives: {
          t_app_print_directives: {
            beforeBind: true,
            statement: '_print',
            analyse: (vm, config = {}) => {
              const startPrintPreview = async (dsVm, templateId) => {
                const tableVm = vm.$select(
                  vm.$cmd.getIdPre(vm) + 'table_main_table'
                )
                const res = await dsVm.request('printView', {
                  args: {
                    templatePrintReviewDTO: {
                      templatePrintId: templateId,
                      ids: tableVm?.$ds?.checkedDataIds
                    }
                  }
                })
                if (!res?.data?.attachmentId) return
                const printPreviewDialog = {
                  type: 'dialog',
                  title: Tech.$t('print.pPreview'), // 打印预览
                  hasFooter: false,
                  className: 'printPreviewDialog',
                  css: `.printPreviewDialog .choice-dialog{width:100% !important;height:100%;margin-top:0 !important}
                  .printPreviewDialog .choice-dialog .body{height: 100% !important; padding: 0 !important; max-height: calc(100% - 40px) !important; overflow: hidden !important;}
                  .printPreviewDialog .choice-dialog .body>div, .printPreviewDialog .choice-dialog .body>div>div{height: 100%}`,
                  items: [
                    {
                      type: 'iframe',
                      id: 'print_preview_iframe',
                      url: '',
                      style: {
                        width: '100%',
                        height: '100%',
                        border: 0,
                        background: '#fff'
                      }
                    }
                  ],
                  bind_on_opreates: (params) => {
                    if (params.value.type === 'cancel') {
                      params.value.close()
                      // 关闭弹窗后刷新表格数据
                      const refresh = vm.$select(
                        vm.$cmd.getIdPre(vm) + 'table_main_toolbar_refresh'
                      )
                      refresh?.instance?.click()
                    }
                  }
                }
                const newPrintPreviewDialog =
                  window.Tech._cloneDeep(printPreviewDialog)
                newPrintPreviewDialog.items[0].url =
                  window.location.origin +
                  window.tech.routerBase +
                  '?pageId=tech_print_preview_page&attachmentId=' +
                  res.data.attachmentId
                // 24-07-04 修改打印jsonData字段过长问题
                // localStorage.setItem('jsonData', JSON.stringify(res?.data?.data || {}))
                // 25-05-13 数据存储更换至 window,避免 loacalStorage 5m 最大存储限制
                window._printAppJsonData = JSON.stringify(res?.data?.data || {})
                newPrintPreviewDialog.display = true
                vm.$cmd.meta.popupView(vm, newPrintPreviewDialog, vm.$ds.idPre)
              }
              const ds_config = {
                list: [
                  {
                    name: 'lookup',
                    type: 'meta',
                    method: 'service',
                    autoRequest: false,
                    options: {
                      params: {
                        model: 'template_print',
                        service: 'selectTemplatePrint',
                        app: 'sie-iidp-print'
                      }
                    }
                  },
                  {
                    name: 'printView',
                    type: 'meta',
                    method: 'service',
                    autoRequest: false,
                    options: {
                      params: {
                        model: 'template_print',
                        service: 'printView',
                        app: 'sie-iidp-print'
                      }
                    }
                  }
                ]
              }
              const dialogNode = {
                type: 'dialog',
                title: Tech.$t('print.printing'), // 打印
                confirmText: Tech.$t('print.printing'), // 打印
                ds_config,
                items: [
                  {
                    type: 'form',
                    id: 'print_preview_form_choose_template',
                    dataSource: {
                      form: {
                        templateId: ''
                      }
                    },
                    items: [
                      {
                        type: 'lookup',
                        text: Tech.$t('print.pTemplate'), // 打印模板,
                        name: 'templateId',
                        created: (vm) => {
                          vm.$ds.form.templateId = ''
                          const form = vm.$ds.form
                          for (let key in form) {
                            delete form[key + '___values']
                          }
                        },
                        lookupConfig: {
                          getData: async (
                            dataSource = {},
                            params,
                            customFilter = [],
                            f
                          ) => {
                            const table_main = vm.$select(
                              vm.$cmd.getIdPre(vm) + 'table_main'
                            )
                            const res = await f.vm.request('lookup', {
                              args: {
                                app:
                                  vm?.data?.app ||
                                  table_main?.$ds?._metaParamsApp ||
                                  'base', // 优先取视图配置
                                modelName:
                                  vm?.data?.modelName ||
                                  table_main?.$ds?._metaParamsModel // 优先取视图配置
                              }
                            })
                            res?.data?.forEach((i) => {
                              i.label = i.attachmentName
                              i.value = i.id
                            })
                            return {
                              items: res?.data || []
                            }
                          },
                          paging: {
                            autoControll: true,
                            input: '1-20',
                            next: true,
                            prev: false,
                            totalCount: '···'
                          }
                        }
                      }
                    ]
                  }
                ],
                beforeOperate: async (params) => {
                  const tableVm = vm.$select(
                    vm.$cmd.getIdPre(vm) + 'table_main_table'
                  )
                  const table_main = vm.$select(
                    vm.$cmd.getIdPre(vm) + 'table_main'
                  )
                  if (!tableVm?.$ds?.checkedDataIds?.length) {
                    window.ELEMENT.Message.warning(Tech.$t('print.psrData')) // 请选择行数据！
                    return false
                  }
                  const res = await vm.request('lookup', {
                    args: {
                      app:
                        vm?.data?.app ||
                        table_main?.$ds?._metaParamsApp ||
                        'base', // 优先取视图配置
                      modelName:
                        vm?.data?.modelName || table_main?.$ds?._metaParamsModel // 优先取视图配置
                    }
                  })
                  if (res?.data?.length === 1) {
                    // res.data.length=1时直接打印，不弹出选择框
                    startPrintPreview(vm, res.data[0].id)
                    return false
                  }
                  return true
                },
                bind_on_opreates: async (params) => {
                  const { value } = params
                  // 点击了打印按钮
                  if (value.type === 'confirm') {
                    // 调接口 接口返回文件id、预览的真实数据
                    const templateFormVm = vm.$select(
                      'print_preview_form_choose_template'
                    )
                    // const tableVm = vm.$select(vm.$cmd.getIdPre(vm) + 'table_main_table')
                    if (!templateFormVm?.$ds?.form?.templateId) {
                      window.ELEMENT.Message.warning(
                        Tech.$t('print.pspTemplate')
                      ) // 请选择打印模板！
                      return
                    }
                    startPrintPreview(
                      params.self,
                      templateFormVm.$ds.form.templateId
                    )
                    // const res = await params.self.request('printView', {
                    //   args: {
                    //     templatePrintReviewDTO: {
                    //       templatePrintId: templateFormVm.$ds.form.templateId,
                    //       ids: tableVm?.$ds?.checkedDataIds
                    //       // ids: ['rbac_user_superuser']
                    //     }
                    //   }
                    // })
                    // if (!res?.data?.attachmentId) return
                    // const printPreviewDialog = {
                    //   type: 'dialog',
                    //   title: Tech.$t('print.pPreview'), // 打印预览
                    //   hasFooter: false,
                    //   className: 'printPreviewDialog',
                    //   css: `.printPreviewDialog .choice-dialog{width:100% !important;height:100%;margin-top:0 !important}
                    //   .printPreviewDialog .choice-dialog .body{height: 100% !important; padding: 0 !important; max-height: calc(100% - 40px) !important; overflow: hidden !important;}
                    //   .printPreviewDialog .choice-dialog .body>div, .printPreviewDialog .choice-dialog .body>div>div{height: 100%}`,
                    //   items: [
                    //     {
                    //       type: 'iframe',
                    //       id: 'print_preview_iframe',
                    //       url: '',
                    //       style: {
                    //         width: '100%',
                    //         height: '100%',
                    //         border: 0,
                    //         background: '#fff'
                    //       }
                    //     }
                    //   ]
                    // }
                    // const newPrintPreviewDialog = window.Tech._cloneDeep(printPreviewDialog)
                    // newPrintPreviewDialog.items[0].url =
                    //   window.location.origin +
                    //   window.tech.routerBase +
                    //   '?pageId=tech_print_preview_page&attachmentId=' +
                    //   res.data.attachmentId
                    // // 24-07-04 修改打印jsonData字段过长问题
                    // localStorage.setItem('jsonData', JSON.stringify(res?.data?.data || {}))
                    // newPrintPreviewDialog.display = true
                    // vm.$cmd.meta.popupView(vm, newPrintPreviewDialog, vm.$ds.idPre)
                  }
                  value.close()
                }
              }
              if (vm?.parent?.data?.type === 'operation') {
                // TODO 产品暂时没提出放在操作列 暂时搁置
                // vm.data.click = async (vm, scope) => {
                //   if (!scope?.row?.id) return
                //   const newDialogNode = window.Tech._cloneDeep(dialogNode)
                //   newDialogNode.display = true
                //   vm.$cmd.meta.popupView(vm, newDialogNode, '')
                // }
              } else {
                vm.data.options.icon = 'iconfont icon-ASPROJECT'
                vm.data.ds_config = ds_config
                vm.data.view = {
                  click: window.Tech._cloneDeep(dialogNode)
                }
              }
            }
          },
          t_app_print_design_directives: {
            beforeBind: true,
            statement: '_printDesign',
            analyse: (vm, config = {}) => {
              // 设计器
              const dialogNode = {
                type: 'dialog',
                title: Tech.$t('print.designer'), // 设计器
                hasFooter: false,
                className: 'printDesignDialog',
                css: `.printDesignDialog .choice-dialog{width:100% !important;height:100%;margin-top:0 !important}
                      .printDesignDialog .choice-dialog .body{height: 100% !important; padding: 0 !important; max-height: calc(100% - 40px) !important; overflow: hidden !important;}
                      .printDesignDialog .choice-dialog .body>div, .printDesignDialog .choice-dialog .body>div>div{height: 100%}`,
                items: [
                  {
                    type: 'iframe',
                    url: '',
                    style: {
                      width: '100%',
                      height: '100%',
                      border: 0,
                      background: '#fff'
                    }
                  }
                ],
                bind_on_opreates: (params) => {
                  if (params.value.type === 'cancel') {
                    params.value.close()
                    // 关闭弹窗后刷新表格数据
                    const refresh = vm.$select(
                      vm.$cmd.getIdPre(vm) + 'table_main_toolbar_refresh'
                    )
                    refresh?.instance?.click()
                  }
                }
              }

              if (vm?.parent?.data?.type === 'operation') {
                // 操作列按钮
                vm.data.click = async (vm, scope) => {
                  if (!scope?.row?.id) return
                  // window.addEventListener('message', (event) => {
                  //   if (event?.data === '__printDesignDialogClose') {
                  //     const dVm = vm.$select(vm.$ds.idPre + 'print_design_template_dialog')
                  //     dVm?.instance?.close()
                  //   }
                  // })
                  // 调接口
                  const res = await vm.request('otherService', {
                    model: 'template_print',
                    service: 'design',
                    app: 'sie-iidp-print',
                    args: {
                      id: scope.row.id
                    }
                  })
                  if (res?.data) {
                    const { attachmentId, id } = res.data
                    const newDialogNode = window.Tech._cloneDeep(dialogNode)
                    newDialogNode.items[0].url =
                      window.location.origin +
                      window.tech.routerBase +
                      '?pageId=tech_print_design_page&attachmentId=' +
                      attachmentId +
                      '&id=' +
                      id +
                      '&type=0'
                    newDialogNode.display = true
                    vm.$cmd.meta.popupView(vm, newDialogNode, vm.$ds.idPre)
                  }
                }
              } else {
                //tabar 查看按钮
                vm.data.bind_on_click = (params) => {
                  const table = vm.$select(
                    params.self.$ds.idPreTab + 'table_main_table'
                  )
                  if (!table?.$ds?.checkedDataIds?.length) {
                    window.ELEMENT.Message.warning(Tech.$t('print.psrData')) // 请选择行数据！
                    return false
                  }
                  let id = table?.$ds?.checkedDataList[0].id
                  let attachmentId = table?.$ds?.checkedDataList[0].attachmentId

                  const newDialogNode = window.Tech._cloneDeep(dialogNode)
                  newDialogNode.items[0].url =
                    window.location.origin +
                    window.tech.routerBase +
                    '?pageId=tech_print_design_page&attachmentId=' +
                    attachmentId +
                    '&id=' +
                    id +
                    '&type=1'
                  newDialogNode.display = true
                  vm.$cmd.meta.popupView(vm, newDialogNode, table.$ds.idPre)
                }
              }
            }
          },
          t_app_print_download: {
            beforeBind: true,
            statement: '_download',
            analyse: (vm, config = {}) => {
              function getApiBase(baseUrl) {
                let tempApi = ''
                if (sessionStorage) {
                  tempApi = sessionStorage.getItem('tempApi')
                }
                return tempApi || baseUrl
              }
              vm.data.bind_on_click = (params) => {
                const urlPrefix = getApiBase(tech.apiHost) // location.protocol + '//' + location.host
                const urlParams = new URLSearchParams(location.search)
                let table = null
                if (params.self.$ds.idPreTab) {
                  table = vm.$select(
                    params.self.$ds.idPreTab + 'table_main_table'
                  )
                } else {
                  table = vm.$select(params.self.$ds.idPre + 'table_main_table')
                }

                for (const item of table?.$ds?.checkedDataList) {
                  let attachmentId = item.attachmentId
                  let fileName = item.attachmentName
                  let urlPath =
                    urlPrefix +
                    '/file/download?id=' +
                    attachmentId +
                    '&token=' +
                    Tech?.token?.get?.()
                  // let link = document.createElement('a')
                  // link.href = urlPath
                  // link.download = fileName
                  // link.target = '_self' // 可选，如果希望在新窗口中下载文件，请取消注释此行
                  // link.click()

                  setTimeout(function () {
                    // 动态添加iframe,设置src,然后删除
                    const frame = document.createElement('iframe') //创建标签
                    frame.setAttribute('style', 'display: none')
                    frame.setAttribute('src', urlPath)
                    document.body.appendChild(frame)
                    setTimeout(function () {
                      document.body.removeChild(frame)
                    }, 200)
                  }, 100)
                }
              }
            }
          }
        }
      }
      return config.view
    },
    view: {}
  },

  tech_print_design_hide_main_wrap_extend_view: {
    type: 'merge',
    selector: {
      attr: 'id',
      value: 'template_print_menu_container_table_main_wrap'
    },
    beforeOperate: (app, operate, options) => {
      return operate.view
    },
    view: {
      display: false
    }
  }
}
