export function formatDateTimeStr(date, params) {
  return dateFormat(getFormat(params, 'YYYY-MM-DD hh:mm:ss'), date)
}
export function formatDateStr(date, params) {
  return dateFormat(getFormat(params, 'YYYY-MM-DD'), date)
}

export function getFormat(params, defaultFormat) {
  let dateFormat = defaultFormat
  if (typeof params === 'string') {
    dateFormat = params
  } else if (params) {
    dateFormat = params.dateFormat || defaultFormat
  }
  return dateFormat
    .replace('yyyy-MM-dd', 'YYYY-MM-DD')
    .replace('MM-dd', 'MM-DD')
    .replace('yyyy-MM', 'YYYY-MM')
    .replace('HH:mm:ss.SSS', 'hh:mm:ss.SSS')
    .replace('HH:mm:ss', 'hh:mm:ss')
    .replace('HH:mm', 'hh:mm')
    .replace('mm:ss.SSS', 'mm:ss.SSS')
    .replace('ss.SSS', 'ss.SSS')
}
// tttt-TT-dd hh:mm:ss.kkk
export function dateFormat(fmt, date, map) {
  if (!date) {
    date = new Date()
  } else if (typeof date === 'string' || typeof date === 'number') {
    let n = isNaN(Number(date)) ? date : Number(date)
    date = new Date(n)
  }
  // let temp = {
  //   'Y': 't',
  //   'M': 'T',
  //   'S': 'k'
  // };
  var o = {
    'M+': date.getMonth() + 1, // 月份
    'D+': date.getDate(), // 日
    'h+': date.getHours(), // 小时
    'm+': date.getMinutes(), // 分
    's+': date.getSeconds(), // 秒
    'q+': Math.floor((date.getMonth() + 3) / 3) // 季度
  }
  if ((map?.Y && new RegExp('(' + map.Y + '+)').test(fmt)) || /(Y+)/.test(fmt)) {
    fmt = fmt.replace(RegExp.$1, (date.getFullYear() + '').substring(4 - RegExp.$1.length))
  }
  if ((map?.S && new RegExp('(' + map.S + '+)').test(fmt)) || /(S+)/.test(fmt)) {
    fmt = fmt.replace(
      RegExp.$1,
      ((date.getMilliseconds() || '000') + '').substring(0, RegExp.$1.length)
    )
  }
  // if (/(Y+)/.test(fmt))
  //   fmt=fmt.replace(RegExp.$1, (date.getFullYear()+'').substring(4 - RegExp.$1.length));
  // if (/(S+)/.test(fmt))
  //   fmt=fmt.replace(RegExp.$1, ((date.getMilliseconds() || '000')+'').substring(0, RegExp.$1.length));
  for (var k in o)
    if (
      (map?.[k[0]] && new RegExp('(' + map[k[0]] + '+)').test(fmt)) ||
      new RegExp('(' + k + ')').test(fmt)
    )
      fmt = fmt.replace(
        RegExp.$1,
        RegExp.$1.length == 1 ? o[k] : ('00' + o[k]).substring(('' + o[k]).length)
      )
  return fmt
}
