import getOnlyLookRequired from '../../../from-fields/form/onlyLookRequired'

export function openDrawer() {
  let view = {
    type: 'drawer',
    crossEvent: true, // mark的事件穿透
    bind_visible: '$ds.visible', //显示或隐藏抽屉
    hasTitle: false,
    width: '',
    wrapperClosable: false,
    showModal: true,
    // id: 'table_drawer',
    bind_showEditBtn: '${!$ds.isEditDrawerForm}', //显示编辑按钮
    bind_showSaveBtn: '$ds.isEditDrawerForm', //显示保存按钮
    display: true,
    dataSource: {
      visible: true,
      showDrawerBtn: true,
      isEditDrawerForm: true
    },
    commands: {},
    created(vm) {
      vm.$ds.openView = vm.data.openView
      vm.data.width = vm.data.openView.width || '45%'
      const tableMain = vm.$select(vm.$ds.__fromIdPre + 'table_main')
      if (tableMain) {
        // 判断是不是显示只看必填项
        const isOnlyLookRequired =
          tableMain?.$ds?.tableView?.data?.views?.form?.body.onlyLookRequired || false

        if (isOnlyLookRequired) {
          setTimeout(() => {
            const curForm = vm.$select(vm.$ds.idPre + 'form_main_detail_top_common')
            if (curForm) {
              const config = getOnlyLookRequired()
              // 更换ID
              config.id = vm.$ds.idPre + config.id
              config.mounted = (_vm) => {
                const checkEl = _vm?.instance?.$el
                if (checkEl) {
                  const buttonContainer = document.querySelector(
                    `#${vm.$ds.__fromIdPre}table_main_table_column_operation_custom_view_click_items_0`
                  )
                  if (buttonContainer) {
                    buttonContainer.appendChild(checkEl)
                  }
                }
              }
              // 添加只看必填项节点
              vm.app.updatePageNode(config, vm, () => {
                vm.data.items.push(config)
              })
            }
          }, 200)
        }
      }
    },
    mounted(vm) {},
    items: [
      {
        type: 'container',
        // id: 'drawer_title',
        style: {
          'margin-bottom': '0.1rem',
          'padding-top': '.05rem',
          display: 'flex',
          'align-items': 'center'
        },
        items: [
          {
            type: 'button',
            value: Tech.$t('detailView.close'),
            style: {
              color: '#606266',
              'font-size': '0.15rem',
              'border-right': '0 none'
            },
            options: {
              type: 'text',
              icon: 'el-icon-close'
            },
            bind_on_click: (res) => {
              const { self: vm } = res
              // vm.$ds.visible = false
              vm.parent.parent.data.display = false
            }
          },
          {
            type: 'pagetopsplit',
            bind_display: '${!$ds.isEditDrawerForm && $ds.showDrawerBtn}',
            style: {
              height: '.14rem',
              'background-color': '#CCCCCC',
              margin: '0 .07rem'
            }
          },
          {
            type: 'button',
            value: Tech.$t('gridView.editBtn'),
            bind_display: '${!$ds.isEditDrawerForm && $ds.showDrawerBtn}',
            options: {
              size: 'mini'
            },
            className: 'custom_table_drawer_btn',
            css: `.custom_table_drawer_btn{
                font-size: 0.14rem;
                padding: 0.06rem 0.1rem;
                border: none;
                background: #677177;
                color: #fff;
              }
              .custom_table_drawer_btn:hover,
              .custom_table_drawer_btn:focus {
                color: #fff;
                background: #495053;
              }
            `,
            bind_on_click: (res) => {
              const { self: vm } = res
              vm.$ds.isEditDrawerForm = true
            }
          },
          {
            type: 'button',
            value: Tech.$t('detailView.affirm'),
            bind_display: '$ds.isEditDrawerForm && $ds.showDrawerBtn',
            options: {
              size: 'mini'
            },
            className: 'custom_table_drawer_btn',
            css: `.custom_table_drawer_btn{
                font-size: 0.14rem;
                margin-left: 0.05rem;
                padding: 0.06rem 0.1rem;
                border: none;
                background: #677177;
                color: #fff;
              }
              .custom_table_drawer_btn:hover,
              .custom_table_drawer_btn:focus {
                color: #fff;
                background: #495053;
              }
            }`,
            loading: false,
            _clickTimer: null,
            bind_on_click: async (res) => {
              const { self: vm, value } = res
              const table_detail = vm.$select(`${vm.$ds.idPre}table_detail`)
              let result = {}
              // 默认情况
              // 表单，点击详情页面保存按钮
              if (table_detail?.$ds?.isSingleFormView) {
                //表单防重点
                vm.data.loading = true
                if (vm.data._clickTimer) {
                  clearTimeout(vm.data._clickTimer)
                  vm.data._clickTimer = null
                }
                vm.data._clickTimer = setTimeout(() => {
                  vm.data.loading = false
                }, 500)

                const saveBtn = table_detail.$select(`${vm.$ds.idPre}form_main_detail_top_save`)
                result = await saveBtn.$cmd.saveForm({ self: saveBtn })
                if (!saveBtn.$ds.isFormSucc) {
                  return
                }
                window.ELEMENT.Message.success(Tech.$t('detailView.successHint'))
              }

              // 表格情况
              if (vm.$ds?.openView?.type?.indexOf('grid') > -1) {
                // 防重点
                if (vm._savingForm) {
                  return
                }
                vm._savingForm = true
                if (vm._savingFormTimer) {
                  window.clearTimeout(vm._savingFormTimer)
                  vm._savingFormTimer = null
                }
                vm._savingFormTimer = window.setTimeout(() => {
                  if (params?.self) {
                    vm._savingForm = false
                  }
                }, 2500)
                // loading初始化
                let loadingInstance = null
                let loadingOptions = { text: Tech.$t('detailView.saveLoading') }
                if (!loadingInstance) {
                  loadingInstance = window.ELEMENT.Loading.service(loadingOptions)
                }
                // 配置api情况

                // 主表格
                const mainTableNode = vm.$select(vm.$ds.idPre + 'table_main_wrap')
                // save配置
                const gridSaveConfig = vm.$ds?.openView?.api?.grid?.save
                if (gridSaveConfig) {
                  const originParams = {
                    model: vm.$ds.openView.model,
                    service: 'search'
                  }
                  result = await vm.$cmd.meta.openViewApi({
                    apiConfig: gridSaveConfig,
                    vm: mainTableNode,
                    dsConfigName: 'confirm',
                    originParams
                  })
                  if (result?.error) {
                    window.ELEMENT.Message.error(result.error?.message)
                    // 关闭loading
                    loadingInstance.close()
                    return
                  }
                  if (result?.data?.message) {
                    window.ELEMENT.Message.success(result.data.message?.text)
                  } else {
                    window.ELEMENT.Message.success(Tech.$t('detailView.successHint'))
                  }
                }
                if (vm._savingFormTimer) {
                  window.clearTimeout(vm._savingFormTimer)
                  vm._savingFormTimer = null
                }
                vm._savingForm = false
                // 关闭loading
                loadingInstance.close()
              }

              // 自定义确认按钮事件
              let cusConfirm = vm.$ds.openView.confirm
              if (cusConfirm) {
                if (Object.prototype.toString.call(cusConfirm) === '[object String]') {
                  try {
                    cusConfirm = window.tech_app.utils._cloneDeep(vm.$ds.openView.confirm)
                    cusConfirm = new Function('return ' + cusConfirm)()
                  } catch (error) {
                    console.log(' === openView Api reqPrep error == ', error)
                  }
                }
                const ctnVm = vm.$select(`${vm.$ds.idPre}container_main`)
                let confirmResult = undefined
                if (ctnVm.$cmd.isAsync(cusConfirm)) {
                  confirmResult = await cusConfirm(vm, result)
                } else {
                  confirmResult = cusConfirm(vm, result)
                }
                if (confirmResult === false) {
                  return
                }
              }

              vm.parent.parent.data.display = false
            }
          }
        ]
      },
      {
        type: 'container',
        id: 'drawer_content',
        items: []
      }
    ]
  }
  return view
}
