// 处理输入字段的校验问题

/**
 * 验证值是否是整数
 * @param {rule} rule rule
 * @param {value} value value
 * @param {*} callback 回调
 */
export function validateInteger(rule, value, callback) {
  if (value === '' || value == null) {
    callback()
    return
  }

  if (Number.isInteger(Number(value))) {
    if (String(value).indexOf('.') !== -1) {
      callback(new Error(Tech.$t('register.integerValidate')))
    } else {
      callback()
    }
  } else {
    callback(new Error(Tech.$t('register.integerValidate')))
  }
}

/**
 * 验证值是否是数字,包括整数和小数
 * @param {rule} rule rule
 * @param {value} value value
 * @param {*} callback 回调
 */
export function validateNumber(rule, value, callback) {
  if (value === '' || value == null) {
    callback()
    return
  }

  if (isNaN(value)) {
    callback(new Error(Tech.$t('register.numValidate')))
  } else {
    callback()
  }
}

