export function getRegexRule(pattern, message) {
  return {
    trigger: 'change',
    required: false,
    pattern,
    message
  }
}

// eslint-disable-next-line no-unused-vars
export function validateMetaModelPropertyFactory(metaColumn) {
  let evalFn = null
  if (metaColumn.uiRuleScript) {
    evalFn = bindUIRuleScript(metaColumn.uiRuleScript)
  }
  // eslint-disable-next-line no-unused-vars
  const fn = ({ rule, value, callback } = options) => {
    if (value == null || value === '') {
      callback()
      return
    }

    if (metaColumn.isString()) {
      const length = metaColumn.getLength()
      if (length != null && !isNaN(length) && length >= 0) {
        if (typeof value === 'string' && value.length > length) {
          callback(new Error(Tech.$t('register.lengthThan') + length))
          return
        }
        const minValue = metaColumn.getMinValue(),
          maxValue = metaColumn.getMaxValue()
        if (minValue != null && !isNaN(minValue) && value.length < minValue) {
          callback(new Error(Tech.$t('register.lengthLess') + minValue))
          return
        }
        if (maxValue != null && !isNaN(maxValue) && value.length > maxValue) {
          callback(new Error(Tech.$t('register.lengthThan') + maxValue))
          return
        }
      }
    }

    if (metaColumn.isNumber()) {
      if (metaColumn.isInteger()) {
        if (!Number.isInteger(Number(value))) {
          callback(new Error(Tech.$t('register.integerValidate')))
          return
        } else if (String(value).indexOf('.') !== -1) {
          callback(new Error(Tech.$t('register.integerValidate')))
          return
        }
      } else {
        if (isNaN(value)) {
          callback(new Error(Tech.$t('register.numValidate')))
          return
        }
      }
      value = Number(value)
      const minValue = metaColumn.getMinValue(),
        maxValue = metaColumn.getMaxValue()
      if (minValue != null && !isNaN(minValue) && value < minValue) {
        callback(new Error(Tech.$t('register.belowMin') + minValue))
        return
      }
      if (maxValue != null && !isNaN(maxValue) && value > maxValue) {
        callback(new Error(Tech.$t('register.thanMax') + maxValue))
        return
      }
    }

    if (evalFn) {
      const result = evalFn(value)
      if (result === false) {
        callback(new Error())
      } else if (result instanceof Error) {
        callback(result)
      } else if (Array.isArray(result) && result.length > 0 && result[0] instanceof Error) {
        callback(result[0])
      }
    }

    callback()
  }
  return fn
}

function bindUIRuleScript(obj) {
  return Function('"use strict";return (' + obj + ')')()
}
