export function container() {
  let view = {
    // 普通容器
    type: 'container',
    display: true,
    commands: {},
    created(vm) {},
    mounted(vm) {
      setTimeout(() => {
        // 设置openview中container_main节点的overflow
        tech_app.utils.addClass(
          `${vm.data.openView?.preId}openview-container_main-css`,
          `
          #${vm.data.openView?.preId}container_main {
            overflow: initial !important;
          }
          `
        )
      }, 200)
    },
    destroy(vm) {},
    items: []
  }
  return view
}
