import resetPasswordView from '../components/resetPassword'
export default {
  header_left_reset_pwd_extend_view: {
    selector: {
      // 如果是节点id列表
      attr: 'id', // 属性 key
      value: 'button_meta_header_user_rest_pwd'
    },
    type: 'custom',
    beforeOperate: (app, operateItem, options) => {
      options.element.bind_on_click = (params) => {
        let vm = params.self
        let resetPassword = window.Tech._cloneDeep(operateItem.view)
        // console.log(resetPassword,'resetPassword')
        resetPassword.dataSource.rowData = JSON.parse(window.Tech.cookies.get('userInfo'))
        resetPassword.display = true
        let bottomContainer = vm.$select('pop_top_rest_pwd_container')
        bottomContainer.data.items = []
        vm.$cmd.meta.addIdPre(resetPassword, vm.$ds.idPre)
        vm.app.updatePageNode(resetPassword, bottomContainer, () => {
          bottomContainer.data.items.push(resetPassword)
        })
      }
      return operateItem.view
    },
    view: resetPasswordView
  }
}
