export default {
  // 登录初始化修改密码提醒弹窗
  type: 'dialog',
  showCancel: true,
  id: 'container_password_init_remind',
  width: '35%',
  title: Tech.$t('common.passwordInitRemind'),
  display: false,
  notice: 0, // 到期提醒 1需要，0不需要
  days: 0,
  time: 0,
  bind_on_opreates: async (params) => {
    const { self: vm, value } = params
    if (value.type === 'confirm') {
      // 打开修改密码弹窗
      vm.$select('button_meta_header_user_rest_pwd').instance.click()
    } else {
      if (vm.data.notice == 1) {
        // 如果pwd_reset_notice等于1 则打开密码过期提醒弹窗
        vm.$select('container_password_expire_remind').data.display = true
        vm.$select('container_password_expire_notice_text').data.value =
          Tech.$t('common.passwordWillExpire') +
          vm.data.time +
          Tech.$t('common.passwordResidual') +
          vm.data.days +
          Tech.$t('common.changeLoginPassword')
      }
    }
    value.close()
  },
  items: [
    {
      type: 'text',
      id: 'container_password_init_notice_text',
      value: Tech.$t('common.passwordInitRemindChange')
    }
  ]
}
