//上下表格模板 子从表 从form-tabs.js复制
export default {
  id: 'form-tabs',
  name: 'form-tabs',
  type: 'container',
  className: 'form-tabs-wrap-ctn',
  style: {
    display: 'flex',
    height: '100%',
    width: '100%'
  },
  ds_config: {
    list: [
      {
        name: 'selectedTableData', // er 弹出 请求左侧数据接口定义
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {
          params: {}
        }
      }
    ]
  },
  items: [
    {
      type: 'container',
      id: 'form-tabs-wrap',
      className: 'form-tabs-wrap-css',
      style: {
        'overflow-x': 'auto',
        display: 'flex',
        height: '100%',
        width: '100%'
      },
      css: '.form-tabs-wrap-css .tech-tabs > .el-tabs > .el-tabs__content{overflow-y: auto;}',
      items: [
        {
          type: 'tabs',
          id: 'form-tabs-node',
          close: false,
          activeId: '',
          activeWork: true, // 切换到的tab才生效
          style: {
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            width: '100%'
          },
          created: async (vm) => {
            vm.data.items = []
            // 获取的loadView接口数据
            let loadViewData = vm.$select(vm.$ds.idPre + 'table_main_wrap').$ds.tableView
            if (loadViewData?.data) {
              loadViewData = loadViewData.data
            }
            // tabsActiveWork：激活所有子表tab
            if (loadViewData?.views?.form?.body?.tabsActiveWork === false) {
              vm.data.activeWork = false
            }
            // console.log(' === loadViewData === ', loadViewData);
            // 传进tabs-utils里面的方法转换
            let tabs = await vm.$cmd.meta.formatTabs(vm, {
              view: loadViewData?.views?.form,
              fields: loadViewData?.fields,
              permissions: loadViewData?.permissions
            })
            // console.log(' ==== tabs === ', tabs);
            for (let i = 0; i < tabs.length; i++) {
              // 如果是页面初始化，子表渲染时也要清除高级表格基础配置缓存
              if (vm.$ds.isInitPage && window.$tech?.techAdvancedTable) {
                sessionStorage.removeItem(tabs[i].dataSource.idPreTab + 'grid_dynamic_config')
              }
              // 如果子表带有formpart，则不追加到tabs
              if (tabs[i]?.body?.type == 'formpart') continue
              vm.app.updatePageNode(tabs[i], vm, () => {
                try {
                  // 若原来有相同id则先移除
                  if (tabs[i]?.id) {
                    let fIndex = vm.data.items.findIndex((it) => it.id === tabs[i].id)
                    if (fIndex !== -1) {
                      vm.data.items.splice(fIndex, 1)
                    }
                  }
                } catch (e) {}
                vm.data.items.push(tabs[i])
              })
            }
            try {
              let formTabsObj = vm.$select(vm.$ds.idPre + 'form-tabs')
              if (vm.data.items.length > 0) {
                formTabsObj.data.style.display = 'block'
              } else {
                formTabsObj.data.style.display = 'none'
              }
            } catch (e) {
              console.log('==== formTabsObj === error ==', e)
            }
            //获取主表暂存选择的tab
            // TODO activeSubTab
            // const form = vm.$select(vm.$ds.idPre + 'form-tabs-wrap')
            const form = vm.$select(vm.$ds.idPre + 'container_main')
            let maintableObj = vm.$select(vm.$ds.idPre + 'table_main_table')
            form.$ds.activeTab = maintableObj.$ds.preTab
              ? maintableObj.$ds.preTab
              : form.$ds.activeTab
            // 获取点击编辑前当前选择的tab，如果有就选中，如果没有就选择第一个
            vm.data.activeId = form.$ds.activeTab
              ? form.$ds.activeTab
              : tabs?.[0]?.id
              ? tabs?.[0]?.id
              : ''
            vm.instance?.$nextTick(() => {
              vm.$cmd.syncTableFormSaveStatus(vm)
              if (!vm.instance) {
                return
              }
              //清除主表暂存选择的tab
              maintableObj.$ds.preTab = null
              vm.instance.goto({ name: vm.data.activeId })
              const container_table_main_wrap = document.getElementById(
                vm.$ds.idPre + 'container_tab_sub_table_wrap'
              )
              const container_table_tab_wrap = document.querySelector(
                `#${vm.$ds.idPre}form-tabs-node .el-tabs__header`
              )
              const container_main = document.querySelector(`#${vm.$ds.idPre}container_main`)
              const table_wrapper = document.querySelector(
                `#${vm.$ds.idPre}table_main_table .vxe-table--render-wrapper`
              )
              if (!container_table_tab_wrap) return
              container_table_tab_wrap.style.cursor = 'move'
              container_table_tab_wrap.style.height = 'auto'
              //监听tabs拖拽改变上下表格高度
              container_table_tab_wrap.addEventListener('mousedown', (e) => {
                const container_form_main_wrap1 = vm.$select(vm.$ds.idPre + 'table_main_table')
                // const container_form_main_wrap = document.getElementById(vm.$ds.idPre + 'table_main_table')
                const container_table_main_wrapdiv = document.getElementById(
                  vm.$ds.idPre + 'container_tab_sub_table_wrap'
                )
                // tabs组件的位置信息
                let tabsRect = vm.instance.$el.getBoundingClientRect()
                // 上半部表单的位置信息
                let formRect = container_form_main_wrap1.instance.$el.getBoundingClientRect()
                // 记录点击时，tabs组件顶点和表单上半部分的顶点间的距离（表单的上半部分div高度不能代表tabs组件的顶点位置）
                // 整个区域的高度
                let formMainH = document.getElementById(
                  vm.$ds.idPre + 'table_main_wrap'
                ).scrollHeight // 整体滚动高度
                let searchnH = document.getElementById(
                  vm.$ds.idPre + 'main_table_search_container'
                ).offsetHeight
                let toolbarH = document.getElementById(
                  vm.$ds.idPre + 'table_main_toolbar'
                ).offsetHeight
                let oldH = tabsRect.y - formRect.y
                function move(eMove, e) {
                  // container_form_main_wrap1.data.style.overflow = 'auto'
                  let distance = eMove.clientY - e.clientY
                  let newtabelHei = oldH + distance
                  let newtabsHei = formMainH - newtabelHei - searchnH - toolbarH
                  if ((distance > -10 && distance < 10) || newtabsHei < 50) {
                    return
                  }
                  // 改变上半部分的div高度
                  container_form_main_wrap1.data.style = {
                    height: newtabelHei + 'px',
                    overflow: 'auto',
                    padding: '0.06rem 0.07rem',
                    backgroundColor: 'var(--table-padding-bg,#fff)'
                  }
                  // container_form_main_wrap1.data.style.height =  newtabelHei + 'px'
                  // 改变下半部分的div高度
                  container_table_main_wrapdiv.style.height = newtabsHei + 'px'
                }
                document.body.onmousemove = (eMove) => {
                  container_main.style['user-select'] = 'none'
                  table_wrapper.style['user-select'] = 'none'
                  move(eMove, e)
                }
                document.body.addEventListener('mouseup', (e) => {
                  document.body.onmousemove = null
                  container_main.style['user-select'] = 'text'
                  table_wrapper.style['user-select'] = 'text'
                })
              })
            })
          },
          commands: {
            // 同步主表保存状态 遍历主表里面的tabs
            syncTableFormSaveStatus: (vm) => {
              try {
                let tabHasNotSave = false
                // 获取tabs节点
                let tabs = vm.$select(vm.$ds.idPre + 'form-tabs-node')
                // console.log(' ==== tabs === ', tabs);
                if (tabs?.data?.items) {
                  tabs.data.items.map((item) => {
                    let tabNode = vm.$select(item.id)
                    if (tabNode) {
                      if (tabNode.$ds.isTabNotSave) {
                        tabHasNotSave = tabNode.$ds.isTabNotSave
                      }
                    }
                  })
                }
                vm.$ds.isNotSave = vm.$ds.isFormNotSave || tabHasNotSave
              } catch (e) {
                console.log(' ==== syncFormSaveStatus == error == ', e)
              }
            }
          },
          ds_config: {
            mainTableRowDataId: null,
            list: [
              {
                name: 'lookup',
                type: 'meta',
                method: 'service',
                autoRequest: false,
                options: {}
              }
            ]
          },
          items: [],
          bind_on_goto: (params) => {
            const { self: vm } = params
            // tabs切换的时候将当前选中的tab的id存到表单的$ds中
            // TODO activeSubTab
            // const form = vm.$select(vm.$ds.idPre + 'form-tabs-wrap')
            const form = vm.$select(vm.$ds.idPre + 'container_main')
            form.$ds.activeTab = vm.data.activeId
            const activeTab = vm.$select(form.$ds.activeTab)
            const table_detail = vm.$select(`${vm.$ds.idPre}table_detail`)
            //如果修改了关联主表选中行重新执行查询
            if (
              table_detail &&
              (activeTab?.data?.mainTableRowDataId != table_detail?.$ds?.mainTableRowData?.id ||
                !activeTab?.data?.mainTableRowDataId) &&
              activeTab &&
              (activeTab?.$ds?._viewType != 'singleGrid' || activeTab?.$ds?.searchByMainTable) //增加配置searchByMainTable更新子表
            ) {
              if (activeTab.$ds.typeView == 'subTable' && activeTab.$ds.idPreTab) {
                const parentTable = activeTab.$select(vm.$ds.idPre + 'table_main_table')
                //上下表格模板 && 主页 && 主表没有可选行传给子表 没有设置自动查询的 不调子表的查询接口
                // Er表或autoSearch为true，主表无数据，子表不查询
                // Er表或autoSearch为true，主表未选择数据，子表不查询
                if (
                  parentTable.instance &&
                  (activeTab.$ds.tabViewType != 'singleGrid' ||
                    activeTab.$ds.searchByMainTable?.autoSearch) &&
                  (parentTable.$ds.tableData.data.length == 0 ||
                    !parentTable.$ds.selectedTableData[0])
                ) {
                  // 5-27 兼容处理 主表无数据时,清空子表的分页
                  const clearSubTableData = (subNode, type) => {
                    if (subNode?.$ds?.tableData) {
                      subNode.$ds.tableData.data = []
                      subNode.$ds.tableDataCount.data = 0
                      subNode.$ds.paging.next = false
                      subNode.$ds.paging.pageStart = 0
                      subNode.$ds.paging.currentPage = 1
                    }
                  }
                  if (vm?.data?._gotoTimer) {
                    vm.data._gotoTimer = null
                  }
                  vm.data._gotoTimer = setTimeout(() => {
                    const container_tab_sub_table_wrap = vm.$select(
                      `${activeTab.$ds.idPreTab}container_tab_sub_table_wrap`
                    )
                    if (!container_tab_sub_table_wrap) {
                      // 子表未渲染，设置500毫秒后的重试定时器
                      vm.data._gotoTimer = setTimeout(() => {
                        const retryContainer = vm.$select(
                          `${activeTab.$ds.idPreTab}container_tab_sub_table_wrap`
                        )
                        clearSubTableData(retryContainer)
                        vm.data._gotoTimer = null
                      }, 500)
                    } else {
                      // 元素存在，直接清空数据
                      clearSubTableData(container_tab_sub_table_wrap)
                      vm.data._gotoTimer = null
                    }
                  }, 200)
                  return
                }
              }
              activeTab.data.mainTableRowDataId = table_detail.$ds.mainTableRowData.id
              const rowParams = {
                row: table_detail.$ds.mainTableRowData
              }
              let tableObj = vm.$select(vm.$ds.idPre + 'table_main_table')
              tableObj.$cmd.changeSubTable(vm, rowParams)
            }
          }
        }
      ]
    }
  ]
}
