/**
 * 显示授权到期消息对话框
 * @param {string} grantMsg - 授权消息内容
 */
function showGrantMessage(grantMsg) {
  console.log(' === grant_msg === ', grantMsg)
  if (grantMsg) {
    window.Tech.confirmbox({
      width: '35%',
      title: Tech.$t('login.authorizationExpiredReminder'),
      items: [
        {
          id: 'grant_message_confirm_box',
          value: grantMsg,
          type: 'text'
        }
      ],
      showCancel: false,
      options: {
        confirm: (close) => {
          close()
        },
        cancel: (close) => {
          close()
        }
      }
    })
  }
}
// 设置localStorage
Storage.prototype.setExpire = (key, value, expire) => {
  let obj = {
    data: value,
    time: Date.now(),
    expire: expire
  }
  localStorage.setItem(key, JSON.stringify(obj))
}
// 读取localStorage
Storage.prototype.getExpire = (key) => {
  let val = localStorage.getItem(key)
  if (!val) {
    return val
  }
  val = JSON.parse(val)
  if (Date.now() - val.time > val.expire) {
    localStorage.removeItem(key)
    return null
  }
  return val.data
}

