export default {
  type: 'container',
  id: 'container_formpart',
  fromType: 'formpart',
  style: {
    padding: '0.15rem',
    background: '#fff',
    height: '100%',
    overflow: 'auto'
  },
  created: async (vm) => {},
  items: [
    {
      type: 'form',
      id: 'form_formpart',
      className: 'form_formpart',
      created: async (vm) => {
        // 表单预览状态展示
        if (window.$tech?.previewForm && vm.$ds.clickType == 'preview') {
          vm.data.formConfig.preview = true
          vm.data.formConfig.previewChange = vm.$cmd.meta.formFormat.previewChange
        }
        let table_detail = vm.$select(vm.$ds.idPre + 'table_detail')
        let tree_main = vm.$select(vm.$ds.idPre + 'tree_main_wrap')
        let filterId = ''
        let res = {}
        if (table_detail?.instance && table_detail?.$ds?.clickType !== 'add') {
          // 从主表跳转到编辑/详情表单的情况
          filterId = table_detail?.$ds?.mainTableRowData?.id || ''
        }
        if (tree_main?.instance && tree_main?.$ds?.clickType !== 'add') {
          // 左树右表单的情况
          filterId = tree_main?.$ds?.currentId || ''
        }
        if (filterId) {
          res = await vm.request('formPartData', {
            model: vm.$ds.menuConfig.model,
            service: 'search',
            args: {
              filter: [['id', '=', filterId]],
              properties: vm.$cmd.meta.toProperty(vm.$ds.formPartColumns, vm.$ds.formPartFields)
            }
          })
        }

        let rowRes = res?.data?.[0] || {}
        // console.log(' ==== rowRes === ', rowRes);
        vm.$ds.form = Object.assign(vm.$ds.form, rowRes)
      },
      formConfig: {
        labelPosition: 'top',
        labelWidth: '0.7rem',
        marginRight: '0.2rem',
        size: 'small',
        // disabled: false
        bind_disabled: '$ds.clickType === "preview"'
      },
      ds_config: {
        list: [
          {
            name: 'formPartData',
            type: 'meta',
            method: 'service',
            autoRequest: false,
            options: {
              params: {
                bind_model: '$ds.menuConfig.model',
                service: 'search',
                args: {
                  useDisplayForModel: true,
                  limit: 1,
                  offset: 0,
                  order: ''
                  // bind_properties: '${$ds.tableView?.data?.views?.search?.body?.columns || []}'
                }
              }
            }
          },
          {
            name: 'formSearch',
            type: 'meta',
            method: 'service',
            autoRequest: false,
            options: {}
          },
          {
            name: 'lookup',
            type: 'meta',
            method: 'service',
            autoRequest: false,
            options: {}
          }
        ]
      },
      style: {
        background: '#fff',
        // 'display': 'grid',
        'grid-template-columns': 'auto auto auto'
      },
      items: []
    }
  ]
}
