export default {
  // 使用个人查询方案弹窗
  type: 'dialog',
  id: 'dialog_meta_use_query_scheme',
  width: '80%',
  title: Tech.$t('seniorTable.usePersonalQueryScheme'),
  display: false,
  hasFooter: false,
  confirmText: Tech.$t('toolbar.dialogConfirm'),
  cancelText: Tech.$t('toolbar.dialogCancle'),
  commands: {
    searchUserSchemeFn: async (vm) => {
      // 查询使用个人查询方案
      const idPre = vm.$cmd.getIdPre(vm)
      let commonForm = vm.$select(idPre + 'form_main_table_search_common')
      let params = {
        args: {
          signId: `${commonForm.$ds.tableView.data.views?.search.view_id}&${vm.$cmd.getIdPre(
            vm
          )}container_table_search`,
          signType: 'searchScheme'
        },
        model: 'rbac_user_prefer',
        tag: 'master',
        service: 'queryUserScheme',
        app: 'iidp-user-prefer'
      }
      let res = await commonForm.request('getScheme', params)
      if (res?.data) {
        // 设置表格回填数据
        vm.$ds.fieldList = res.data
        // 默认选中
        // vm.data.defaultCheck = [res.data.find((item) => item.isSelected)?.id]
        vm.data.defaultCheck = [vm.$ds.selectedSchemeId]
      }
    }
  },
  dataSource: {
    selectedSchemeId: ''
  },
  items: [
    {
      type: 'container',
      id: 'use_query_scheme_table_box',
      className: 'use_query_scheme_table_box',
      dataSource: {
        fieldList: []
      },
      created: (vm) => {
        const idPre = vm.$cmd.getIdPre(vm)
        const pageVm = vm.$select(idPre + 'container_main_content')
        const tableVm = vm.$select(idPre + 'use_query_scheme_table')
        let index = tableVm.data.items.findIndex((item) => item.name == 'isOpen')
        // 不是管理员删掉 表格是否默认列
        if (index > -1 && !pageVm.$ds.isAdmin) tableVm.data.items.splice(index, 1)
      },
      css: `
        .use_query_scheme_table_box .vxe-table--render-default.vxe-editable .vxe-body--column{
          padding: 0.05rem 0;
        }
        .use_query_scheme_table_box .vxe-table--render-default .vxe-cell{
          white-space: normal !important;
          text-overflow: inherit !important;
        }
      `,
      items: [
        {
          type: 'table',
          id: 'use_query_scheme_table',
          checkbox: 'single',
          dataSource: {
            checkedDataList: []
          },
          defaultCheck: [],
          bind_on_select: async (params) => {
            let { self: vm, value } = params
            if (!value.data?.id) return
            vm.$ds.checkedDataList = [value.data]
            vm.$ds.selectedSchemeId = value.data.id
            const idPre = vm.$cmd.getIdPre(vm)
            let tableMain = vm.$select(idPre + 'table_main')
            let schemeTable = vm.$select(idPre + 'use_query_scheme_table')
            const commonForm = vm.$select(idPre + 'form_main_table_search_common')
            const dropdownForm = vm.$select(idPre + 'form_main_table_search_dropdown')
            const dialogSearchDropdown = vm.$select(idPre + 'dialog_meta_use_query_scheme')
            let signContent = JSON.parse(schemeTable.$ds.checkedDataList[0]?.signContent)
            let getDataProperty = tableMain.$cmd.meta.toProperty(
              tableMain.$ds.tableView.data.views.grid.body.columns,
              tableMain.$ds.tableView.data.fields
            )
            // await tableMain.request('tableData', param) // 重新请求表格数据
            const searchBtn = vm.$select(idPre + 'form_main_table_search_btn')
            searchBtn.instance.click()
            // let filterObj = { ...commonform.$ds.form, ...dropdownForm?.$ds.form }
            for (const key in signContent.formData) {
              // 清空搜索
              if (Object.hasOwnProperty.call(commonForm?.$ds?.form, key)) {
                if (signContent.formData[key + '___values']) {
                  commonForm.$ds.form[key] = signContent.formData[key + '___values']
                } else {
                  commonForm.$ds.form[key] = signContent.formData[key]
                }
              }
              if (Object.hasOwnProperty.call(dropdownForm?.$ds?.form, key)) {
                if (signContent.formData[key + '___values']) {
                  dropdownForm.$ds.form[key] = signContent.formData[key + '___values']
                } else {
                  dropdownForm.$ds.form[key] = signContent.formData[key]
                }
              }
            }
            setTimeout(() => {
              commonForm.$ds.tableFilter = signContent.tableFilter
              commonForm.$ds.tableFilterTags = signContent.tableFilterTags
            }, 500)
            dialogSearchDropdown.data.display = false
          },
          beforeEditMethod: ({ row, column, rowIndex, columnIndex }) => {
            //根据数据是否可以编辑
            if (row.isEdit) {
              return true
            }
            return false
          },
          created: (vm) => {
            // 查询使用个人查询方案
            vm.$cmd.searchUserSchemeFn(vm)
          },
          isEdit: true,
          id: 'use_query_scheme_table',
          style: {
            minHeight: '3.5rem'
          },
          bind_tableData: '$ds.fieldList',
          items: [
            {
              type: 'seq',
              width: 60,
              title: Tech.$t('transferTable.serial')
            },
            {
              type: 'text',
              field: 'name',
              title: Tech.$t('seniorTable.schemeName'),
              editRender: {
                configs: {
                  editType: 'input'
                }
              }
            },
            {
              type: 'text',
              field: 'description',
              title: Tech.$t('treeView.des'),
              editRender: {
                configs: {
                  editType: 'input'
                }
              }
            },
            {
              type: 'switch',
              field: 'isOpen',
              name: 'isOpen',
              model: {},
              formatItem: (row, item) => {
                item.model = row
                return item
              },
              title: Tech.$t('seniorTable.whetherToMakePublic')
            },
            {
              type: 'operation',
              field: 'operate',
              title: Tech.$t('seniorTable.controls'),
              fixed: 'right',
              items: [
                {
                  text: Tech.$t('actionScope.save'),
                  action: 'update',
                  options: {
                    type: 'text'
                  },
                  enableCondition: (row) => {
                    // 按钮是否禁用
                    return row[0].isEdit
                  }
                },
                {
                  text: Tech.$t('toolbar.delete'),
                  action: 'delete',
                  options: {
                    type: 'text'
                  },
                  enableCondition: (row) => {
                    // 按钮是否禁用
                    return row[0].isEdit
                  }
                }
              ]
            }
          ],
          bind_on_clickOptionBtn: async (params) => {
            const { self: vm, value } = params
            const idPre = vm.$cmd.getIdPre(vm)
            let commonForm = vm.$select(idPre + 'form_main_table_search_common')
            let btnType = value?.btn?.action //获取操作按钮类型
            // 针对点击编辑/详情按钮
            if (btnType == 'delete') {
              let param = {
                args: {
                  ids: [value.scope.row.id]
                },
                model: 'rbac_user_prefer',
                tag: 'master',
                service: 'delete',
                app: 'iidp-user-prefer'
              }
              const res = await commonForm.request('getScheme', param) // 修改当前行数据
              if (res.error) {
                window.ELEMENT.Message.error(res.error.message)
              } else {
                window.ELEMENT.Message.success(Tech.$t('actionScope.deleteSuccess'))
                vm.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
              }
            }
            if (btnType == 'update') {
              let row = window.Tech._cloneDeep(value.scope.row)
              delete row.isDefault
              let param = {
                args: {
                  values: row
                },
                model: 'rbac_user_prefer',
                tag: 'master',
                service: 'updateOfScheme',
                app: 'iidp-user-prefer'
              }
              const res = await commonForm.request('getScheme', param) // 修改当前行数据
              if (res.error) {
                window.ELEMENT.Message.error(res.error.message)
              } else {
                window.ELEMENT.Message.success(Tech.$t('seniorTable.modifiedSuccessfully'))
                vm.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
              }
            }
            vm.$cmd.searchUserSchemeFn(vm) //重新请求表格数据
          }
        }
      ]
    }
  ]
}
