// 初始化卡片按钮组
function initBtnView(vm, btns, type) {
  btns?.map((item) => {
    const btnView = {
      ...item,
      type: 'button',
      options: { type: 'text' },
      value: item.name,
      style: {
        marginLeft: '5px'
      },
      bind_on_click: async (params) => {
        let res = await params.value
        res?.event?.stopPropagation()
        const currData = params.self?.$ds?.currData
        if (params.self?.data?.action === 'workFlow' && currData?.id) {
          jump(params.self, type, currData, item)
        }
      }
    }
    vm.app.updatePageNode(btnView, vm, () => {
      vm.data.items.push(btnView)
    })
  })
}

function jump(vm, type, currData, item) {
  if (item?.args && !item.args.app) {
    item.args.app = vm.$ds._metaParamsApp
  }
  if (item?.args) {
    item.args.ids = [currData?.id]
  }
  let menuVm = vm.$select('menu_meta_siderbar')
  let menuPath = menuVm.$cmd.getMenuPath({
    name: type,
    app: 'workflow'
  })
  if (!menuPath) return
  // 跳转
  vm.$cmd.meta.goTo(vm, {
    path: menuPath,
    query: {
      view: 'form',
      id: currData?.id,
      options: {
        args: item?.args || {},
        model: item.model,
        service: item.service,
        serviceMetaId: currData.serviceMetaId,
        row: currData,
        id: currData.id
      },
      originPagePath: menuVm.$cmd.getMenuPath({
        name: 'bpm',
        app: 'workflow'
      }),
      isApproval: true // 需要加载审批流的表单
    }
  })
}

const workflowCenterCard = {
  name: 'tech-my-workflow-center-card', // 组件名
  __block: true, // 标识为区块视图组件 固定配置 否则视图组件会失效
  view: {
    type: 'table-card',
    id: 'workflow-center-card-list',
    autoChildrenId: true,
    dataSource: {
      currData: {}
    },
    cardStyle: {
      background: '#f0f2f5',
      borderRadius: '10px',
      margin: '10px 0px 10px 10px'
    },
    // tableData: [],
    // bind_tableData: '${$ds.tableData?.data || []}',
    bind_tableData: {
      path: '$ds.tableData.data',
      // selector: '', //选择目标节点，绑定目标节点的dataSource，语法参考selector
      transform: (params) => {
        if (params.self.instance) {
          params.self.instance.tableData = params.value || []
        }
        return params.value || []
      }
    },
    created: (vm) => {},
    bind_on_click: (param) => {
      const { self: vm, value } = param
      vm.$ds.currData = value.data
      vm.$ds.currData.rowIndex = value.rowIndex
    },
    gutter: 20,
    spans: 12,
    items: [
      {
        type: 'container',
        className: 'wf_process_card_item',
        css: `.wf_process_card_item:hover{border: 1px solid #2783FE}`,
        style: {
          fontSize: '14px',
          borderRadius: '10px',
          height: '75px'
        },
        items: [
          {
            type: 'container',
            items: [
              {
                type: 'container',
                style: {
                  display: 'flex',
                  padding: '16px 13px 16px 10px',
                  cursor: 'pointer'
                },
                items: [
                  {
                    type: 'container',
                    style: {
                      width: '30px',
                      height: '30px',
                      minWidth: '30px',
                      background: '#ffffff',
                      borderRadius: '8px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center'
                    },
                    items: [
                      {
                        type: 'n-i',
                        className: 'iconfont icon-liucheng1',
                        css: `.wf_process_card_item .iconfont.icon-liucheng1 {
                          color: #AD053D;
                          font-size: 19px;
                        }`
                      }
                    ]
                  },
                  {
                    type: 'container',
                    style: {
                      marginLeft: '10px',
                      width: 'calc(100% - 40px)'
                    },
                    items: [
                      {
                        type: 'container',
                        style: {
                          width: '100%',
                          marginBottom: '4px',
                          overflow: 'hidden',
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'center'
                        },
                        items: [
                          {
                            type: 'text',
                            value: '',
                            style: {
                              display: 'inline-block',
                              overflow: 'hidden',
                              whiteSpace: 'nowrap',
                              textOverflow: 'ellipsis',
                              color: '#333333',
                              with: '70%',
                              maxWidth: '70%',
                              fontWeight: 700,
                              fontSize: '16px'
                            },
                            formatItem: (row, item) => {
                              item.value = row.title
                              return item
                            }
                          },
                          {
                            type: 'container',
                            style: {
                              float: 'right',
                              with: '25%'
                            },
                            items: [
                              {
                                type: 'text',
                                value: '',
                                style: {
                                  color: '#9c9c9c'
                                },
                                formatItem: (row, item) => {
                                  item.value = row.startTime?.slice(0, 10)
                                  return item
                                }
                              }
                            ]
                          }
                        ]
                      },
                      {
                        type: 'container',
                        style: {
                          color: '#666666',
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'center',
                          width: '100%'
                        },
                        items: [
                          {
                            type: 'container',
                            style: {
                              width: '70%',
                              overflow: 'hidden',
                              'white-space': 'nowrap',
                              'text-overflow': 'ellipsis'
                            },
                            items: [
                              {
                                type: 'text',
                                value: '',
                                style: {
                                  marginRight: '4px'
                                },
                                formatItem: (row, item) => {
                                  item.value = row.startUserId?.label || ''
                                  return item
                                }
                              },
                              {
                                type: 'text',
                                value: '|'
                              },
                              {
                                type: 'text',
                                value: '',
                                style: {
                                  marginLeft: '4px'
                                },
                                formatItem: (row, item) => {
                                  item.value = row.displayName
                                  return item
                                }
                              }
                            ]
                          },
                          // 按钮组
                          {
                            type: 'container',
                            items: [],
                            created: (vm) => {
                              vm.data.items = []
                              const btns =
                                vm.$ds.tableView?.data?.views?.[vm.$ds.__viewName]?.body?.buttons ||
                                []
                              initBtnView(vm, btns, vm.$ds.__type)
                            }
                          }
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        ],
        bind_on_click: (params) => {
          const vm = params.self
          const currData = vm?.$ds?.currData
          const btns = vm.$ds.tableView?.data?.views?.[vm.$ds.__viewName]?.body?.buttons
          const btn = btns.find((i) => i.action === 'workFlow')
          jump(vm, vm.$ds.__type, currData, btn)
        }
      }
    ]
  }
}

// 全部导入组件
export default workflowCenterCard
