export default {
  type: 'form',
  id: 'form_main_detail_top_common',
  className: 'detail_common_form',
  //   css: `
  //   .detail_common_form .tech-form-inner-container {
  //     width: 32%;
  //     display: inline-block;
  //     margin-right: 1.5%
  //   }
  //   .detail_common_form .tech-form-inner-container:nth-child(3n+3) {
  //     margin-right: 0
  //   }
  //  `, // ?.submitChanged
  submitChanged: false, // 是否开启只提交改变的字段
  changedFields: {}, // 改变过的字段对象 和里面的新旧值 格式例如 { fieldA: {oldValue: '', newValue: ''} }
  bind_on_setChangedFields: (params) => {
    // 监听那个字段改变的方法
    // console.log(' === bind_on_setChangedFields == ', params)
  },
  formConfig: {
    labelPosition: 'top',
    marginRight: '0.2rem',
    disabled: false,
    preview: false,
    previewChange: null
  },
  formChange: (vm, type, data) => {
    vm.$ds.isFormNotSave = true // 标识表单未保存
    vm.$cmd.syncFormSaveStatus(vm.app.page.getNode(vm.data.id))
    // 关联主表单数据 动态控制子表和子表列显示隐藏
    let formData = data
    if (vm?.$ds?.form) {
      formData = { ...vm.$ds.form, ...formData }
    }
    vm.$cmd.tabHideRelForm(vm, formData)
  },
  ds_config: {
    list: [
      {
        name: 'formSearch',
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {}
      },
      {
        name: 'formUpdate',
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {},
        reqAfter: (vm, res, config) => {
          if (res?.data !== undefined) {
            try {
              // 清理er表缓存
              let objNode = vm.$select(vm.$ds.idPre + 'form_main_detail_top_header')
              objNode?.$cmd?.clearErField(vm)
            } catch (e) {}
          }
          return res
        }
      },
      {
        name: 'bpmFormUpdate',
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {}
      },
      {
        name: 'lookup',
        type: 'meta',
        method: 'service',
        autoRequest: false,
        options: {}
      }
    ]
  },
  style: {
    background: '#fff',
    height: 'auto',
    scrollbarWidth: 'none',
    'grid-template-columns': 'auto auto auto',
    overflow: '',
    paddingBottom: '10px'
  },
  items: [],
  created: async (vm) => {
    let tableVM = vm.$select(vm.$ds.idPre + 'table_main')
    // form属性设置
    if (tableVM) {
      if (tableVM.$ds.tableView.data.views?.form?.body?.formConfig) {
        Object.assign(vm.data.formConfig, tableVM.$ds.tableView.data.views.form.body.formConfig)
      }

      vm.data.formConfig.labelPosition =
        tableVM.$ds.tableView.data.views?.form?.body?.formConfig?.labelPosition ||
        window.$tech?.formLabelPosition ||
        'top'
      // 表单预览状态展示
      if (window.$tech?.previewForm && vm.$ds.clickType == 'preview') {
        vm.data.formConfig.preview = true
        vm.data.formConfig.previewChange = vm.$cmd.meta.formFormat.previewChange
      }
    }
  },
  mounted: (vm) => {
    //初始关联主表单动态加载子表和子表列
    vm.instance.$nextTick(() => {
      if (vm?.$cmd?.tabHideRelForm) {
        vm.$cmd.tabHideRelForm(vm, vm.$ds.form)
      }
    })
  }
}
