export type MenuConfig = {
  name: string
  app: string
  model: string
  view: string
  filter?: Array<string>
  filterUser?: Array<string>
  product_line?: boolean | undefined
  product?: string | undefined
  isRebuildView?: boolean | undefined
}

export type WujieProps = {
  menuConfig: MenuConfig
  token: string
}

export type MicroConfig = {
  insert: 'provide' | 'self'
  notify: 'wujie' | 'origin'
  micro: 'wujie'
  api?: 'restful' | 'base'
}

export type WujieMenu = {
  app?: string
  display_name: string
  filer: Array<string> | null
  icon?: string | null
  id?: string
  model?: string
  name: string
  parent_ids?: string | MenuParentId
  product?: string
  product_line?: boolean
  sequence?: string
  url?: string | null
  view?: string
  path?: string | null
  isRebuildView?: boolean
}

type MenuParentId = {
  name: string
  args: {
    DisplayName: string
    IsDbIndex: string
    name: string
    relId: string
  }
}

export const hideDomIds = [
  'container_meta_sidebar',
  'container_meta_footer_content',
  'container_meta_header_top',
  'container_meta_menu',
  'menu_meta_siderbar'
]
